						if (l == 1)cost2 += cnt[1][m] * D[m][j];
						if (l == 2)cost2 += cnt[2][m] * D[m][k];
					}
				}
				if (cost2 < cost)cost = cost2;
			}
		}
	}
	cout << cost << endl;
}

