    ios::sync_with_stdio(false);

    int n,c;
    cin >> n >> c;

    int diff[30][30];
    for ( int i = 0; i < c; i++ )
        for ( int j = 0; j < c; j++ )
            cin >> diff[i][j];

    int x;
    for ( int i = 0; i < n; i++ )
        for ( int j = 0; j < n; j++ ){
            cin >> x;
