signed main() {
    int N, C;
    cin >> N >> C;

    int D[C][C], c[N][N];

    for(int i = 0; i < C; ++i){
        for(int j = 0; j < C; ++j){
            cin >> D[i][j];
        }
    }

    for(int i = 0; i < N; ++i){
        for(int j = 0; j < N; ++j){
            cin >> c[i][j];
        }
    }

    map<int, int> x, y, z; //斜め列の色の頻度分布

    int sx = 0, sy = 0, sz = 0;
    for(int i = 0; i < N; ++i){
        for(int j = 0; j < N; ++j){
            if((i + j) % 3 == 0){
                ++x[c[i][j] - 1];
                ++sx;
            }
            if((i + j) % 3 == 1){
                ++y[c[i][j] - 1];
                ++sy;
            }
            if((i + j) % 3 == 2){
                ++z[c[i][j] - 1];
                ++sz;
            }
        }
    }

    int ans = 1000 * N * N;
    for(int color = 0; color < C * C * C; ++color){
        int s = color % C, t = (color / C) % C, u = (color / (C * C)) % C;

        if(s == t | s == u | t == u){
            continue;
        }
        int cost = 0;

        for(int ic = 0; ic < C; ++ic){
            cost += x[ic] * D[ic][s] + y[ic] * D[ic][t] + z[ic] * D[ic][u];
        }
        if(ans > cost){
            ans = cost;
        }
    }
    cout << ans << endl;
}

