int main() {
  int N, C;
  cin >> N >> C;
  vector<vector<int>> D(C, vector<int>(C));
  vector<vector<int>> c(3, vector<int>(C));
  for (int i = 0; i < C; i++) {
    for (int j = 0; j < C; j++) {
      cin >> D[i][j];
    }
  }

  for (int i = 1; i <= N; i++) {
    for (int j = 1; j <= N; j++) {
      int tmp;
      cin >> tmp;
      tmp--;
      c[(i + j) % 3][tmp] += 1;
    }
  }

  int ans = 1000 * 500 * 500;
  for (int x = 0; x < C; x++) {
    for (int y = 0; y < C; y++) {
      for (int z = 0; z < C; z++) {
        if (x == y || y == z || z == x) continue;
        int cost = 0;
        for (int i = 0; i < C; i++) {
          cost += c[0][i] * D[i][x];
          cost += c[1][i] * D[i][y];
          cost += c[2][i] * D[i][z];
        }
        ans = min(ans, cost);
      }
    }
  }
  cout << ans << endl;
}

