signed main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int N, C;
    cin >> N >> C;
    vector<vector<int>> D(C, vector<int>(C));
    REP(i, C) REP(j, C) { cin >> D[i][j]; }
    vector<vector<int>> E(N, vector<int>(N));
    REP(i, N) REP(j, N) {
        cin >> E[i][j];
        E[i][j]--;
    }
    // 予め色を変更した違和感を計算
    vector<vector<int>> iwa(3, vector<int>(C));
    REP(c, C) REP(i, N) REP(j, N) { iwa[(i + j) % 3][c] += D[E[i][j]][c]; }

    // 異なる色を３種類決める
    int minv = 1e9;
    REP(c1, C) {
        REP(c2, C) {
            if (c1 == c2)
                continue;
            REP(c3, C) {
                if (c1 == c3 || c2 == c3)
                    continue;
                int sum = iwa[0][c1] + iwa[1][c2] + iwa[2][c3];
                minv = min(minv, sum);
            }
        }
    }
    cout << minv << endl;

    return 0;
}

