int dfs(int m, int color[],int sum=0, int answer=100000000, int depth=0) {
    if (depth == min(m,3)) {
        return min(sum,answer);
    }
    for (int k=0;k<m;k++) {
        bool next = false;
        for (int i=0;i<depth;i++) {
            if (k==color[i])
                next = true;
        }
        if (next) continue;

        color[depth] = k;

        if (sum+group[depth][k] < answer)
        answer = dfs(m,color,sum+group[depth][k],answer,depth+1);

    }
    return answer;
}

