                for (auto e : cmap[1]) {
                    if (e.first != j) {
                        diff += e.second * D[e.first][j];
                    }
                }
                for (auto e : cmap[2]) {
                    if (e.first != k) {
                        diff += e.second * D[e.first][k];
                    }
                }
                ans = min(ans, diff);
            }
        }
    }
