ll calc(ll n, ll c, vector<vector<ll> > d, vector<vector<ll> > vv, vector<int> out){
    ll res = 0;
    rep(i, n){
        rep(j, n){
            int tmp = i + j + 2;
            int change = out[tmp%3];
            // vv[i][j] -> change
            res += d[vv[i][j]-1][change];
        }
    }
    return res;
}

ll solve(ll n, ll c, vector<vector<ll> > d, vector<vector<ll> > vv, vector<int> out){
    if(out.size() == 3){
        return calc(n, c, d, vv, out);
    }
    ll res = LLINF;
    rep(i, c){
        bool ok = true;
        rep(j, out.size()){
            if(out[j] == i){
                ok = false;
                break;
            }
        }
        if(!ok) continue;
        out.push_back(i);
        res = min(res, solve(n, c, d, vv, out));
        out.erase(out.end()-1);
    }
    return res;
}

