int N, C;
int D[1010][1010], c[1010][1010];
int sum[5][35]; // sum[i][c]:=
                // (x+i)%3==iを満たすマスを,全てcに変更したときの総コスト

signed main() {
  cin >> N >> C;
  for (int i = 1; i <= C; i++) {
    for (int j = 1; j <= C; j++) {
