/* attention
    long longのシフト演算には気をつけよう
    タイポした時のデバッグが死ぬほどきつくなるので変数名は最低3字くらい使った方がいいかも
*/

int main(){
    int N, C; cin >> N >> C;
    int D[C+1][C+1];
    for(int i=1; i<=C; i++){
        for(int j=1; j<=C; j++) cin >> D[i][j];
    }

    map<int, int> zero, one, two;

    for(int i=1; i<=N; i++){
        for(int j=1; j<=N; j++){
            int c; cin >> c;
            if((i+j)%3 == 0) zero[c]++;
            if((i+j)%3 == 1) one[c]++;
            if((i+j)%3 == 2) two[c]++;
        }
    }

    ll ans = 25000000000;
    for(int i=1; i<=C; i++){
        for(int j=1; j<=C; j++){
            if(i == j) continue;
            for(int k=1; k<=C; k++){
                if(i == k || j == k) continue;

                //zeroの色をiに、oneの色をjに、twoの色をkにする
                ll tmp = 0;
                for(int color=1; color<=C; color++){
                    tmp += zero[color]*D[color][i];
                    tmp += one[color]*D[color][j];
                    tmp += two[color]*D[color][k];
                }

                ans = min(ans, tmp);
            }

        }
    }

    cout << ans << endl;
}

