int main() {
    int N, C;
    cin >> N >> C;
    vector<vector<int>> D(C, vector<int>(C));
    REP(i, 0, C) {
        REP(j, 0, C) {
            cin >> D[i][j];
        }
    }
    vector<vector<int>> c(N, vector<int>(N));
    REP(i, 0, N) {
        REP(j, 0, N) {
            cin >> c[i][j];
        }
    }
    vector<lli> memo[3];
    REP(i, 0, N) {
        REP(j, 0, N) {
            int ind = (i + j) % 3;
            memo[ind].push_back(c[i][j]);
        }
    }
    vector<vector<lli>> res(3, vector<lli>(C, 0));
    REP(i, 0, 3) {
        REP(j, 0, C) {
