                res[i][j] += D[memo[i][k] - 1][j];
            }
        }
    }
    lli ans = 1LL << 60;
    REP(i, 0, C) {
        REP(j, 0, C) {
            REP(k, 0, C) {
                if (i == j || j == k || k == i) {
