						res += d[c[i][j]-1][col];
					}
				}
				else{
					int i = n-1;
					int j = sum-i;
					for(; j < n; i--, j++){
						res += d[c[i][j]-1][col];
					}
				}
			} 
			//printf("    (%ld, %d)\n", res, col);
			list[mod].push_back(P(res, col));
