using namespace std ;

const int N = (int) 500 + 10 ;
const int inf = (int) 2e9 ;

int d[N][N] , color[N][N] ;
int n , c ;
vector< int > grp[4] ;
int cost[4][50] ;

int G( int g , int col ) {
    if( cost[g][col] != -1 ) return cost[g][col] ;
    int sum = 0 , len = (int) grp[g].size() ;
    for( int i = 0 ; i < len ; i++ ) {
        sum += d[ grp[g][i] ][ col ] ;
    }
    cost[g][col] = sum ;
    return sum ;
}

int F( int x , int y , int z ) {
    int sum = G(0 , x) + G(1 , y) + G(2 , z) ;
    return sum ;
}

int main(){
//    freopen("in.txt" , "r" , stdin ) ;
    memset( cost , -1 , sizeof(cost) ) ;
    scanf("%d %d" , &n , &c ) ;
    for( int i = 1 ; i <= c ; i++ ) {
        for( int j = 1 ; j <= c ; j++ ) {
            scanf("%d" , &d[i][j] ) ;
        }
    }
    for( int i = 1 ; i <= n ; i++ ) {
        for( int j = 1 ; j <= n ; j++ ) {
            scanf("%d" , &color[i][j] ) ;
            grp[(i + j) % 3].push_back( color[i][j] ) ;
        }
    }
    int ans = inf ;
    for( int i = 1 ; i <= c ; i++ ) {
        for( int j = 1 ; j <= c ; j++ ) {
            for( int k = 1 ; k <= c ; k++ ) {
                if( i == j || i == k || j == k ) continue ;
                ans = min( ans , F(i , j , k) ) ;
            }
        }
    }
    printf("%d\n" , ans ) ;
    return 0 ;
}

