int main() {
    int n, c;
    cin >> n >> c;

    vector<vector<int>> costs(c, vector<int>(c));
    rep(i, c) rep(j, c) cin >> costs[i][j];

    vector<vector<int>> grid(n, vector<int>(n));
    rep(i, n) rep(j, n) cin >> grid[i][j];
