    vector<vector<int>> use(c, vector<int>(3));

    rep(i, n) {
        rep(j, n) {
            int p = (i + j) % 3;
            int ci = grid[i][j];
            use[ci][p]++;
        }
    }

    auto check = [&](int d, int e, int f) {
        ll ans = 0;
        for (int i = 0; i < c; i++) {
            ll now = use[i][0] * costs[i][d];
            ans += now;
        }
        for (int i = 0; i < c; i++) {
            ll now = use[i][1] * costs[i][e];
            ans += now;
        }
        for (int i = 0; i < c; i++) {
            ll now = use[i][2] * costs[i][f];
            ans += now;
        }
        return ans;
    };

    ll ans = INF;

    for (int d = 0; d < c; d++) {
        for (int e = 0; e < c; e++) {
            for (int f = 0; f < c; f++) {
                if (d == e) continue;
                if (e == f) continue;
                if (f == d) continue;
                ll now = check(d, e, f);
                cmin(ans, now);
            }
        }
    }

