    REP(i, 3) {
      col[i] = x % C;
      x /= C;
    }
    if (col[0] == col[1] || col[1] == col[2] || col[2] == col[0]) continue;
    ll t = 0;
    REP(i, N) REP(j, N) t += D[c[i][j] - 1][col[(i + j) % 3]];
    ans = min(ans, t);
  }
  io.writeln(ans);
  return 0;
}

