  int N,C; cin >> N >> C;
  vvi d(C, vi(C));
  vvi c(N, vi(N));
  rep(i,C) rep(j, C) cin >> d[i][j];
  rep(i,N) rep(j, N) cin >> c[i][j];
  vector<map<int, int>> mps(3);
  rep(y, N) rep(x, N) {
    int md = (x+y+2) % 3;
    int color = c[y][x];
    mps[md][color]++;
  }
  int ans = INF;
