            --before;
            int after = -1;
            if (mp == 0) after = i;
            if (mp == 1) after = j;
            if (mp == 2) after = k;
            num += cnt * d[before][after];
          }
        }
        chmin(ans, num);
      }
    }
  }
  cout << ans << endl;
