void solve()
{
    ll N, C;
    cin >> N >> C;
    for1(i, C)
    {
        for1(j, C) { cin >> D[i][j]; }
    }
    for1(i, N)
    {
        for1(j, N)
        {
            cin >> c[i][j];
            c[i][j]--;
        }
    }
    for1(i, N)
    {
        for1(j, N)
        {
            ll mod = (i + j) % 3;
            cnt[mod][c[i][j]]++;
        }
    }
    ll ans = INF;
    for1(c1, C)
    {
        ll sc1 = 0;
        for1(i1, C) { sc1 += cnt[0][i1] * D[i1][c1]; }
