// mod0の色、mod1の色、mod2の色を決め打った時の合計コスト
int solve(int zero, int one, int two) {
	int ret = 0;
	for (int ci = 1; ci <= C; ci++) {
		ret += D[ci-1][zero-1] * X[0][ci];
	}
	for (int ci = 1; ci <= C; ci++) {
		ret += D[ci-1][one-1] * X[1][ci];
	}
	for (int ci = 1; ci <= C; ci++) {
		ret += D[ci-1][two-1] * X[2][ci];
	}

	return ret;
}

