namespace UnionFind {
	const int MAX_N = 1010101;
	int par[MAX_N];//N番目のnodeの親nodeのindex
	int Rank[MAX_N];//木の深さ

	void init(int n) {
		REP(i, n) {
			par[i] = i;//rootの親は自分に設定しておくことでrootの判別ができる
			Rank[i] = 0;
		}
	}

	//xのrootを求める
	int find(int x) {
		//root
		if (par[x] == x) {
			return x;
		}
		else {
			return par[x] = find(par[x]);//ここで親を貼り直している
		}
	}

	//木の統合
	void unite(int x, int y) {
		//x = find(x), y = find(y);//親ノードの検出
		if (x == y) { return; }//何もしない

							   //併合の際に２つの木の高さが異なれば高さの小さいものが大きい物の根へと辺をはる
		if (Rank[x] < Rank[y]) {
			par[x] = y;
			//Rank[y]のほうが深いのでRankの更新は行わなくて良い
		}
		else {
			par[y] = x;
			//２つの根が同じ深さの場合は１つの根がもうひとつの根につくわけなので深さは1増える
			if (Rank[x] == Rank[y]) { Rank[x]++; }
		}
		/*if (vact[x] > vact[y]) {
			par[y] = x;
		}
		else {
			par[x] = y;
		}*/
	}

	bool same(int x, int y) {
		return find(x) == find(y);
	}
}


class matrix : public vector< vector<int> > {
private:
	int tate_, yoko_;
public:
	matrix(const int tate__, const int yoko__) {
		assert(tate__ > 0); assert(yoko__ > 0);
		resize(tate__);
		for (size_t i = 0; i < size(); i++) { (*this)[i].resize(yoko__); }
		tate_ = tate__; yoko_ = yoko__;
	}
	matrix() {};
	int tate()const { return tate_; }
	int yoko()const { return yoko_; }
	void resizematrix(const int tate__, const int yoko__) {
		assert(tate__ > 0); assert(yoko__ > 0);

		resize(tate__);
		for (size_t i = 0; i < size(); i++) {
			(*this)[i].resize(yoko__);
		}
		tate_ = tate__; yoko_ = yoko__;
	}
	void setone() {
		for (int i = 0; i<tate(); i++)  for (int j = 0; j < yoko(); j++) { (*this)[i][j] = 1; }
	}
	void setzero() {
		for (int i = 0; i<tate(); i++) for (int j = 0; j < yoko(); j++) { (*this)[i][j] = 0; }
	}
	void setchar(char a) {
		for (int i = 0; i<tate(); i++) for (int j = 0; j < yoko(); j++) { (*this)[i][j] = a; }
	}
};
inline std::ostream & operator<<(std::ostream & os, const matrix & m)
{
	for (int j = 0; j < m.tate(); j++) {
		os << "[";
		for (int i = 0; i < m.yoko(); i++) {
			//os.std::setw(2);

			os <<m[j][i];
		}
		os << "]" << endl;
	}
	return os;
}
int main() {

	int N, C_;
	matrix D;
	matrix C;
	cin >> N >> C_;
	D.resizematrix(C_, C_);
	C.resizematrix(N, N);
	vector<PII > samec[3];

	REP(i, C_)REP(j, C_) {

		cin >> D[i][j];
	}
	REP(i, N)REP(j, N) {
		cin >> C[i][j];
		C[i][j]--;
		samec[(i + j) % 3].push_back({ i,j });
	}
	LL min_iwakan = 100000000;

	vector<int> aa;
	REP(i, C_) {
		aa.push_back(i);
	}

	do {
		LL iwakan = 0;

		REP(i, 3) {
			for (auto a : samec[i]) {
				if (C[a.first][a.second] != aa[i]) {
					iwakan += D[C[a.first][a.second]][aa[i]];
				}
			}
		}
