int now[3];
bool visited[35];

int Solve(int turn){
  if (turn == 3){
    ll res = 0;
    for (int i = 0; i < N; i++){
      for (int j = 0; j < N; j++){
        res += D[c[i][j]][now[(i+j) % 3]];
      }
    }
    ans = min(res, ans);
    return 0;
  }

  for (int i = 0; i < C; i++){
    if (visited[i]) continue;
    now[turn] = i; visited[i] = true;
    Solve(turn + 1);
    visited[i] = false;
  }
  return 0;
}


