#include <bits/stdc++.h>

int main() {
  int n, c;
  std::cin >> n >> c;
  std::vector<std::vector<uint16_t>> d(c, std::vector<uint16_t>(c));

  for (int i = 0; i < c; i++) {
    for (int j = 0; j < c; j++) {
      std::cin >> d[i][j];
    }
  }

  std::vector<int> c_g[3];
  c_g[0] = std::vector<int>(c, 0);
  c_g[1] = std::vector<int>(c, 0);
  c_g[2] = std::vector<int>(c, 0);

  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= n; j++) {
      int tmp;
      std::cin >> tmp;
      c_g[(i + j) % 3][tmp - 1]++;
    }
  }

  uint64_t cost = 250000000;

  for (int i = 0; i < c; i++) {
    for (int j = 0; j < c; j++) {
      for (int k = 0; k < c; k++) {
        if (i == j || j == k || k == i) {
          continue;
        } else {
          uint64_t cost_now = 0;
          for (int l = 0; l < c; l++) {
            cost_now += d[l][i] * c_g[0][l];
          }
          for (int l = 0; l < c; l++) {
            cost_now += d[l][j] * c_g[1][l];
          }
          for (int l = 0; l < c; l++) {
            cost_now += d[l][k] * c_g[2][l];
          }
          cost = std::min(cost, cost_now);
        }
      }
    }
  }

  std::cout << cost << std::endl;
  return 0;
}

