class WarshallFloyd {
private:
    const int n;
    vector<vector<int>> d;
public:
    WarshallFloyd(int _n) : n(_n), d(_n, vector<int>(_n)) {
        rep(i, n) rep(j, n) {
            d[i][j] = (i == j ? 0 : INF);
        }
    }
    // directed
    void setDist(int i, int j, int c) {
        d[i][j] = c;
    }
    int getDist(int i, int j) {
        return d[i][j];
    }
    void calc() {
        rep(k, n) rep(i, n) rep(j, n) {
            d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
        }
    }
};

ll N, C, X, S, M = INF, W[50][50], A[50][3], D[50][3];
signed main() {
    cin >> N >> C;
    WarshallFloyd W(C);
    rep(i, C) rep(j, C) {
        cin >> W[50][50];
    }
    W.calc();
    rep(i, N) rep(j, N) {
        cin >> X;
        A[X - 1][(i + j) % 3]++;
    }
    rep(i, C) rep(j, C) rep(k, 3) {
        D[j][k] += A[i][k] * W[i][j];
    }
    rep(i, C) rep(j, C) rep(k, C) {
        S = 0;
        if((i - j) * (j - k) * (k - i)) {
            S += D[i][0];
            S += D[j][1];
            S += D[k][2];
            if(S < M) M = S;
        }
    }
    cout << M << endl;
}

