			}
			if (temp == 0) {
				count = count + VALUE(PAN[i][j], B);
			}
			if (temp == 1) {
				count = count + VALUE(PAN[i][j], C);
			}
		}
	}
	return count;
}


void CALCULMIN() {
	int temp;
	for (int i = 1; i <= C; i++) {
		for (int j = 1; j <= C; j++) {
