    rep(j,C) {
      if ( i == j ) continue;
      ll D1 = f(1,j);
      rep(k,C) {
        if ( i == j || j == k || k == i ) continue;
        ll D2 = f(2,k);
        ans = std::min(ans, D0+D1+D2);
      }
    }
  }
  std::cout << ans << std::endl;
  return 0;
}

