using namespace std;

uint16_t N, C;

uint16_t D[30][30];

typedef uint16_t Color;

class ColorCounter : public map<Color, uint32_t> {
public:
  void add(uint16_t color) {
    if (this->find(color) == this->end())
      this->emplace(color,1);
    else
      this->at(color)++;
  }

  void print() {
    for (auto x : *this)
      cerr << x.first << ":" << x.second << endl;
  }

};

class ColorChangeCost : public map<Color, uint32_t> {
public:
  ColorChangeCost(ColorCounter counter) {
    for (Color c=0; c<C; ++c) {
      this->emplace(c,0);
    }

    for (auto& color_dist : *this) {
      for (auto color_count : counter) {
	Color origin = color_count.first;
	uint32_t cost_per_tile = D[origin][color_dist.first];
	uint32_t cost_all = cost_per_tile *= color_count.second;
	color_dist.second += cost_all;
      }
      //cerr << "paint to " << color_dist.first << ":" << color_dist.second << endl;
    }
  }

  // std::pair<Color,uint32_t> min_cost(Color exception) {
