      uint16_t d;
      cin >> d;
      D[c1][c2] = d;
    }
  }

  uint16_t c[500][500];
  ColorCounter count_color[3];

  for (uint16_t n1=0; n1<N; ++n1) {
    for (uint16_t n2=0; n2<N; ++n2) {
      uint16_t cc;
      cin >> cc;
      --cc;
      c[n1][n2] = cc;
      uint16_t residue = (n1+n2)%3;
      count_color[residue].add(cc);
    }
  }

  // for (auto cc: count_color) {
  //   //cc.print();
  //   //cerr << endl;
  // }

  //cerr << endl;
  ColorChangeCost* change_costs[3];
  for (int r=0; r<3; ++r) {
    change_costs[r] = new ColorChangeCost(count_color[r]);
    //cerr << endl;
