    int tmp=(i-color[0])/C;
    color[1]=tmp%C;
    int tmptmp=(tmp-color[1])/C;
    color[2]=tmptmp%C;
    if(color[0]==color[1] || color[1]==color[2] || color[2]==color[0]) return INF;
    int ret=0;
    for(int t=0;t<3;t++){
        for(int c=0;c<C;c++){
            ret += Wall[t][c]*Cost[c][color[t]];
        }
    }
    return ret;
}

