int main(int argc, char* argv[])
{
  std::cin.tie(nullptr);
  std::ios::sync_with_stdio(false);

  ll N, C;
  std::cin >> N >> C;

  // ある色からある色への距離
  std::vector< std::vector<ll> > dist(C, std::vector<ll>(C, 0LL));
  for (ll y = 0; y < C; y++) {
    for (ll x = 0; x < C; x++) {
      std::cin >> dist[y][x];
    }
  }

  std::vector< std::vector<ll> > grid(N, std::vector<ll>(N, 0LL));
  for (ll y = 0; y < N; y++) {
    for (ll x = 0; x < N; x++) {
      ll c;
      std::cin >> c;
      grid[y][x] = c - 1;
    }
  }

  // グループ毎に色を変えるコストを算出
  std::vector< std::vector<ll> > cost(3, std::vector<ll>(C, 0LL));
  for (ll y = 0; y < N; y++) {
    for (ll x = 0; x < N; x++) {
      ll type = (y + x) % 3;
      for (ll color = 0; color < C; color++) {
	cost[type][color] += dist[grid[y][x]][color];
      }
    }
  }

  ll ans = INF;
  for (ll i = 0; i < C; i++) {
    for (ll j = 0; j < C; j++) {
      for (ll k = 0; k < C; k++) {
	if (i == j || j == k || k == i) continue;
	ll all_cost = cost[0][i] + cost[1][j] + cost[2][k];
	ans = std::min(ans, all_cost);
      }
    }
  }

  print(ans);

  return 0;
}

