		}
	}
	for (i = 1; i <= c; i++) {    
		x = 0;
		for (j = 1; j <= c; j++) {
			x += t[0][j] * d[j][i];
		}
		for (j = 1; j <= c; j++) {    //枚举余数为1统一变成颜色j,其代价为y 
