		for (int j = 0; j < C; j++) {
			int karint;
			cin >> karint; kari.push_back(karint);
		}
		D.push_back(kari);
	}
	for (int i = 1; i <= N; i++) {
		for (int j = 1; j <= N; j++) {
			int x; cin >> x;
			if ((i + j) % 3 == 1) {
				amari1[x]++;
			}
			else if ((i + j) % 3 == 2) {
				amari2[x]++;
			}
			else {
				amari3[x]++;
			}
		}
	}

	int miniwa = 250000001;

	for (int i = 1; i <= C; i++) {
		for (int j = 1; j <= C; j++) {
			for (int k = 1; k <= C; k++) {
				//まず、ijkは相異なるチェック
				if (i == j)continue;
				if (i == k)continue;
				if (j == k)continue;
				//ijkセットにかえるときの違和感チェック
				//i = 1,j = 2,k = 3担当
				int iwa = 0;

				for (int x = 1; x <= C; x++) {
					iwa += D[x - 1][i - 1] * amari1[x];
					iwa += D[x - 1][j - 1] * amari2[x];
					iwa += D[x - 1][k - 1] * amari3[x];
				}

				//miniwa 更新
				miniwa = min(iwa, miniwa);
			}
		}
	}

	cout << miniwa;
	return 0;
}

