i64 f(const vector<i64>& cnt, i64 c) {
    i64 res = 0;
    REP(i, NC) {
        i64 k = cnt[i];
        res += k * D[i][c];
    }
    return res;
}

void solve() {
    vector<vector<i64>> cnts(3, vector<i64>(NC, 0));

    REP(i, N) REP(j, N) {
        i64 idx = (i+j) % 3;
        i64 c   = C[i][j];
        ++cnts[idx][c];
    }
    DBG(cnts);

