    REP(c1, NC) {
        REP(c2, NC) {
            if(c2 == c1) continue;
            REP(c3, NC) {
                if(c3 == c1) continue;
                if(c3 == c2) continue;

                i64 x = 0;
                x += f(cnts[0], c1);
                x += f(cnts[1], c2);
                x += f(cnts[2], c3);
                chmin(ans, x);
            }
        }
    }

    PRINTLN(ans);
}

