	int D[C][C], c[N][N], r1[C], r2[C], r0[C];
	for(int i=0; i<C; i++){
		for(int j=0; j<C; j++){
			cin >> D[i][j];
		}
        r0[i] = 0, r1[i] = 0, r2[i] = 0;
	}
	for(int i=0; i<N; i++){
		for(int j=0; j<N; j++){
			cin >> c[i][j];
			for(int k=0; k<C; k++){
				if((i+j)%3 == 0){
					r0[k] += D[c[i][j] - 1][k];
				}
				if((i+j)%3 == 1){
					r1[k] += D[c[i][j] - 1][k];
				}
				if((i+j)%3 == 2){
					r2[k] += D[c[i][j] - 1][k];
				}
			}
		}
	}
	int min = 1000000000;
	for(int i=0; i<C; i++){
		for(int j=0; j<C; j++){
			if(i != j){
				for(int k=0; k<C; k++){
					if(i != k && j != k){
						if(min > r0[i] + r1[j] + r2[k]){
							min = r0[i] + r1[j] + r2[k];
						}
					}
				}
			}
		}
	}
	cout << min << endl;
	return 0;
}

