map<int, int> GetMin(const vector<int>& Nx, const vector<vector<int>>& Dv){
    map<int, int> minList;
    for(int c = 1; c<= Dv.size(); c++){
        auto d = 0;
        for(auto c1 : Nx){
            d += Dv[c1-1][c-1];
        }
        minList[c] = d;
    }
    return minList;
}

int GetMin(const vector<vector<int>>& Dv, const vector<vector<int>>& Cv){
    if(Cv.size()==1) return 0;
    vector<int> N0, N1,N2;
    for(size_t i=0; i<Cv.size(); i++){
        for(size_t j=0; j<Cv.size(); j++){
            if((i+j)%3 == 0) N0.push_back(Cv[i][j]);
            if((i+j)%3 == 1) N1.push_back(Cv[i][j]);
            if((i+j)%3 == 2) N2.push_back(Cv[i][j]);
        }
    }
    auto l0 = GetMin(N0, Dv);
    auto l1 = GetMin(N1, Dv);
    auto l2 = GetMin(N2, Dv);
    int dmin = INT_MAX;
    for(auto c0 : l0){
        for(auto c1 : l1){
            if(c0.first == c1.first) continue;
            for(auto c2 : l2){
                if(c0.first == c2.first) continue;
                if(c1.first == c2.first) continue;
                auto d = c0.second + c1.second + c2.second;
                if(d < dmin) dmin = d;
            }
        }
    }
    return dmin;
}

