	for(int i = 0; i < C; i++)
	{
		for(int j = 0; j < C; j++)
		{
			std::cin >> D[i][j];
		}
	}
	std::vector<std::vector<int>>color_num(3, std::vector<int>(C, 0));
	std::vector<std::vector<int>>c(N, std::vector<int>(N));
	for(int i = 0; i < N; i++)
	{
		for(int j = 0; j < N; j++)
		{
			std::cin >> c[i][j];
			color_num[(i + j) % 3][c[i][j] - 1]++;
		}
	}

	int minimum_cost = 100000000;
	for(int i = 0; i < C; i++)
	{
		for(int j = 0; j < C; j++)
		{
			if(i == j)continue;
			for(int k = 0; k < C; k++)
