	mint factMod(lint n) {
		if (n == 0)
		{
			return 1;
		}
		mint ans = 1;
		while (n > 1) {
			ans *= n;
			n--;
		}
		return ans;
	}

	mint powMod(mint x, lint y)
	{
		if (x.n <= 1)
		{
			return x;
		}
		if (y == 0)
		{
			return 1;
		}
		else if (y == 1)
		{
			return x;
		}
		else if (y % 2 == 0)
		{
			mint tmp = powMod(x, y / 2);
			return tmp * tmp;
		}
		else
		{
			mint tmp = powMod(x, y / 2);
			return tmp * tmp * x;
		}
	}

	mint modinv(mint n)
	{
		return powMod(n, mod - 2);
	}

