int VALUE(int oricolor, int aftercolor) {
	return COLOR[oricolor - 1][aftercolor - 1];
}

int CALCUL(int A, int B, int C) {
	int count = 0; int temp;
	for (int i = 0; i < N; i++) {
		for (int j = 0; j < N; j++) {
			temp = (i + j) % 3;
			if (temp == 2) {
				count = count + VALUE(PAN[i][j], A);
			}
			if (temp == 0) {
				count = count + VALUE(PAN[i][j], B);
			}
			if (temp == 1) {
				count = count + VALUE(PAN[i][j], C);
			}
		}
	}
	return count;
}


void CALCULMIN() {
	int temp;
	for (int i = 1; i <= C; i++) {
		for (int j = 1; j <= C; j++) {
			for (int z = 1; z <= C; z++) {
				if (i == j || j == z) {
					continue;
				}
				if (z == i) {
					continue;
				}
				temp = CALCUL(i, j, z);
				if (min > temp) {
					min = temp;
				}
			}
		}
	}
}

