		rep(i, 3) {
			cnt[i].resize(C);
			rep(c, C) cnt[i][c] = { c, 0 };
		}
		rep(y, N) rep(x, N) {
			int moded_n = (y + x) % 3;
			if (c[y][x] < 0) continue;
			cnt[moded_n][c[y][x]].cnt += 1;
		}
		//rep(i, 3) {
