		//		c.print();
		//	}
		//	cerr << endl;
		//}
		rep(i, 3) {
			cost[i].resize(C);
			rep(c, C) cost[i][c].cnt = 0;
			rep(c, C) cost[i][c].c = c;
			rep(c, C) rep(c2, C) {
				cost[i][c2].cnt += D[c][c2] * cnt[i][c].cnt;
			}
		}
		rep(i, 3) {
			sort(all(cost[i]));
			for (auto& c : cost[i]) {
				c.print();
			}
			cerr << endl;
		}
		bool used[35] = {};
		set<int> yet;
		rep(i, 3) {
			yet.insert(i);
		}
		int res = 0;
		while (yet.size() != 0) {
			vector<int> hoping[35];
			for (auto& v : yet) {
				hoping[cost[v][0].c].push_back(v);
			}
			bool f = true;
			rep(c, C) {
				dump(c + 1);
				dumpl(hoping[c].size());
				if (hoping[c].size() < 2) continue;
				f = false;
				auto best = hoping[c][0];
				for (auto& v : hoping[c]) {
					auto f = [&](int v2) {
						return cost[v2][0].cnt - cost[v2][1].cnt;
					};
					if (f(v) < f(best)) {
						best = v;
					}
				}
				dump(best);
				dumpl(cost[best][0].cnt);
				res += cost[best][0].cnt;
				used[c] = true;
				yet.erase(best);
				for (auto& v : hoping[c]) {
					cost[v].erase(cost[v].begin());
				}
			}
			if (f == true) {
				for (auto& v : yet) {
					dumpl(cost[v][0].c);
					res += cost[v][0].c;
				}
				break;
			}
		}
		cout << res << endl;
	}

};

