int main(){
    int N, C;
    cin >> N >> C;
    ll D[30][30];
    int x[500][500];
    for(int i = 0; i < C; i++){
        for(int j = 0; j < C; j++){
            cin >> D[i][j];
        }
    }

    for(int i = 0; i < N; i++){
        for(int j = 0; j < N; j++){
            cin >> x[i][j];
            x[i][j]--;
        }
    }

    ll res = LONG_LONG_MAX;

    ll cost[3][30];
    for(int j = 0; j < 3; j++){
        for(int i = 0; i < C; i++){
            ll cost_sum = 0;
            for(int k = 0; k < N; k++){
                for(int l = 0; l < N; l++){
                    if((k+l) % 3 == j){
                        cost_sum += D[x[k][l]][i];
                    }
                }
            }
            cost[j][i] = cost_sum;
        }
    }

    for(int i = 0; i < C*C*C; i++){
        int c1 = i % C;
        int c2 = (i / C) % C;
        int c3 = (i / (C * C)) % C;
        if(c1 == c2 || c2 == c3 || c3 == c1){
            continue;
        }

        res = min(res, cost[0][c1]+cost[1][c2]+cost[2][c3]);
    }

    cout << res << endl;



    return 0;

}

