int main() {
	ll N;
	scanf("%lld", &N);
	ll C;
	scanf("%lld", &C);
	vector<vector<ll>> D(C, vector<ll>(C, 0));
	for (ll j = 0; j < C; j++) {
		for (ll i = 0; i < C; i++) {
			scanf("%lld", &D[j][i]);
		}
	}
	vector<vector<ll>> c(N, vector<ll>(N, 0));
	for (ll j = 0; j < N; j++) {
		for (ll i = 0; i < N; i++) {
			scanf("%lld", &c[j][i]);
		}
	}

	vector<vector<ll>> count(3, vector<ll>(C, 0));
	for (ll j = 0; j < N; j++) {
		for (ll i = 0; i < N; i++) {
			count[(i + j) % 3][c[j][i] - 1]++;
		}
	}

	vector<vector<ll>> cost(3, vector<ll>(C, 0));
	for (ll iGroup = 0; iGroup < 3; iGroup++) {
		for (ll iDstColor = 0; iDstColor < C; iDstColor++) {
			for (ll iSrcColor = 0; iSrcColor < C; iSrcColor++) {
				cost[iGroup][iDstColor] += D[iSrcColor][iDstColor] * count[iGroup][iSrcColor];
			}
		}
	}

	ll result = INF;

	vector<int> dstColor(3, 0);
	while (true) {
		dstColor[0]++;
		if (dstColor[0] >= C) {
			dstColor[0] = 0;
			dstColor[1]++;
			if (dstColor[1] >= C) {
				dstColor[1] = 0;
				dstColor[2]++;
			}
		}

		if (dstColor[0] == C - 1 && dstColor[1] == C - 1 && dstColor[2] == C - 1) {
			break;
		}

		if (dstColor[0] == dstColor[1] || dstColor[0] == dstColor[2] || dstColor[1] == dstColor[2]) {
			continue;
		}

		ll totalCost = cost[0][dstColor[0]] + cost[1][dstColor[1]] + cost[2][dstColor[2]];

		result = min(result, totalCost);
	}

	printf("%lld\n", result);
}


