#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int N, C;
const int MAX_N = 500 + 10;
const int MAX_C = 30 + 10;
int D[MAX_C][MAX_C];
int c[MAX_N][MAX_N];

int main() {
    cin >> N >> C;
    for (int i = 0; i < C; i++) {
        for (int j = 0; j < C; j++) {
            cin >> D[i][j];
        }
    }
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            cin >> c[i][j];
        }
    }

    pair<int, int> zero[C], one[C], two[C];
    for (int i = 0; i < C; i++) { 
        zero[i].second = i;
        one[i].second = i;
        two[i].second = i;            
    }

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            if ((i+j) % 3 == 0) {
                for (int k = 0; k < C; k++) {
                    zero[k].first += D[c[i][j] - 1][k];
                }
            }
            else if ((i+j) % 3 == 1) {
                for (int k = 0; k < C; k++) {
                    one[k].first += D[c[i][j] - 1][k];
                }
            }
            else {
                for (int k = 0; k < C; k++) {
                    two[k].first += D[c[i][j] - 1][k];
                }
            }
        }
    }

    sort(zero, zero+C);
    sort(one, one+C);
    sort(two, two+C);

    int ans = 1.0e9;
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            for (int k = 0; k < 3; k++) {
                if (zero[i].second != one[j].second &&
                    one[j].second != two[k].second &&
                    two[k].second != zero[i].second) {

                    ans = min(ans, zero[i].first + one[j].first + two[k].first);    
                }
            }
        }
