const double EPS = 1e-9;

const int DX[]={1,0,-1,0},DY[]={0,-1,0,1};

vector<pair<LL, int> > memo[3];

LL solve(set<int> use_idx, LL cost){
    if(use_idx.size() == 3) {
        return cost;
    }

    LL ans = INF;
    REP(i, memo[use_idx.size()].size()){
        LL score = memo[use_idx.size()][i].first;
        int idx = memo[use_idx.size()][i].second;
        if(use_idx.count(idx) == 1) continue;

        use_idx.insert(idx);
        ans = min(ans, solve(use_idx, cost + score));
        use_idx.erase(idx);
    }

    return ans;
}

