// 1≤k≤n≤10^7
class CombLib {
private:
	int mMax, mMod;
	vector<ll> fac, finv, inv;
public:
	CombLib(int modNum = 1000000007, int maxSize = 510000) {
		mMax = maxSize, mMod = modNum;
		fac = vector<ll>(maxSize);
		finv = vector<ll>(maxSize);
		inv = vector<ll>(maxSize);
	    fac[0] = fac[1] = 1;
    	finv[0] = finv[1] = 1;
    	inv[1] = 1;
    	for (int i = 2; i < mMax; i++){
	        fac[i] = fac[i - 1] * i % mMod;
    	    inv[i] = mMod - inv[mMod%i] * (mMod / i) % mMod;
        	finv[i] = finv[i - 1] * inv[i] % mMod;
    	}
	}

	ll calc(int n, int k){
    	if (n < k) return 0;
    	if (n < 0 || k < 0) return 0;
    	return fac[n] * (finv[k] * finv[n - k] % mMod) % mMod;
	}
};

struct UnionFind {
  vector<int> data;
  UnionFind(int size) : data(size, -1) { }
  bool unionSet(int x, int y) {
    x = root(x); y = root(y);
    if (x != y) {
      if (data[y] < data[x]) swap(x, y);
      data[x] += data[y]; data[y] = x;
    }
    return x != y;
  }
  bool findSet(int x, int y) {
    return root(x) == root(y);
  }
  int root(int x) {
    return data[x] < 0 ? x : data[x] = root(data[x]);
  }
  int size(int x) {
    return -data[root(x)];
  }
};

ll calc(ll n) {
	if (n < 0) return INT64_MAX;
	if (n < 6) return n;
	ll ans = INT64_MAX;
	ll cnt = 0;
	ll m = 6;
	while (m * 6 <= n) {
		chmin(ans, calc(n - m));
		m *= 6;
	}
	m = 9;
	while (m * 9 <= n) {
		chmin(ans, calc(n - m));
		m *= 9;
	}
	return ans;
}

