    rep(c, C){
      // 塗る色を c に決めた時の違和感の総和を計算
      // 領域 k について、最初に塗られている色 j の数はcolor[k][j]に格納されている
      rep(j, C) dif[k][c] += (ll)color[k][j] * (ll)D[j][c];
    }
  }
  ll res = numeric_limits<ll>::max();
  rep(i, C){
    rep(j, C){
      if (i == j) continue;
      rep(k, C){
        if (i == k || j == k) continue;
        ll buf = dif[0][i] + dif[1][j] + dif[2][k];
        chmin(res, buf);
      }
    }
  }
  cout <<res <<endl;
}

