	vector<vi> c(n, vi(n));
	REP(i, n) REP(j, n) cin >> c[i][j];
	vector<vi> col(3, vi(C + 1));
	REP(i, n + n - 1) {
		for (int j = max(i - n + 1, 0); j <= min(i, n - 1); ++j) {
			col[i % 3][c[j][i - j]]++;
		}
	}
