const int MAX_N = 505, MAX_COLOURS = 35;
int number[MAX_N][MAX_N], cost[MAX_COLOURS][MAX_COLOURS];

int all_different(int x, int y, int z)
{
    return (x != y && y != z && z != x);
}

int cost_to_repaint(int colour_for_0, int colour_for_1, int colour_for_2, int n, int no_of_colours)
{
    int total_cost = 0;

    for(int i = 1; i <= n; i++)
    {
        for(int j = 1; j <= n; j++)
        {
            int old_colour = number[i][j];
            int new_colour;

            switch( (i+j)%3 )
            {
                case 0: new_colour = colour_for_0; break;
                case 1: new_colour = colour_for_1; break;
                case 2: new_colour = colour_for_2; break;
            }

            total_cost += cost[old_colour][new_colour];
        }
    }

    return total_cost;
}

int main()
{
    int n, no_of_colours;
    scanf("%d %d", &n, &no_of_colours);

    for(int i = 1; i <= no_of_colours; i++)
        for(int j = 1; j <= no_of_colours; j++)
            scanf("%d", &cost[i][j]);

    for(int i = 1; i <= n; i++)
        for(int j = 1; j <= n; j++)
            scanf("%d", &number[i][j]);

    const int oo = 1e9;
    int minimum_cost = oo;

    for(int c0 = 1; c0 <= no_of_colours; c0++)
    {
        for(int c1 = 1; c1 <= no_of_colours; c1++)
        {
            for(int c2 = 1; c2 <= no_of_colours; c2++)
            {
                if(all_different(c0, c1, c2))
                    minimum_cost = min(minimum_cost, cost_to_repaint(c0, c1, c2, n, no_of_colours));
            }
        }
    }

    printf(minimum_cost >= oo ? "-1\n" : "%d\n", minimum_cost);
    return 0;
}

