int main(){
	scanf("%d%d",&n,&m);
	for(int i=1;i<=m;i++)
		for(int j=1;j<=m;j++)
			scanf("%d",&d[i][j]);
	for(int i=1;i<=n;i++)
		for(int j=1;j<=n;j++)
			scanf("%d",&c[i][j]);
	for(int i=1;i<=n;i++){
		for(int j=1;j<=n;j++){
			v[(i+j)%3].push_back(make_pair(i,j));
		}
	}
	for(int i=0;i<3;i++){
		for(int j=1;j<=m;j++){
			for(int k=0;k<v[i].size();k++){
				int x=v[i][k].first;
				int y=v[i][k].second;
				cost[i][j]+=d[c[x][y]][j];
			}
		}
	}
	long long ans=1e17;
	for(int i=1;i<=m;i++){
		for(int j=1;j<=m;j++){
			if(i==j) continue;
			for(int k=1;k<=m;k++){
				if(i==k||j==k) continue;
				long long sum=0;
				sum=cost[0][i]+cost[1][j]+cost[2][k];
				ans=min(ans,sum);
			}
		}
	}
	printf("%lld",ans);
	return 0;
}

