using orig_color_type = std::vector<std::vector<int32_t>>;
using diff_score_type = std::vector<std::vector<int32_t>>;
int32_t calc_score(int32_t c0, int32_t c1, int32_t c2, orig_color_type& col, diff_score_type& d){
    int32_t sum = 0;
    for(auto i : col[0]){
        if(i == -1) break;
        sum += d[i-1][c0];
    }
    for(auto i : col[1]){
        if(i == -1) break;
        sum += d[i-1][c1];
    }
    for(auto i : col[2]){
        if(i == -1) break;
        sum += d[i-1][c2];
    }
    return sum;
}

int main(){
    std::cin.tie(0);
    std::ios::sync_with_stdio(false);

    int32_t N, C;
    std::cin >> N >> C;
    //orig_color_type orig_color(3);
    orig_color_type orig_color(3, std::vector<int32_t>(500, -1));
    diff_score_type d(C, std::vector<int32_t>(C));

    for(int32_t i = 0; i < C; i++){
        for(int32_t j = 0; j < C; j++){
            std::cin >> d[i][j];
        }
    }

    int32_t idx[3] = {};
    for(int32_t i = 0; i < N; i++){
        for(int32_t j = 0; j < N; j++){
            int32_t orig;
            std::cin >> orig;
            orig_color[(i+j+2)%3][idx[(i+j+2)%3]] = orig;
            idx[(i+j+2)%3]++;
            //orig_color[(i+j+2)%3].push_back(orig);
        }
    }

    constexpr int32_t INF = 1 << 30;
    int32_t min_score = INF;
    int32_t score = INF;
    for(int32_t c0 = 0; c0 < C; c0++){
        for(int32_t c1 = 0; c1 < C; c1++){
            if(c1 == c0) continue;
            for(int32_t c2 = 0; c2 < C; c2++){
                if(c2 == c1 || c2 == c0) continue;
                score = calc_score(c0, c1, c2, orig_color, d);
                min_score = std::min(score, min_score);
            }
        }
    }

    std::cout << min_score << std::endl;
    return 0;

}

