using namespace std;


int main()
{
    int64_t N, C;
    std::cin >> N >> C;

    boost::multi_array<int64_t, 2> D(boost::extents[C][C]);
    for (auto p = D.data(); p < (D.origin() + D.num_elements()); ++p) {
        std::cin >> *p;
    }

    boost::multi_array<int64_t, 2> c(boost::extents[N][N]);
    for (auto p = c.data(); p < (c.origin() + c.num_elements()); ++p) {
        int64_t t;
        std::cin >> t;
        t--;
        *p = t;
    }

    // memo[g][col]: グループg[0,1,2] を色[0,C)に塗った時に生じる違和感
    boost::multi_array<int64_t, 2> memo(boost::extents[3][C]);

    for (int64_t y = 0; y < N; ++y) {
        for (int64_t x = 0; x < N; ++x) {
            const auto g = (x+y) % 3;
            for (int64_t col = 0; col < C; ++col) {
                memo[g][col] += D[c[y][x]][col];
            }
        }
    }

    std::vector<int64_t> cols;
    cols.resize(C);
    std::iota(cols.begin(), cols.end(), 0);

    int64_t mi = INT64_MAX;

    do {
        mi = std::min(mi, memo[0][cols[0]] + memo[1][cols[1]] + memo[2][cols[2]]);
    } while (std::next_permutation(cols.begin(), cols.end()));

    std::cout << mi << std::endl;

    return 0;
}

