int main(void){
    int n, c;
    cin >> n >> c;
    vector<vector<int>> d(c + 1, vector<int>(c + 1));

    for(int i = 1; i <= c; i++){
        for(int j = 1; j <= c; j++){
            cin >> d[i][j];
        }
    }

    vector<vector<int>> grid(n + 1, vector<int>(n + 1));

    for(int i = 1; i <= n; i++){
        for(int j = 1; j <= n; j++){
            cin >> grid[i][j];
        }
    }

    vector<vector<int>> cs(3, vector<int>(c + 1, 0));


    for(int i = 1; i <= n; i++){
        for(int j = 1; j <= n; j++){
            cs[(i + j) % 3][grid[i][j]]++;
        }
    }
    ll ans = INF;
    for(int i = 1; i <= c; i++){
        for(int j = 1; j <= c; j++){
            for(int k = 1; k <= c; k++){
                if(i == k || j == k || i == j) continue;
