#include <bits/stdc++.h>
using namespace std;
#define INF 1000000000

int ans = INF;
int bf[3][31];
int best_colors[3][3];
int visited[31];
vector<int> backtrack;

void check(int i)
{
    if (i == 3)
    {
		int partial = 0;
        for (int j = 0; j < 3; j++)
		{
			partial += bf[j][backtrack[j]];
		}
		ans = min(ans, partial);
    }
    else
    {
        for (int j = 0; j < 3; j++)
        {
			if (!visited[best_colors[i][j]])
			{
				backtrack.push_back(best_colors[i][j]);
				visited[best_colors[i][j]] = true;
				check(i + 1);
				backtrack.pop_back();
				visited[best_colors[i][j]] = false;
			}
        }
    }

}

int main()
{
    int n, c, i, j, k;
    cin >> n >> c;

    int wrong[c + 1][c + 1];
    int squares[n + 1][n + 1];

    for (i = 1; i <= c; i++)
    {
        for (j = 1; j <= c; j++)
        {
            cin >> wrong[i][j];
        }
    }

    for (i = 1; i <= n; i++)
    {
        for (j = 1; j <= n; j++)
        {
            cin >> squares[i][j];
        }
    }

    memset(bf, 0, sizeof(bf));
	memset(visited, 0, sizeof(visited));

    for (int mod = 0; mod < 3; mod++)
    {
        for (int color = 1; color <= c; color++)
        {
            for (i = 1; i <= n; i++)
            {
                for (j = 1; j <= n; j++)
                {
                    if ((i + j) % 3 == mod)
                    {
                        bf[mod][color] += wrong[squares[i][j]][color];
                    }
                }
            }
        }
    }

    priority_queue<pair<int, int>> finder;
    priority_queue<pair<int, int>> empty;

    for (i = 0; i < 3; i++)
    {
        for (j = 1; j <= c; j++)
        {
            finder.push(make_pair(bf[i][j], j));
        }
        for (k = 0; k < 3; k++)
        {
            best_colors[i][k] = finder.top().second;
            finder.pop();
        }
        finder.swap(empty);
    }
	check(0);
    cout << ans << endl;

    return 0;
}

