	for (int i = 0; i < C; ++i) {
		for (int j = 0; j < C; ++j) {
			cin >> D[i][j];
		}
	}
	for (int i = 0; i < N; ++i) {
		for (int j = 0; j < N; ++j) {
			cin >> c[i][j];
			--c[i][j];
		}
	}
	for (int i = 0; i < C; ++i) {
		for (int j = 0; j < 3; ++j) {
			if (i%3 == j) {
				d[i][j] = 0;
				break;
			}
			d[i][j] = INF;
			for (int k = j; k < C; k += 3) {
				if (k == i)
					d[i][j] = 0;
				d[i][j] = min(d[i][j], D[i][k]);
			}
		}
	}
	int ans = INF;
	vector<int> col;
	for (int i = 0; i < 3; ++i) {
		col.push_back(i);
	}
	do {
		int wrong = 0;
		for (int i = 0; i < 2*N; ++i) {
			for (int j = 0; j < N; ++j) {
				if (i-j >= 0 && i-j < N) {
					int a = c[i-j][j];
					int b = col[(i)%3];
					//cout << j << " " << i-j << endl;
					//cout << d[a][b] << ": " << c[i-j][j] << " -> " << col[(i-j+j)%3] << endl;
					wrong += d[a][b];
				}
			}
		}
		ans = min(ans, wrong);
	} while (next_permutation(col.begin(), col.end()));
	cout << ans << endl;
}

