int main () {
  int N, C;
  std::cin >> N >> C;

  // Dとcの設定
  int ** D = new int * [C];
  int ** c = new int * [3];
  for (int i = 0; i < C; i++ ) {
    D[i] = new int[C];  
  }
  for (int i = 0; i < 3; i++ ) {
    c[i] = new int[C];  
  }
  for (int i = 0; i < C; i++ ) {
    for (int j = 0; j < C; j++ ) {
      std::cin >> D[i][j];  
    }  
  }
  for (int i = 0; i < 3; i++ ) {
    for (int j = 0; j < C; j++) {
      c[i][j] = 0;   
    }  
  }


  // 3の剰余によって場合分け
  // 例えば, 1 1が入ってきた時c[2][値-1]に++される.
  int sub = 0;
  for (int i = 0; i < N; i++ ) {
    for (int j = 0; j < N; j++ ) {
      if ((i + j + 2) % 3 == 0 ) {
        std::cin >> sub;
        c[0][sub-1]++;  
      }
      else {
        if ((i + j + 2) % 3 == 1) {
          std::cin >> sub;
          c[1][sub-1]++;  
        }  
        else {
          std::cin >> sub;
          c[2][sub-1]++;  
        }
      }
    }  
  }

  // Cの色から3色選び, それについて直した時の違和感の合計を調べて行く. 
  // 計算量ワンチャンヤバい気がする.
  int answer = -1;
  int sub_answer = 0;
  bool forBool = false;

  // 3の剰余によって分類すべきでしたね.
  for (int i = 0; i < C; i++ ) {
    for (int j = 0; j < C; j++ ) {
      for (int k = 0; k < C; k++ ) {
        sub_answer = 0;
        forBool = false;
        if (i != j && j != k && k != i ) {

          // c[0]から見て行く.
          for (int l = 0; l < 3; l++ ) {
            for (int m = 0; m < C; m++) {
              if (answer >= 0 && sub_answer >= answer ) {
                forBool = true;
                break;  
              }
              if (l == 0) {
                sub_answer = sub_answer + c[l][m]*D[m][i];
              }
              else {
                if (l == 1) {
                  sub_answer = sub_answer + c[l][m]*D[m][j];  
                }  
                else {
                  sub_answer = sub_answer + c[l][m]*D[m][k];  
                }
              } 
            }
            if (forBool) {
              break;  
            }    
          } 
          if (answer < 0 || sub_answer <= answer ) {
            answer = sub_answer;  
          } 
        } 
      }  
    }  
  }

  std::cout << answer << std::endl;

  // deleteすることを忘れずに
  for (int i = 0; i < C; i++ ) {
    delete[] D[i];
    D[i] = 0;  
  }
  for (int i = 0; i < 3; i++ ) {
    delete[] c[i];
    c[i] = 0;  
  }
  delete[] D;
  D = 0;
  delete[] c;
  c = 0;
  return 0;
}

