	for (int i = 0; i < n; i++) {
		for (int j = 0; j < n; j++) {
			cin >> a[i][j];
			--a[i][j];
		}
	}

	//塗り替える先の色を決めて、集める
	//a[j][k]を決めた色にするのはd[a[j][k]][i]
	//全てのaの要素について、(i+j)%3で分類して集める

	vector<vector<int>> cost(3, vector<int>(c));
	for (int i = 0; i < c; i++) {
		for (int j = 0; j < n; j++) {
			for (int k = 0; k < n; k++) {
				cost[(j+k) % 3][i] += d[a[j][k]][i];
			}
		}
	}

	int res = INF;

	//(i+j)%3の余り0,1,2の類に対して
	//色の割当てを全探索

	for (int c1 = 0; c1 < c; c1++) {
		for (int c2 = 0; c2 < c; c2++) {
			for (int c3 = 0; c3 < c; c3++) {
				if (c1==c2 || c2==c3||c1==c3)continue;
				int cnt = 0;

				cnt += cost[0][c1];
				cnt += cost[1][c2];
				cnt += cost[2][c3];

				res = min(res, cnt);
			}

		}

	}

	cout << res << endl;

	return 0;
}

