int maps[3][31]; // instead of reading in every element, read in the modulo and also the color. That's all we need, after all.
int ans = 1000000;

int main() {
    for (int i=0; i<3; i++) {
        for (int j=0; j<31; j++) {
            maps[i][j] = 0;
        }
    }

	cin >> N;
	cin >> C;
	for (int i=1; i<=C; i++) {
	    for (int j=1; j<=C; j++) {
	        cin >> diff[i][j];
	    }
	}

	for (int i=1; i<=N; i++) {
	    for (int j=1; j<=N; j++) {
	        int sum = (i+j)%3;
	        int color;
	        cin >> color;
	        maps[sum][color]++; // add to existing value!
	    }
	}

	// now we need to check every combination.

	for (int i=1; i<=C; i++) { // n is just how big the map is, that's not what we want. We want to test all possible colors, C! And we don't want to do 30 because then that won't be a thing in our Diff array!
	    for (int j=1; j<=C; j++) {
	        for (int k=1; k<=C; k++) {
	            if (i!=j && i!=k && j!=k) {
	            int diffs = 0;
	            for (int a=1; a<=C; a++) { // for all of the colors.. Again, N has nothing to do with it, and 30 is way too much.
	                diffs += diff[a][i]*maps[0][a];
	            }
	            for (int b=1; b<=C; b++) {
	                diffs += diff[b][j]*maps[1][b];
	            }
	            for (int c=1; c<=C; c++) {
	                diffs += diff[c][k]*maps[2][c];
	            }
	            if (diffs < ans) {
	                ans = diffs;
	            }
	            }
	        }
	    }
	}

    cout << ans;
	return 0;
}

