long long dfs(int n, int m, int color[],long long sum=0, long long answer=100000000000LL, int depth=0) {
    if (depth == min(n*n,3)) {
        return min(sum,answer);
    }
    for (int k=0;k<m;k++) {
        bool next = false;
        for (int i=0;i<depth;i++) {
            if (k==color[i])
                next = true;
        }
        if (next) continue;

        color[depth] = k;

        if (sum+group[depth][k] < answer)
        answer = dfs(n,m,color,sum+group[depth][k],answer,depth+1);

    }
    return answer;
}

