                {
                    sum += mp1[m] * uum[m - 1][i - 1];
                    sum += mp2[m] * uum[m - 1][j - 1];
                    sum += mp3[m] * uum[m - 1][k - 1];
                }
                chmin(res, sum);
            }
        }
    }
    cout << res << endl;
}

