struct Xorshift {
  uint64_t x = 88172645463325252LL;
  unsigned next_int() {
    x = x ^ (x << 7);
    return x = x ^ (x >> 9);
  }
  unsigned next_int(unsigned mod) {
    x = x ^ (x << 7);
    x = x ^ (x >> 9);
    return x % mod;
  }
  unsigned next_int(unsigned l, unsigned r) {
    x = x ^ (x << 7);
    x = x ^ (x >> 9);
    return x % (r - l + 1) + l;
  }
  double next_double() {
    return double(next_int()) / UINT_MAX;
  }
} rnd;

template<typename T>
void shuffle_vector(vector<T>& v, Xorshift& rnd) {
  int n = v.size();
  for (int i = n - 1; i >= 1; i--) {
    int r = rnd.next_int(i);
    swap(v[i], v[r]);
  }
}



ll change_cost(const vector<vector<ll>>& D, const map<ll, ll>& modcol, ll c) {
  // c に変えるコスト
  ll cost = 0;
  for (const auto& e : modcol) {
    cost += D[e.first][c] * e.second;
  }
  return cost;
}

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  ll N, C;
  cin >> N >> C;
  vector<vector<ll>> D(C, vector<ll>(C)), c(N, vector<ll>(N));
  cin >> D >> c;
  REP(i, N) REP(j, N) c[i][j]--;

  vector<map<ll, ll>> modcol(3);

  for (ll i = 0; i < N; i++) {
    for (ll j = 0; j < N; j++) {
      modcol[(i + j) % 3][c[i][j]]++;
    }
  }

  ll ans = INT64_MAX;
  for (ll c0 = 0; c0 < C; c0++) {
    for (ll c1 = 0; c1 < C; c1++) {
      if (c0 == c1) continue;
      for (ll c2 = 0; c2 < C; c2++) {
        if (c0 == c2 || c1 == c2) continue;
        ll cost = change_cost(D, modcol[0], c0) + change_cost(D, modcol[1], c1) + change_cost(D, modcol[2], c2);
        ans = min(ans, cost);
      }
    }
  }

  cout << ans << endl;

  return 0;
}

