const int inf = 10000000;
int N, C;
vector<vector<int>> D;
vector<vector<int>> c;
vector<int> nCol[3];

int calc(int l, int m, int n) {
	if (l == m || m == n || n == l) return inf;

	int ret = 0;
	for (int i = 0; i < 3; i++) for (int j = 0; j < C; j++) {
		if (i == 0) ret += nCol[i][j] * D[j][l];
		if (i == 1) ret += nCol[i][j] * D[j][m];
		if (i == 2) ret += nCol[i][j] * D[j][n];
	}
	return ret;
}

int main() {
	cin >> N >> C;
	D = vector<vector<int>>(C, vector<int>(C, 0));
	c = vector<vector<int>>(N, vector<int>(N, 0));
	for (int i = 0; i < 3; i++) nCol[i] = vector<int>(C);

	for (int i = 0; i < C; i++) for (int j = 0; j < C; j++) cin >> D[i][j];
	for (int i = 0; i < N; i++) for (int j = 0; j < N; j++) {
		cin >> c[i][j];
		c[i][j]--;
		nCol[(i + j) % 3][c[i][j]]++;
	}

	int ans = inf;
	for (int i = 0; i < C; i++) {
		for (int j = 0; j < C; j++) {
			for (int k = 0; k < C; k++) {
				ans = min(ans, calc(i, j, k));
			}
		}
	}
	cout << ans << endl;
}

