// double(64bit浮動小数)のn分探索のループ回数の上限(2分探索なら50でも十分かもしれない). long double(80ビットの x87 浮動小数点型?)だと, 2分探索であってもこれだと足りないケースがある気がするので, もうちょっと余裕を持たせた方が良さそう.
constexpr i64 max_loop = 100;

void solve() {
    //constexpr i64 mod = 1'000'000'007;
    i64 N, C;
    cin >> N >> C;

    vector<vector<i64>> D(C, vector<i64>(C));
    rep(i, 0, C) rep(j, 0, C) cin >> D[i][j];

    vector<vector<i64>> c(N, vector<i64>(N));
    rep(i, 0, N) {
        rep(j, 0, N) {
            cin >> c[i][j];
            --c[i][j];
        }
    }

    vector<vector<i64>> cost(3, vector<i64>(C));

    rep(i, 0, 3) {
        rep(col, 0, C) {
            i64 sum=0;
            rep(y,0,N){
                rep(x,0,N){
                    if((y+x)%3==i) sum+=D[c[y][x]][col];
                }
            }
            cost[i][col]=sum;
        }
    }

    i64 ans=inf64;
    rep(c0,0,C) rep(c1,0,C) rep(c2,0,C){
        if(c0==c1 or c0==c2 or c1==c2) continue;
        chmin(ans,cost[0][c0]+cost[1][c1]+cost[2][c2]);
    }

    cout << ans << endl;
}

