using namespace std;
using boost::adaptors::reversed;
using boost::irange;
using uint = unsigned int;
using ll = long long int;
using ull = unsigned long long int;

int main() {
    ll N, C;
    cin >> N >> C;
    vector<vector<ll>> ds(C, vector<ll>(C));
    vector<vector<ll>> cs(N, vector<ll>(N));

    for (auto &&i: irange(0LL, C)) {
        for (auto &&j: irange(0LL, C)) {
            cin >> ds.at(i).at(j);
        }
    }
    for (auto &&i: irange(0LL, N)) {
        for (auto &&j: irange(0LL, N)) {
            ll c;
            cin >> c;
            c--;
            cs.at(i).at(j) = c;
        }
    }

    vector<vector<ll>> c_another_struct(3, vector<ll>{});
    for (auto &&i: irange(0LL, N)) {
        for (auto &&j: irange(0LL, N)) {
            c_another_struct.at((i + j) % 3).emplace_back(cs.at(i).at(j));
        }
    }
    vector<vector<ll>> cost(3, vector<ll>(C, 0));
    for (auto &&i: irange(0LL, 3LL)){
        for (auto &&color_to: irange(0LL, C)){
            for (auto &&color_from: c_another_struct.at(i)){
                cost.at(i).at(color_to)+=ds.at(color_from).at(color_to);
            }
        }
    }
    ll min_cost{numeric_limits<ll>::max()};
    for (auto &&color_1: irange(0LL, C)){
        for (auto &&color_2: irange(0LL, C)){
            if (color_2 == color_1) continue;
            for (auto &&color_3: irange(0LL, C)){
                if (color_3 == color_1 || color_3 == color_2) continue;
                min_cost = min(min_cost, cost.at(0).at(color_1) + cost.at(1).at(color_2) + cost.at(2).at(color_3));
            }
        }
    }
    cout << min_cost;
    return 0;
}

