#define FOR(i, a, b) for (LL i = (a); i < (b); ++i)
#define REP(i, n)    FOR(i, 0, n)
#define $(x)         {cout << #x << " = " << (x) << endl;}


void solve(LL N, LL C, vector<vector<LL>> D, vector<vector<LL>> c){
    VVI t(3, VI(C));
    REP(i, N) {
        REP(j, N) {
            t[(i + j + 2) % 3][c[i][j] - 1]++;
        }
    }

    LL ans = LLONG_MAX;
    REP(c0, C) {
        LL sum0 = 0;
        REP(i, C) {
            if (i == c0) continue;
            sum0 += t[0][i] * D[i][c0];
        }
        if (ans <= sum0) continue;
        REP(c1, C) {
            if (c0 == c1) continue;
            LL sum1 = 0;
            REP(i, C) {
                if (i == c1) continue;
                sum1 += t[1][i] * D[i][c1];
            }
            if (ans <= sum0 + sum1) continue;
            REP(c2, C) {
                if (c0 == c2 || c1 == c2) continue;
                LL sum2 = 0;
                REP(i, C) {
                    if (i == c2) continue;
                    sum2 += t[2][i] * D[i][c2];
                }
                LL sum = sum0 + sum1 + sum2;
                ans = min(ans, sum);
            }
        }
    }
    cout << ans << endl;
}

