          if ((i + j) % 3 == k) {
            aux += d[a[i][j]][cor];
          }
        }
      }
      f[k].insert({aux, cor});
    }
  }
  long minimo = INF;
  for (auto &x : f[0]) {
    for (auto &y : f[1]) {
      for (auto &z : f[2]) {
        if (x.second == y.second) continue;
        if (x.second == z.second) continue;
        if (z.second == y.second) continue;
        long total = x.first + y.first + z.first;
        minimo = min(minimo, total);
      }
    }
  }
  printf("%lld\n", minimo);
}

