template<class T>
T pow_n(T x, T n) {
	T res = 1;
	while (n > 0) {
		if (n & 1) res = res * x;
		x = x * x;
		n >>= 1;
	}
	return res;
}

class Solver {
public:
	int H, W;

	bool grid_ng(int y, int x) {
		return y < 0 || y >= H || x < 0 || x >= W;
	}

	struct Point {
		int y, x;
		bool operator < (const Point& r) const {
			if (y != r.y) return y < r.y;
			return x < r.x;
		}
	};

	struct Color {
		int c, cnt;
		bool operator < (const Color& r) const {
			return cnt < r.cnt;
		}
		void print() {
			cerr << "color : " << c + 1 << " " << cnt << endl;
		}
	};

	int N, C;
	int D[35][35];
	int c[505][505];

	void solve() {
		cin >> N >> C;
		rep(y, C) rep(x, C) cin >> D[y][x];
		rep(y, N) rep(x, N) {
			cin >> c[y][x];
			c[y][x] -= 1;
		}
		// int cnt[3][3][35] = {};
		vector<Color> cnt[3];
		vector<Color> cost[3];
		rep(i, 3) {
			cnt[i].resize(C);
			rep(c, C) cnt[i][c] = { c, 0 };
		}
		rep(y, N) rep(x, N) {
			int moded_n = (y + x) % 3;
			if (c[y][x] < 0) continue;
			cnt[moded_n][c[y][x]].cnt += 1;
		}
		//rep(i, 3) {
		//	for (auto& c : cnt[i]) {
		//		c.print();
		//	}
		//	cerr << endl;
		//}
		rep(i, 3) {
			cost[i].resize(C);
			rep(c, C) cost[i][c].cnt = 0;
			rep(c, C) cost[i][c].c = c;
			rep(c, C) rep(c2, C) {
				cost[i][c2].cnt += D[c][c2] * cnt[i][c].cnt;
			}
		}
		rep(i, 3) {
			sort(all(cost[i]));
			for (auto& c : cost[i]) {
				c.print();
			}
			cerr << endl;
		}
		bool used[35] = {};
		set<int> yet;
		rep(i, 3) {
			yet.insert(i);
		}
		int res = 0;
		while (yet.size() != 0) {
			vector<int> hoping[35];
			for (auto& v : yet) {
				hoping[cost[v][0].c].push_back(v);
			}
			bool f = true;
			rep(c, C) {
				dump(c + 1);
				dumpl(hoping[c].size());
				if (hoping[c].size() < 2) continue;
				f = false;
				auto best = hoping[c][0];
				for (auto& v : hoping[c]) {
					auto f = [&](int v2) {
						return cost[v2][0].cnt - cost[v2][1].cnt;
					};
					if (f(v) < f(best)) {
						best = v;
					}
				}
				dump(best);
				dumpl(cost[best][0].cnt);
				res += cost[best][0].cnt;
				used[c] = true;
				yet.erase(best);
				rep(i, 3) {
					auto itr = cost[i].begin();
					for (; itr != cost[i].end(); itr++) {
						if (itr->c == c) break;
					}
					cost[i].erase(itr);
				}
			}
			if (f == true) {
				for (auto& v : yet) {
					dumpl(cost[v][0].cnt);
					res += cost[v][0].cnt;
				}
				break;
			}
		}
		cout << res << endl;
	}

};

