			for (LL f = 0; f < c; f++) {
				if (g == f)continue;
				if (h == f)continue;

				LL p = cost[0][g] + cost[1][h] + cost[2][f];
				mn = min(mn, p);
			}
		}
	}

	cout << mn << endl;
}

