int calc(int a, int b, int c) {
  int value = 0;
  for (int i = 1; i <= C; i++) {
    value += t[0][i] * D[i][a];
  }
  for (int i = 1; i <= C; i++) {
    value += t[1][i] * D[i][b];
  }
  for (int i = 1; i <= C; i++) {
    value += t[2][i] * D[i][c];
  }
  return value;
}

