void init()
{
  for (int i = 0; i < 3; i++)
    for (int j = 0; j < MAXC; j++)
      memo[i][j] = -1;
}

int64_t calc(int r, int c)
{
  int64_t s0 = 0, s1 = 0, s2 = 0;
  for (int i = 0; i < N; i++)
  {
    for (int j = 0; j < N; j++)
    {
      if ((i + j) % 3 == 0)
        s0 += ds[cs[i][j]][c];
      else if ((i + j) % 3 == 1)
        s1 += ds[cs[i][j]][c];
      else
        s2 += ds[cs[i][j]][c];
    }
  }
  memo[0][c] = s0;
  memo[1][c] = s1;
  memo[2][c] = s2;
  return memo[r][c];
}

