		vector<Color> cost[3];
		rep(i, 3) {
			cnt[i].resize(C);
			rep(c, C) cnt[i][c] = { c, 0 };
		}
		rep(y, N) rep(x, N) {
			int moded_n = (y + x) % 3;
			if (c[y][x] < 0) continue;
			cnt[moded_n][c[y][x]].cnt += 1;
		}
		rep(i, 3) {
			for (auto& c : cnt[i]) {
				c.print();
			}
			cerr << endl;
		}
		rep(i, 3) {
			cost[i].resize(C);
			rep(c, C) cost[i][c].cnt = 0;
			rep(c, C) cost[i][c].c = c;
			rep(c, C) rep(c2, C){
				cost[i][c2].cnt += D[c][c2] * cnt[i][c].cnt;
			}
		}
		rep(i, 3) {
			for (auto& c : cost[i]) {
				c.print();
			}
			cerr << endl;
		}
		int res = INF;
		rep(a, C) rep(b, C) rep(c, C) {
			if (a == b) continue;
			if (b == c) continue;
			if (c == a) continue;
			int d = cost[0][a].cnt + cost[1][b].cnt + cost[2][c].cnt;
			dump(a); dump(b); dump(c); dumpl(d);
			chmin(res, d);
		}
		cout << res << endl;
	}

};

