int DF[4][32] = {0};
void calcDF(){
	for(int g=0; g<3; g++){
		for(int c=0; c<C; c++){
			int r = 0;
			for(int i=0; i<N; i++){
				for(int j=0; j<N; j++){
					if((i+j)%3 != g) continue;
					r += D[GC0[i][j]][c];
				}
			}
			DF[g][c] = r;
		}
	}
}

int main(int argc, char* argv[]){
	cin.tie(0);
	ios::sync_with_stdio(false);

