			D[i][j] = d;
		}
	}
	for(int i=0; i<N; i++){
		for(int j=0; j<N; j++){
			int c; cin >> c; c--;
			GC0[i][j] = c;
		}
	}

	calcDF();
	LL ans = INF;
	for(int i=0; i<C; i++){
		for(int j=0; j<C; j++){
			if(j == i) continue;
			for(int k=0; k<C; k++){
