class UnionFind
{
public:
    vector<ll> Parent;

    UnionFind(ll N)
    {
        Parent = vector<ll>(N, -1);
    }
    ll find(ll A)
    {
        if (Parent[A] < 0)
            return A;
        return Parent[A] = find(Parent[A]);
    }

    ll size(ll A)
    {
        return -Parent[find(A)];
    }

    bool Union(ll A, ll B)
    {
        A = find(A);
        B = find(B);
        if (A == B)
        {
            return false;
        }
        if (size(A) < size(B))
            swap(A, B);

        Parent[A] += Parent[B];
        Parent[B] = A;

        return true;
    }
};

ll gcd(ll a, ll b)
{
    if (b == 0)
        return a;
    return gcd(b, a % b);
}

ll lcm(ll a, ll b)
{
    ll g = gcd(a, b);
    return a / g * b;
}

ll mulMod(ll a, ll b)
{
    return (((a % MOD) * (b % MOD)) % MOD);
}

ll powMod(ll a, ll p)
{
    if (p == 0)
    {
        return 1;
    }
    else if (p % 2 == 0)
    {
        ll half = powMod(a, p / 2);
        return mulMod(half, half);
    }
    else
    {
        return mulMod(powMod(a, p - 1), a);
    }
}

ll ceil(ll a, ll b)
{
    return (a + b - 1) / b;
}

void solve(long long N, long long C, std::vector<std::vector<long long>> D, std::vector<std::vector<long long>> c)
{
    ll ans = LLONG_MAX;

    for (int one = 0; one < C; one++)
    {
        for (int two = 0; two < C; two++)
        {
            for (int three = 0; three < C; three++)
            {
                if (one != two && two != three && three != one)
                {
                    ll tmp = 0;
                    for (int i = 0; i < N; i++)
                    {
                        for (int j = 0; j < N; j++)
                        {
                            ll color = c[i][j];
                            if ((i + j) % 3 == 1)
                            {
                                tmp += D[color - 1][one];
                            }
                            else if ((i + j) % 3 == 2)
                            {
                                tmp += D[color - 1][two];
                            }
                            else
                            {
                                tmp += D[color - 1][three];
                            }
                        }
                    }
                    ans = min(ans,tmp);
                }
                else
                {
                    continue;
                }
            }
        }
    }
    cout << ans << endl;
}

