void body() {
    auto N = read<i64>();
    auto C = read<i64>();
    auto D = make_matrix<i64, 2>({C, C}, 0);
    REP (i, C) {
        REP (j, C) {
            D[i][j] = read<i64>();
        }
    }
    auto Cs = make_matrix<i64, 2>({N, N}, 0);
    REP (i, N) {
        REP (j, N) {
            Cs[i][j] = read<i64>() - 1;
        }
    }

    auto num = make_matrix<i64, 2>({3, C}, 0);
    REP (i, N) {
        REP (j, N) {
            auto x = (i + 1 + j + 1) % 3;
            num[x][Cs[i][j]] += 1;
        }
    }

    i64 ans = numeric_limits<i64>::max();
    REP (i, C) {
        REP (j, C) {
            REP (k, C) {
                if (i == j || i == k || j == k) continue;

                /* x+y%3 == 0ならi、x+y%3==1ならj、それ以外ならkで塗る*/
                Vector<i64> cs = {i, j, k};
                i64 d = 0;
                REP (x, 3) {
                    REP (c, C) {
                        d += num[x][c] * D[c][cs[x]];
                    }
                }

                ans = std::min(ans, d);
            }
        }
    }
    cout << ans << endl;
}

