#include<bits/stdc++.h>
using namespace std;

int main(){
  int N, C;
  cin >> N >> C;
  vector<vector<int>> color(C,vector<int>(C));
  for(int i=0; i<C; i++){
    for(int j=0; j<C; j++){
      cin >> color.at(i).at(j);
    }
  }
  vector<vector<int>> num(N,vector<int>(N));
  for(int i=0; i<N; i++){
    for(int j=0; j<N; j++){
      cin >> num.at(i).at(j);
    }
  }

  vector<vector<int>> vec(3,vector<int>(0));
  for(int i=0; i<N; i++){
    for(int j=0; j<N; j++){
      vec.at((i+j) %3).push_back(num.at(i).at(j));
    }
  }

  int64_t cost = 10000000000;

  for(int a=0; a<C; a++){
    int64_t cost_x = 0;
    for(int i=0; i<vec.at(0).size(); i++){
      cost_x += color.at(vec.at(0).at(i)-1).at(a);
    }
    for(int b=0; b<C; b++){
      if(b == a){
        continue;
      }
      for(int j=0; j<vec.at(1).size(); j++){
        cost_x += color.at(vec.at(1).at(j)-1).at(b);
      }
      for(int c=0; c<C; c++){
        if(c == a || c == b){
          continue;
        }
        for(int k=0; k<vec.at(2).size(); k++){
          cost_x += color.at(vec.at(2).at(k)-1).at(c);
        }
      }
      cost = min(cost,cost_x);
    }
  }
  cout << cost << endl;          
}

