#define SORT(c)      stable_sort(ALL(c))
#define RSORT(c)     stable_sort((c).rbegin(), (c).rend())
#define FOR(i, a, b) for (LL i = (a); i < (b); ++i)
#define REP(i, n)    FOR(i, 0, n)
#define $(x)         {cout << #x << " = " << (x) << endl;}


void solve(long long N, long long C, std::vector<std::vector<long long>> D, std::vector<std::vector<long long>> c){
    VVI r;
    r.PB(VI{1, 0, 2});
    r.PB(VI{2, 1, 0});
    r.PB(VI{0, 2, 1});

    LL ans = LLONG_MAX;
    REP(c0, C) {
        LL sum0 = 0;
        REP(i, N) {
            for (LL j = r[0][i % 3]; j < N; j += 3) {
                sum0 += D[c[i][j] - 1][c0];
            }
        }
        REP(c1, C) {
            if (c0 == c1) continue;
            LL sum1 = 0;
            REP(i, N) {
                for (LL j = r[1][i % 3]; j < N; j += 3) {
                    sum1 += D[c[i][j] - 1][c1];
                }
            }
            REP(c2, C) {
                if (c0 == c2 || c1 == c2) continue;
                LL sum2 = 0;
                REP(i, N) {
                    for (LL j = r[2][i % 3]; j < N; j += 3) {
                        sum2 += D[c[i][j] - 1][c2];
                    }
                }
                LL sum = sum0 + sum1 + sum2;
                ans = min(ans, sum);
            }
        }
    }
    cout << ans << endl;
}

int main(){
    long long N;
    scanf("%lld",&N);
    long long C;
    scanf("%lld",&C);
    std::vector<std::vector<long long>> D(C, std::vector<long long>(C));
    for(int i = 0 ; i < C ; i++){
        for(int j = 0 ; j < C ; j++){
            scanf("%lld",&D[i][j]);
        }
    }
    std::vector<std::vector<long long>> c(N, std::vector<long long>(N));
    for(int i = 0 ; i < N ; i++){
        for(int j = 0 ; j < N ; j++){
            scanf("%lld",&c[i][j]);
        }
    }
    solve(N, C, std::move(D), std::move(c));
    return 0;
}

