int calc(int A, int B, int C) {
	if (A == B || B == C || C == A) return inf;

	int ret = 0;
	for (int i = 0; i < N; i++) for (int j = 0; j < N; j++) {
		if ((i + j) % 3 == 0 && c[i][j] - 1 != A) {
			ret += D[c[i][j] - 1][A];
		}
		else if ((i + j) % 3 == 1 && c[i][j] - 1 != B) {
			ret += D[c[i][j] - 1][B];
		}
		else if ((i + j) % 3 == 2 && c[i][j] - 1 != C) {
			ret += D[c[i][j] - 1][C];
		}
	}

	return ret;
}

