#include <bits/stdc++.h>
using namespace std;
int N,C,answer;
vector<vector<int>> D, d;
void combinationUtil(int arr[], int data[],  
                    int start, int end,  
                    int index, int r); 
void solve(int arr[], int n, int r)  
{  
    // A temporary array to store 
    // all combination one by one  
    int data[r];  
    combinationUtil(arr, data, 0, n-1, 0, r);  
}  

/* arr[] ---> Input Array  
data[] ---> Temporary array to  
store current combination  
start & end ---> Staring and 
Ending indexes in arr[]  
index ---> Current index in data[]  
r ---> Size of a combination to be printed */
void combinationUtil(int arr[], int data[],  
                    int start, int end,  
                    int index, int r)  
{  
    // Current combination is ready 
    // to be printed, print it  
    if (index == r)  
    {  
        sort(data,data+r);
        do {
            int wrongness = 0;
        	for (int i = 0; i < r; i++) {
          		for (int c = 1; c <= C; c++) {
            		wrongness += d[i][c]*D[c][data[i]];
                }
            }
          answer = min(answer,wrongness);
        } while (next_permutation(data,data+r));
    }  

    // replace index with all possible  
    // elements. The condition "end-i+1 >= r-index" 
    // makes sure that including one element  
    // at index will make a combination with  
    // remaining elements at remaining positions  
    for (int i = start; i <= end &&  
        end - i + 1 >= r - index; i++)  
    {  
        data[index] = arr[i];  
        combinationUtil(arr, data, i+1,  
                        end, index+1, r);  
    }  
}  
int main() {
  int c;
  cin >> N >> C;
  answer = INT_MAX;
  D = vector<vector<int>>(C+1,vector<int>(C+1));
  for (int i = 1; i <= C; i++) {
    for (int j = 1; j <= C; j++) {
      cin >> D[i][j];
    }
  }
  d = vector<vector<int>>(3,vector<int>(C+1));
  for (int i = 1; i <= N; i++) {
    for (int j = 1; j <= N; d[(i+j)%3][c]++, j++) {
      cin >> c;
    }
  }
  int colours[C];
  for (int i = 0; i < C; i++) {
    colours[i] = i+1;
  }
  solve(colours,C,3);
  cout << answer;
}

