    // 最初の色
    rep(i,N){
      rep(j,N){
        ll c;cin>>c;
        c--;

        ll g = (i+j)%3; // group
        mp[g][c]++;
      }
    }

    auto f = [&](map<ll,ll>& mp, ll to){
      ll sum=0;
      for(auto pa : mp){
        ll from = pa.first;
        ll cnt = pa.second;
        sum += D[from][to] * cnt;
      }
      return sum;
    };

    ll mi=inf;
