void solve_abc099_d() {
	ll N, C;
	ll ans = 0;
	cin >> N >> C;

	int D[31][31];
	rep(i, C) {
		rep(j, C) {
			cin >> D[i][j];
		}
	}

	int c[501][501];
	vector<int> g[3];
	rep(i, N) {
		rep(j, N) {
			cin >> c[i][j];
			g[(i + j) % 3].push_back(c[i][j]-1);
		}
	}

	ans = INF;
	ll cost;
	rep(i, C) {
		rep(j, C) {
			rep(k, C) {
				if (i != j && j != k && k != i) {
					cost = 0;
					rep(m, g[0].size()) {
						cost += D[g[0][m]][i];
					}
					rep(m, g[1].size()) {
						cost += D[g[1][m]][j];
					}
					rep(m, g[2].size()) {
						cost += D[g[2][m]][k];
					}
					if (ans > cost) {
						ans = cost;
					}
				}
			}
		}
	}

	cout << ans << "\n";
}

