int N, C;
int d[505][505], c[505][505];
int cnt[5], num[5][505];
int main(){
    scanf("%d%d", &N, &C);
    for(int i = 1; i <= C; ++i){
        for(int j = 1; j <= C; ++j){
            scanf("%d", &d[i][j]);
        }
    }
    for(int i = 1; i <= N; ++i){
        for(int j = 1; j <= N; ++j){
            scanf("%d", &c[i][j]);
            cnt[(i+j)%3]++;
            num[(i+j)%3][c[i][j]]++;
        }
    }
    int ans = 0x3f3f3f3f;
    for(int i = 1; i <= C; ++i){
        for(int j = 1; j <= C; ++j){
            for(int k = 1; k <= C; ++k){
                if((i==j) || (j==k) || (i==k)) continue;
                int res = 0;
                for(int l = 1; l <= N; ++l){
                    if(res >= ans) break;
                    for(int x = 1; x <= N; ++x){
                        if((l+x) % 3 == 0){
                            if(c[l][x] != i){
                                res += d[c[l][x]][i];
                            }
                        }else if((l+x) % 3 == 1){
                            if(c[l][x] != j){
                                res += d[c[l][x]][j];
                            }
                        }else{
                            if(c[l][x] != k){
                                res += d[c[l][x]][k];
                            }
                        }
                        if(res >= ans) break;
                    }
                }
                ans = min(ans, res);
            }
        }
    }
    printf("%d\n", ans);
    return 0;
}

