#include<bits/stdc++.h>
using namespace std;

void all_perm(int *elem, int n, function<void(int *)> f)
{
    do{
        f(elem);
    } while(next_permutation(elem, elem + n));
}

void rec_comb(int *elem, int n, int k, function<void(int *)> f)
{
    if(k == 0) f(elem);
    else if(n < 0) return;
    else
    {
        rec_comb(elem, n - 1, k, f);
        elem[k - 1] = n;
        rec_comb(elem, n - 1, k - 1, f);
    }    
}

void comb(int n, int k, function<void(int *)> f)
{
    int t_elem[k];
    rec_comb(t_elem, n - 1, k, f);
}

void perm(int *elem, int n, int k, function<void(int *)> f)
{
    comb(n, k, [&](int *t_elem) {
        all_perm(elem, k, [&](int *p_elem) {
            int elems[k];
            for(int i = 0; i < k; i++) elems[i] = t_elem[p_elem[i]];
            f(elems);
        });
    });
}

