int main(){
	int n, c;
	cin >> n >> c;
	vector<vector<int>> d = vector<vector<int>>(c, vector<int>(c, 0));
	for (int i = 0; i < c; ++i) {
		for (int j = 0; j < c; ++j) {
			int dij;
			cin >> dij;
			d[i][j] = dij;
		}
	}
	vector<vector<int>> cmap = vector<vector<int>>(n, vector<int>(n, 0));
	for (int i = 0; i < n; ++i) {
		for (int j = 0; j < n; ++j) {
			int cij;
			cin >> cij;
			cij--;
			cmap[i][j] = cij;
		}
	}
	vector<vector<int>> result = vector<vector<int>>(3, vector<int>(c,0));
	for(int ct =0;ct<c;++ct){
		for (int i = 0; i < n; ++i) {
			for (int j = 0; j < n; ++j) {
				int line = (i + j) % 3;
				int cc = cmap[i][j];
				if(cc!=ct)
					result[line][ct] += d[cc][ct];
			}
		}
	}
	int best = 500*500*1000+1;
	for (int call = 0; call < c*c*c; call++) {
		int c1 = call % c;
		int c2 = (call / c) % c;
		int c3 = (call / c / c) % c;
		if (c1 == c2 || c2 == c3 || c3 == c1) continue;
		best = min(best, result[0][c1] + result[1][c2] + result[2][c3]);
	}
	cout << best << endl;
	return 0;
}

