int main() {
    ios::sync_with_stdio(false);
    cin.tie(NULL);

    int N, C;
    cin >> N >> C;

    ll tmp;

    vector<vector<int>> strangeness(C, vector<int>(C)), distribution(3, vector<int>(C, 0));
    for (auto &&row: strangeness) {
        for (auto &element: row) {
            cin >> element;
        }
    }

    for (int i = 1; i <= N; i++) {
        for (int j = 1; j <= N; j++) {
            cin >> tmp;
            distribution[(i + j) % 3][tmp - 1] += 1;
        }
    }

    ll answer = -1;
    for (int i = 1; i <= C; i++) {
        for (int j = 1; j <= C; j++) {
            for (int k = 1; k <= C; k++) {
                // 同じ色については調べる必要はない
                if (i == j || j == k || k == i) {
                    continue;
                }

                tmp = 0;
                for (int l = 1; l <= C; l++) {
                    // 色lを色i,j,kに変換した時の違和感の変化を計算
                    tmp += distribution[0][l - 1] * strangeness[l - 1][i - 1];
                    tmp += distribution[1][l - 1] * strangeness[l - 1][j - 1];
                    tmp += distribution[2][l - 1] * strangeness[l - 1][k - 1];
                }
                answer = (answer == -1) ? tmp : min(tmp, answer);
            }
        }
    }

    cout << answer << endl;
}

