			for (int k = 1; k <= C; k++) {
				//まず、ijkは相異なるチェック
				if (i == j)continue;
				if (i == k)continue;
				if (j == k)continue;
				//ijkセットにかえるときの違和感チェック
				//i = 1,j = 2,k = 3担当
				int iwa = 0;
				for (int x = 0; x < N; x++) {
					for (int y = 0; y < N; y++) {
						if ((x + y) % 3 == 1) {
							iwa += D[G[x][y]-1][i-1];
						}
						if ((x + y) % 3 == 2) {
							iwa += D[G[x][y]-1][j-1];
						}
						if ((x + y) % 3 == 0) {
							iwa += D[G[x][y]-1][k-1];
						}
					}
				}
				//miniwa 更新
				miniwa = min(iwa, miniwa);
			}
		}
	}

	cout << miniwa;
	return 0;
}

