constexpr Value maxN = 100000;

Value calc(Value const n, C const c, const std::vector<std::vector<D>>& ds,
           const std::vector<std::vector<C>> cs) {
  std::vector<C> css[3];
  for (int i = 0; i < 3; ++i) {
    css[i].reserve((n * n + 2) / 3);
  }
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < n; ++j) {
      css[(i + j) % 3].push_back(cs[i][j] - 1);
    }
  }
  Value ret = INT32_MAX;
  for (int t0 = 0; t0 < c; ++t0) {
    D d0 = 0;
    for (auto csss : css[0]) {
      d0 += ds[csss][t0];
    }
    if (d0 >= ret) {
      continue;
    }
    for (int t1 = 0; t1 < c; ++t1) {
      if (t1 == t0) {
        continue;
      }
      D d1 = d0;
      for (auto csss : css[1]) {
        d1 += ds[csss][t1];
      }
      if (d1 >= ret) {
        continue;
      }
      for (int t2 = 0; t2 < c; ++t2) {
        if (t2 == t0 || t2 == t1) {
          continue;
        }
        D d2 = d1;
        for (auto csss : css[2]) {
          d2 += ds[csss][t2];
        }
        ret = std::min(d2, ret);
      }
    }
  }
  return ret;
}

