int CALCUL(int A, int B, int C) {
	int count = 0; int temp;
	for (int i = 0; i < N; i++) {
		for (int j = 0; j < N; j++) {
			temp = (i + j) % 3;
			if (temp == 2) {
				count = count + VALUE(PAN[i][j], A);
				if (count > min) {
					return min;
				}
			}
			if (temp == 0) {
				count = count + VALUE(PAN[i][j], B);
				if (count > min) {
					return min;
				}
			}
			if (temp == 1) {
				count = count + VALUE(PAN[i][j], C);
				if (count > min) {
					return min;
				}
			}
		}
	}
	return count;
}


