    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            int r = (i + j) % 3;
            int color = c[i][j];
            if (m[r].count(color) == 0) {
                m[r][color] = 1;
            } else {
                m[r][color] += 1;
            }
        }
