    int minCost = INT_MAX;
    for (int x = 1; x <= C; x++) {
        for (int y = 1; y <= C; y++) {
            for (int z = 1; z <= C; z++) {
                int cost = 0;
                if (x == y || y == z || z == x) {
                    continue;
                }
                for (auto& m1: m[0]) {
                    if (m1.first != x) {
                        cost += m1.second * D[m1.first-1][x-1];
                    }
                }
                for (auto& m2: m[1]) {
                    if (m2.first != y) {
                        cost += m2.second * D[m2.first-1][y-1];
                    }
                }
                for (auto& m3: m[2]) {
                    if (m3.first != z) {
                        cost += m3.second * D[m3.first-1][z-1];
