vector<int> num[3];
unordered_map<int, int> memo[3];
int f(const vector<vector<int> >& D, int i,int j, int k) {
	int su = 0;
	if (memo[0].find(i) == memo[0].end()) {
		int su1 = 0;
		for (auto &a : num[0]) {
			su1 += D[a][i];
		}
		memo[0][i] = su1;
	}
	if (memo[1].find(j) == memo[1].end()) {
		int su2 = 0;
		for (auto &a : num[1]) {
			su2 += D[a][j];
		}
		memo[1][j] = su2;
	}
	if (memo[2].find(k) == memo[2].end()) {
		int su3 = 0;
		for (auto &a : num[2]) {
			su3 += D[a][k];
		}
		memo[2][k] = su3;
	}
	return memo[0][i] + memo[1][j] + memo[2][k];
}

void solve() {
	int N, C; cin >> N >> C;
	vector<vector<int> > D(C, vector<int>(C));
	REP(i, C) REP(j, C) D[i][j] = in();
	for (int i = 0; i < N; ++i) {
		for (int j = 0; j < N; ++j) {
			num[(i + j + 2) % 3].push_back(in()-1);
		}
	}
	int res = inf;
	for (int i = 0; i < C; ++i) {
		for (int j = 0; j < C; ++j) if(i != j) {
			for (int k = 0; k < C; ++k) if(i != k and j != k) {
				res = min(res, f(D, i, j, k));
			}
		}
	}
	cout << res << endl;
}

