	for(int i=0;i<N;i++) {
		for(int j=0;j<N;j++) {
			rest[i][j] = ((i+1) + (j+1)) % 3;
		}
	}
	// color[3で割ったあまり][色(0<n<C)]
	vector<vector<int>> color(3, vector<int>(C, 0));
	for(int i=0;i<N;i++) {
		for(int j=0;j<N;j++) {
			if(rest[i][j] == 0) color[0][c[i][j]]++;
			if(rest[i][j] == 1) color[1][c[i][j]]++;
			if(rest[i][j] == 2) color[2][c[i][j]]++;
		}
	}

	int ans = INT_MAX;
	// C色の中から3色(i, j, k)を選ぶ
	for(int i=0;i<C;i++) {
