             	 // 3で割ったあまりが2 -> 色をkに
				for(int l=0;l<C;l++) tmpsum += (color[0][l]) * D[l][i];
				for(int l=0;l<C;l++) tmpsum += (color[1][l]) * D[l][j];
				for(int l=0;l<C;l++) tmpsum += (color[2][l]) * D[l][k];
				ans = min(ans, tmpsum);
			}
		}
	}

	cout << ans << endl;
}

