				disorder[i][j] += rem_colors[i][k] * D[k][j];
			}
		}
	}

	//組み合わせを全列挙して最小を探す
	int ans = numeric_limits<int>::max();

	for (int i = 0; i < C; i++) {
		for (int j = 0; j < C; j++) {
			for (int k = 0; k < C; k++) {
				if (i != j && j != k && k != i
					&& ans > disorder[0][i] + disorder[1][j] + disorder[2][k]) {
					ans = disorder[0][i] + disorder[1][j] + disorder[2][k];
				}
			}
		}
	}

	cout << ans << endl;

	return 0;
}

