ll solve(int N, int C)
{
/*
    // Floyd-Warshall para computar o custo mínimo da troca de cores
    for (int x = 1; x <= N; ++x)
        for (int y = 1; y <= N; ++y)
            for (int c = 1; c <= C; ++c)
