*/
    // Calcula o mínimo para trocar todos elementos r mod 3 pela cor C
    for (int c = 1; c <= C; ++c)
        for (int x = 1; x <= N; ++x)
            for (int y = 1; y <= N; ++y)
            {
                int r = (x + y) % 3;
 //               best[r][c] += cost[x][y][c];
                best[r][c] += D[grid[x][y]][c];
            }

    // A resposta é a melhor troca para 3 cores distintas
    ll ans = oo;

    for (int a = 1; a <= C; ++a)
    for (int b = 1; b <= C; ++b)
    for (int c = 1; c <= C; ++c)
    {
        if (a == b or a == c or b == c)
