#include<cstdio>
static const int kMaxVertices = 30;
static const int kInfinity = 1010;
static int Adjacency_matrix[kMaxVertices][kMaxVertices];
int A[3][30];

void InitializeCostMatrix(int nmbr_of_rows, int nmbr_of_columns){
	for (int row = 0; row < nmbr_of_rows; ++row) {
		for (int column = 0; column < nmbr_of_columns; ++column)
			Adjacency_matrix[row][column] = kInfinity;
	}
}

void Dijkstra(int n, int id){
	bool has_not_been_added[kMaxVertices];
	int lowest_cost_route[kMaxVertices];
	for (int i = 0; i < n; ++i)	{
		has_not_been_added[i] = true;
		lowest_cost_route[i] = kInfinity;
	}
	lowest_cost_route[id] = 0;

	while(true){
		int mincost = kInfinity;
		int vertex_to_add;
		for (int i = 0; i < n; ++i)	{
			if(has_not_been_added[i] && lowest_cost_route[i] < mincost){
				mincost = lowest_cost_route[i];
				vertex_to_add = i;
			}
		}

		if(mincost == kInfinity)
			break;

		has_not_been_added[vertex_to_add] = false;
		int vertex_added = vertex_to_add;

		for (int i = 0; i < n; ++i)	{
			if(has_not_been_added[i] && lowest_cost_route[vertex_added] + Adjacency_matrix[vertex_added][i] < lowest_cost_route[i]) {
				lowest_cost_route[i] = lowest_cost_route[vertex_added] + Adjacency_matrix[vertex_added][i];
			}
		}
		for (int i = 0; i < C; ++i) Adjacency_matrix[id][i] = lowest_cost_route[i];
	}
}

int main() {
	int N, C;
	scanf("%d %d", &N, &C);
	for (int i = 0; i < C; ++i){
		for (int j = 0; j < C; ++j) scanf("%d", &Adjacency_matrix[i][j]);
	}
	for (int i = 0; i < C; ++i) Dijkstra(N, i);
	for (int i = 1; i <= N; ++i){
		for (int j = 1; j <= N; ++j){
			int tmp;
			scanf("%d", &tmp);
			A[(i + j) % 3][tmp - 1]++;
		}
	}
	int answer = 250000000;
	for (int i = 0; i < C; ++i)
	{
		for (int j = 0; j < C; ++j)
		{
			for (int k = 0; k < C; ++k)
			{
				if(i != j && j != k && k != i){
					int candidate = 0;
					for (int l = 0; l < 3; ++l){
						for (int m = 0; m < C; ++m) candidate += Adjacency_matrix[m][i]*A[l][m];
					}
					if(candidate < answer) answer = candidate;
				}
			}
		}
	}
	printf("%d\n", answer);
	return 0;
}

