map<tuple<short, int>, int> dp;
map<tuple<short, short>, int> dp2;

int add(short now, short col) {
	int cnt = 0;
	auto status = make_tuple(now, col);
	if (dp2.count(status)) return dp2[status];
	for (int j = 0; j < N; j++) {
		for (int k = 0; k < N; k++) {
			if ((j + k) % 3 != now) continue;
			cnt += D[c[j][k]][col];
		}
	}
	return dp2[status] = cnt;
}

int dfs(short now, int color) {
	if (now == 3) return 0;
	auto status = make_tuple(now, color);
	if (dp.count(status)) return dp[status];
	int res = numeric_limits<int>::max();
	for (short i = 0; i < C; i++) {
		if (color & (1 << i)) continue;
		int cnt = 0;
		cnt += add(now, i);
		res = min(res, cnt + dfs(now + 1, color | (1 << i)));
	}
	return dp[status] = res;
}

