			mod[(i + j) % 3][c[i][j] - 1]++;
		}
	}

	// group i の色を j に変える
	ll ans = INT64_MAX;
	ll a[3];
	for (a[0] = 0; a[0] < C; a[0]++) {
		for (a[1] = 0; a[1] < C; a[1]++) {
			if (a[0] == a[1]) continue;
			for (a[2] = 0; a[2] < C; a[2]++) {
				if (a[0] == a[2] || a[1] == a[2]) continue;

				ll cost = 0;

				for (ll m = 0; m < 3; m++) {
					for (const auto& e : mod[m]) {
						ll val = e.first;
						ll num = e.second;
						cost += D[val][a[m]] * num;
					}
				}

				ans = min(ans, cost);
			}
		}
	}

	cout << ans << endl;

	return 0;
}

