const int K = 3;
const int INF = 1e9;

int N, C;
int d[MAX_C][MAX_C];
int c[MAX_N][MAX_N];
int pat[K];
bool used[MAX_C];
int cnt[K][MAX_C];

int calc() {
    int sum_d = 0;
    for (int k = 0; k < K; k++) {
        for (int i = 0; i < C; i++) {
            sum_d += d[i][pat[k]] * cnt[k][i];
        }
    }
    return sum_d;
}

int dfs(int k) {
    if (k >= K) {
        return calc();
    }

    int ans = INF;
    for (int i = 0; i < C; i++) {
        if (used[i]) {
            continue;
        }
        used[i] = true;
        pat[k] = i;
        ans = min(ans, dfs(k + 1));
        used[i] = false;
    }
    return ans;
}

int solve() {
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            cnt[(i + j) % K][c[i][j]]++;
        }
    }

    return dfs(0);
}

