//二項係数の剰余を求める
//引数は剰余の形ではなくもとの数そのものである
//未検証(検証サンプルがない)
long long modC(long long n, long long k, long long mod)
{
	if (n < k)
		return 0;
	long long p = 1, q = 1;
	for (long long i = 0; i < k; i++)
	{
		p = p * (n - i) % mod;
		q = q * (i + 1) % mod;
	}
	return p * modinv(q, mod) % mod;
}

//20200418
// 整数のとき限定の普通のPOW関数
//標準機能のpow(a,n)は整数だとバグるのでこちらを使う
long long POW(long long a, long long n)
{
	long long res = 1;
	while (n > 0)
	{
		if (n & 1)
			res = res * a;
		a = a * a;
		n >>= 1;
	}
	return res;
}

//20200423
//エラトステネスのふるいによりn以下の素数を全てベクトルに入れて返す
vector<long long> eratos(long long n)
{
	if (n < 2)
		return {};
	vll v(n - 1);
	rep(i, n - 1)
	{
		v[i] = i + 2; //2からnまで
	}
	ll i = 0;
	while (i < n - 1)
	{
		ll p = v[i];
		for (ll j = i + 1; j < n - 1; j++)
		{
			if (v[j] % p == 0)
			{
				v.erase(v.begin() + j);
				n--;
			}
		}
		i++;
	}
	v.resize(n - 1);
	return v;
}

