  for (int i = 0; i < N; ++i) cin >> c[i];

  map<int, vector<LL>> m;
  for (int x = 0; x < C; ++x) {
    m[x] = vector<LL>(3, 0);
    for (int i = 0; i < N; ++i) {
      for (int j = 0; j < N; ++j) {
        int before = c[i][j]-1;
        m[x][(i + j) % 3] += D[before][x];
      }
    }
  }

  LL min_score = 1e18;
  for (int a = 0; a < C; ++a) {
    for (int b = 0; b < C; ++b) {
      if (a == b) continue;
      for (int c = 0; c < C; ++c) {
        if (c == a || c == b) continue;
        LL score = m[a][0] + m[b][1] + m[c][2];
        min_score = min(min_score, score);
      }
    }
  }
  cout << min_score << endl;
}

