	IO >> n >> m;
	::std::vector<::std::vector<uint32>> d(m, ::std::vector<uint32>(m)),
		c(n, ::std::vector<uint32>(n));
	for (auto &x : d)
		for (auto &e : x)
			IO >> e;
	for (auto &x : c)
		for (auto &e : x)
			IO >> e, --e;
	::std::array<::std::vector<uint32>, 3> cnt, cost;
	for (auto &e : cnt)
		e.resize(m, 0);
	for (const auto i : rep(0, n))
		for (const auto j : rep(0, n))
			++cnt[(i + j) % 3][c[i][j]];
	for (const auto t:rep(0,3)) {
		cost[t].resize(m, 0);
		for (const auto i : rep(0, m))
			for (const auto j : rep(0, m))
				cost[t][j] += d[i][j] * cnt[t][i];
	}
	uint32 ans = INF;
	for (const auto c0 : rep(0, m))
		for (const auto c1 : rep(0, m))
			for (const auto c2 : rep(0, m))
				if (c0 != c1&&c1 != c2&&c2 != c0)
					smini(ans, cost[0][c0] + cost[1][c1] + cost[2][c2]);
