void solve(){
  int n,c;
  cin>>n>>c;
  int ans=1e9;
  set<int>zero,one,two;
  vector<vector<int>>d(c,vector<int>(c)),g(n,vector<int>(n));
  rep(i,c)rep(j,c){
    cin>>d[i][j];
  }
  rep(i,n)rep(j,n){
    cin>>g[i][j];
    g[i][j]--;
    if((i+j)%3==0)zero.insert(g[i][j]);
    else if((i+j)%3==1)one.insert(g[i][j]);
    else two.insert(g[i][j]);
  }
  if(n<=2){
    rep(i,n){
      zero.insert(i);
      one.insert(i);
      two.insert(i);
    }
  }
  rep(i,c){
    rep(j,c){
      rep(k,c){
        bool flag=true;
        if(i==j or i==k or j==k)continue;
        int sum=0;
        rep(h,n){
          rep(w,n){
            if((h+w)%3==0){
              if(!zero.count(i)){
                flag=false;
                break;
              }
              sum+=d[g[h][w]][i];
            }
            else if((h+w)%3==1){
              if(!one.count(j)){
                flag=false;
                break;
              }
              sum+=d[g[h][w]][j];
            }
            else {
              if(!two.count(k)){
                flag=false;
                break;
              }
              sum+=d[g[h][w]][k];
            }
          }
          if(!flag)break;
        }
        if(flag)chmin(ans,sum);
      }
    }
  }
  cout<<ans<<"\n";
}

