void solve() {
    i64 N; RD(N);
    i64 C; RD(C);

    auto D = ndarray_make<i64>(C,C, 0);
    REP(from, C) REP(to, C) {
        RD(D[from][to]);
    }

    auto M = ndarray_make<i64>(N,N, 0);
    REP(y, N) REP(x, N) {
        i64 c; RD(c); --c;  // 0-based
        M[y][x] = c;
    }

    i64 ans = INF;
    vector<i64> cs(C);
    ALL(iota, cs, 0);
    do {
        DBG(cs);
        i64 cur = 0;
        REP(y, N) REP(x, N) {
            i64 r = (x+y) % 3;
            i64 from = M[y][x];
            i64 to   = cs[r];
            cur += D[from][to];
            DBG(TUPLE(r,from,to,D[from][to]));
        }
        chmin(ans, cur);
    } while(next_partial_permutation(begin(cs), begin(cs)+3, end(cs)));

    // * 無効値 INF をそのまま出力してない?
    // * MOD はとった?
    // * 入出力の 0-based/1-based 確認した?
    // * 時間/メモリ制限は確認した?
    // * 違うやつ提出してない?
    // * 違うやつテストしてない?
    PRINTLN(ans);
}

signed main() {


    solve();

    EXIT();
}

