const int N= 501;
const int M= 31;

int ar[N][N];
int cost[M][M];
int ne[N][N];
int v[N][N];

void solve() {

        int n, m; cin >> n>> m;

        for (int i= 1; i< N; i++)
                for (int j= 1; j< N; j++) v[i- 1][j- 1]= (i+ j)% 3;

        for (int i= 1; i<= m; i++)
                for (int j= 1; j<= m; j++) cin >> cost[i][j];

        for (int i= 0; i< n; i++)
                for (int j= 0; j< n; j++) cin >> ar[i][j];

        int f[4]= {0}, ans= 1e18;

        auto calc= [&]() {
                int an= 0;
                for (int i= 0; i< n; i++) {
                        for (int j= 0; j< n; j++) {
                                if (ar[i][j]!= ne[i][j]) {
                                        an+= cost[ar[i][j]][ne[i][j]];
                                }
                        }
                }
                return an;
        };

        for (int i= 1; i<= m; i++) {
                for (int j= 1; j<= m; j++) {
                        if (i== j) continue;

                        for (int k= 1; k<= m; k++) {
                                if (i== j|| i== k|| j== k) continue;
                                f[0]= i;
                                f[1]= j;
                                f[2]= k;

                                for (int ii= 0; ii< n; ii++)
                                        for (int jj= 0; jj< n; jj++) ne[ii][jj]= f[v[ii][jj]];

                                ans= min(ans, calc());
                        }
                }
        }
        cout << ans<< "\n";
}

