        int x; scanf("%d", &x);
        v[(i + j) % 3].emplace_back(x);
    }


    for(int i = 1; i <= c; ++i) {
        cost[0].emplace_back(chk(v[0], i));
        cost[1].emplace_back(chk(v[1], i));
        cost[2].emplace_back(chk(v[2], i));
    }

    int res = 1e9;
    for(int i = 0; i < c; ++i) {
        for(int j = 0; j < c; ++j) if(i != j) {
            for(int k = 0; k < c; ++k) if(i != k and j != k) {
                res = min(res, cost[0][i] + cost[1][j] + cost[2][k]);
            }
        }
    }

    printf("%d\n", res);
}

