int N, C;

int dfs(int from, int mod, vector<bool> color_used, vector<bool> mod_used, vector< vector<int> >& D, vector< vector<int> >& c) {
    // cerr << "color: " << from << " mod: " << mod << endl;
    color_used[from] = true;
    mod_used[mod] = true;

    int c_tmp = 0;
    // cerr << "calc score for (" << from << ", " << mod << ")" << endl;
    REP(x, N){
        REP(y, N){
            // cerr << "(x, y) = (" << x << ", " << y << "), c[y][x] = " << c[y][x] << " from = " << from << endl;
            if((x+y)%3 == mod) {
                c_tmp += D[c[y][x]-1][from];
            }
        }
    }

    bool remain = false;
    REP(mod_, 3) if(!mod_used[mod_]) remain = true;
    if(!remain){
        // cerr << "don't exec recursive call, c_tmp = " << c_tmp << endl;
        return c_tmp;
    }

    int d_sum = 1e9;
    bool call = false;

    REP(mod_, 3) {
        if(!mod_used[mod_]) {
            REP(color, C){
                if(!color_used[color]) {
                    int d_sum_tmp = dfs(color, mod_, color_used, mod_used, D, c);
                    if(d_sum > d_sum_tmp) {
                        // cerr << "d_sum_tmp = " << d_sum_tmp << endl;
                        d_sum = d_sum_tmp;
                        call = true;
                    }
                }
            }
        }
    }

    // if(!call) d_sum = 0;
    // cerr << "c_tmp = " << c_tmp << " d_sum = " << d_sum << endl;
    return c_tmp + d_sum;
}

int main() {
    cin >> N >> C;
    vector< vector<int> > D(C, vector<int>(C)), c(N, vector<int>(N));
    REP(i, C) REP(j, C) cin >> D[i][j];
    REP(i, N) REP(j, N) cin >> c[i][j];

    vector<bool> color_used(C, false), mod_used(3, false);

    int ans = 1e9;
    REP(color, C) {
        REP(mod, 3) {
            int tmp = dfs(color, mod, color_used, mod_used, D, c);
            if(tmp < ans) ans = tmp; 
        }
    }

    cout << ans << endl;

    return 0;
}

