using namespace std;
int D[35][35], col[510][510], counter[3][35];
int N, C;
int main() {
	cin >> N >> C;
	for (int i = 1; i <= C; i++) {
		for (int j = 1; j <= C; j++) {
			cin >> D[i][j];
		}
	}
	for (int i = 1; i <= N; i++) {
		for (int j = 1; j <= N; j++) {
			cin >> col[i][j];
		}
	}
	for (int i = 1; i <= N; i++){
		for (int j = 1; j <= N; j++) {
			if ((i + j) % 3 == 0) counter[0][col[i][j]]++;
			if ((i + j) % 3 == 1) counter[1][col[i][j]]++;
			if ((i + j) % 3 == 2) counter[2][col[i][j]]++;
		}
	}
	long long score = 1e9;
	for (int i = 1; i <= C; i++) {
		for (int j = 1; j <= C; j++) {
			if (i == j) continue;
			for (int k = 1; k <= C; k++) {
				if (k == i || k == j) continue;
				long long temp = 0;
				for (int s = 1; s <= C; s++) temp += counter[0][s] * D[s][i];
				for (int s = 1; s <= C; s++) temp += counter[1][s] * D[s][j];
				for (int s = 1; s <= C; s++) temp += counter[2][s] * D[s][k];
				if (score > temp) score = temp;
			}
		}
	}
	cout << score << endl;
}

