      stk.push(name[idx]);
    if(name[idx]==')' || name[idx]=='}')
      stk.pop();
  }
  print_raw(name.substr(0,idx),": ");
  print(arg);
  print_dbg(name.substr(idx==name.size() ? 0 : idx+1),args...);
}
