  long ans = bar[0][1] + bar[1][2] + bar[2][3];
  for (long a = 1; a <= C; a++) {
    for (long b = 1; b <= C; b++) {
      if (a == b) continue;
      for (long c = 1; c <= C; c++) {
        if (b == c or c == a) continue;
        long tmp = bar[0][a] + bar[1][b] + bar[2][c];
        ans = min(ans, tmp);
      }
    }
  }
  cout << ans << endl;
}

