    rep(ii,C) t+=cnt[0][ii]*D[ii][i];
    rep(ij,C) t+=cnt[1][ij]*D[ij][j];
    rep(ik,C) t+=cnt[2][ik]*D[ik][k];
    chmin(ans,t);
  }
  cout << ans << endl;
}

