#define MAX_N (500)
#define MAX_C (30)
#define INF (1000000000)

using namespace std;

int main(int argc, char *argv[]) {
  // read inputs
  int N, C, Ds[MAX_N * MAX_N], cs[MAX_N * MAX_N];
  scanf("%d %d", &N, &C);
  for (int i = 0; i < C; i++) {
    for (int j = 0; j < C; j++) {
      scanf("%d", &Ds[j + i * C]);
    }
  }
  for (int i = 0; i < N; i++) {
    for (int j = 0; j < N; j++) {
      scanf("%d", &cs[j + i * N]);
      cs[j + i * N]--;  // NOTE : changed input
    }
  }

  // count how many colors there are in each group
  int num_colors[3 * MAX_C] = {};
  for (int i = 0; i < N; i++) {
    for (int j = 0; j < N; j++) {
      const int color = cs[j + i * N], group = (i + j) % 3;
      num_colors[color + group * C]++;
    }
  }

  // solve
  int ans = INF;
  for (int c0 = 0; c0 < C; c0++) {    // color of first group
    for (int c1 = 0; c1 < C; c1++) {  // color of second group
      if (c1 == c0) {
        continue;
      }
      for (int c2 = 0; c2 < C; c2++) {  // color of third group
        if (c2 == c0 || c2 == c1) {
          continue;
        }
        // calculate the cost to change colors
        int cost = 0;
        for (int c = 0; c < C; c++) {
          cost += num_colors[c + 0 * C] * Ds[c0 + c * C];
        }
        for (int c = 0; c < C; c++) {
          cost += num_colors[c + 1 * C] * Ds[c1 + c * C];
        }
        for (int c = 0; c < C; c++) {
          cost += num_colors[c + 2 * C] * Ds[c2 + c * C];
        }
        ans = min(ans, cost);
      }
    }
  }
  printf("%d\n", ans);

  return 0;
}

