int solve(int zero, int one, int two) {
	int ret = 0;
	rep (i, N) {
		rep (j, N) {
			int I = i+1, J = j+1;
			if ((I+J)%3 == 0) {
				ret += D[c[i][j]-1][zero-1];
			}
			if ((I+J)%3 == 1) {
				ret += D[c[i][j]-1][one-1];
			}
			if ((I+J)%3 == 2) {
				ret += D[c[i][j]-1][two-1];
			}
		}
	}
	return ret;
}

