llint totalDist(int mod3, int next)
{
    llint total = 0;
    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= N; ++j) {
            if ((i + j) % 3 == mod3) {
                int cur = color[(i - 1) * N + j - 1];
                total += D[(cur - 1) * C + next - 1];
            }
        }
    }
    return total;
}

