        color.push_back(n);
    }

    llint minDist = -1;
    for (int c0 = 1; c0 <= C; ++c0) {
        llint d0 = totalDist(0, c0);
        for (int c1 = 1; c1 <= C; ++c1) {
            if (c1 == c0) continue;
            llint d1 = totalDist(1, c1);
            for (int c2 = 1; c2 <= C; ++c2) {
                if (c2 == c0) continue;
                if (c2 == c1) continue;
                llint d2 = totalDist(2, c2);
                if (minDist == -1 || d0 + d1 + d2 < minDist)
                    minDist = d0 + d1 + d2;
