ll wrongness(vector<int>& perm, vector<pii>* count) {
  ll sum = 0;
  for(int i=0; i<3; i++) {
    for(int j=0; j<count[i].size(); j++) {
      pii p = count[i][j];
      sum += d[p.first-1][perm[i]-1] * p.second;
    }
  }
  return sum;
}

