void solve()
{
    int N, C; cin >> N >> C;
    vvi D(C+1, vi(C+1)); REP1(i, C) REP1(j, C) cin >> D[i][j];
    vvi c(N+1, vi(N+1)); REP1(i, N) REP1(j, N) cin >> c[i][j];
    vvi color(3, vi(C+1, 0));
    REP1(i, N)
    {
        REP1(j, N)
        {
            if((i+j) % 3 == 1) color[1][c[i][j]]++;
            else if((i+j) % 3 == 2) color[2][c[i][j]]++;
            else color[0][c[i][j]]++;
        }
    }

    int ans = INF;
    REP1(i, C) // % 3 == 0
    {
        REP1(j, C) // 1
        {
            if(i == j) continue;
            REP1(k, C) // 2
            {
                if(i == k || j == k) continue;
                int d = 0;
                REP1(l, C)
                {
                    d += D[l][i] * color[0][l];
                    d += D[l][j] * color[1][l];
                    d += D[l][k] * color[2][l];
                }
                ans = min(ans, d);
            }
        }
    }

    cout << ans << endl;
}

