int cal(vector<int>& freqs, int color, vector<vector<int>>& D, int C)
{
  int ret = 0;
  for (int i = 1; i <= C; ++i) {
    ret += freqs[i] * D[i][color];
  }
  return ret;
}

int main()
{
  int N, C; scanf("%d %d", &N, &C);
