int cnt[3][MAXC];

void solve() {
  for (int i=0;i<n;i++) {
    for (int j=0;j<n;j++) {
      cnt[(i + j + 2) % 3][grid[j][i]-1]++;
    }
  }
  vector<P> minCost[3];
  for (int i=0;i<3;i++) {
    for (int j=0;j<c;j++) {
      int tmp = 0;
      for (int k=0;k<c;k++) {
        tmp += cnt[i][k] * d[j][k];
      }
      minCost[i].push_back(P(tmp, j));
    }
    sort(minCost[i].begin(), minCost[i].end());
  }
  int cost = INF;
  for (int i=0;i<3;i++) {
    for (int j=0;j<3;j++) {
      for (int k=0;k<3;k++) {
        if (minCost[0][i].second != minCost[1][j].second &&
            minCost[1][j].second != minCost[2][k].second &&
            minCost[2][k].second != minCost[0][i].second) {
          cost = min(cost, minCost[0][i].first + minCost[1][j].first + minCost[2][k].first);
        }
      }
    }
  }
  cout << cost << endl;
}

