    optional<T> &operator()(int i, int j, int k) {        if (i < 0 || j < 0 || sz(v) <= i || sz(v[i]) <= j) {            if(k < 0 || sz(v[i][j]) <= k){                emp.reset();                return emp;            }        }        return v[i][j][k];    }
