#define INF (1e9)

int main() {
  int n, cn;
  cin >> n >> cn;
  int tmp;
  vector<vector<int> > d(cn, vector<int>(cn));

  for (int i = 0; i < cn; i++) {
    for (int j = 0; j < cn; j++) {
      cin >> tmp;
      d[i][j] = tmp;
    }
  }

  vector<vector<int> > c(n, vector<int>(n));
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      int tmp;
      cin >> tmp;
      c[i][j] = tmp;
    }
  }
  vector<int> dis0s;
  vector<int> dis1s;
  vector<int> dis2s;

  for (int k = 0; k < cn; k++) {
    int dis0 = 0;
    int dis1 = 0;
    int dis2 = 0;

    for (int i = 0; i < n; i++) {
      for (int j = 0; j < n; j++) {
        int c_be = c[i][j] - 1;  //変わる前の色

        if ((i + 1 + j + 1) % 3 == 0) {
          dis0 += d[c_be][k];
        } else if ((i + 1 + j + 1) % 3 == 1) {
          dis1 += d[c_be][k];
        } else {
          dis2 += d[c_be][k];
        }
      }
    }

    dis0s.push_back(dis0);
    dis1s.push_back(dis1);
    dis2s.push_back(dis2);
  }
  int ans = INF;
  for (int i = 0; i < cn; i++) {
    for (int j = 0; j < cn; j++) {
      for (int k = 0; k < cn; k++) {
        if (i != j && j != k && i != k) {
          ans = min(dis0s[i] + dis1s[j] + dis2s[k], ans);
        }
      }
    }
  }

  cout << ans << endl;

  return 0;
}

