using namespace std;

const long long MOD = 1000000007LL;
long long GCD(long long a, long long b){return b == 0 ? a : GCD(b, a % b);}

long long grid[501][501];
long long valu[31][31];

long long freq[3][31];

int main(){

    cin.sync_with_stdio(0); cin.tie(0); cout.tie(0);

    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout);

    int n, c;

    cin >> n >> c;

    for(int i = 0; i < c; ++i){
        for(int j = 0; j < c; ++j){
            cin >> valu[i][j];
        }
    }

    for(int i = 0; i < n; ++i){
        for(int j = 0; j < n; ++j){
            cin >> grid[i][j];
        }
    }

    // Preprocess

    for(int offset = 0; offset < 3; ++offset){

        int X = 0, Y = offset;

        while(X < n || Y < n){
            int y = Y;
            int x = X;
            while(x < n && y >= 0){
                freq[offset][grid[x][y] - 1]++;
                y--; x++;
            }
            if(Y + 3 < n){
                Y += 3;
            } else {
                X += 3 - ((n - 1) - Y);
                if(X >= n)
                    break;
                Y = n - 1;
            }
        }

    }

    long long best = -1;

    for(int ca = 0; ca < c; ++ca){

        long long costa = 0;

        for(int other = 0; other < c; ++other)
            costa += valu[other][ca] * freq[0][other];

        for(int cb = 0; cb < c; ++cb){

            if(ca == cb)
                continue;

            long long costb = 0;

            for(int other = 0; other < c; ++other)
                costb += valu[other][cb] * freq[1][other];

            for(int cc = 0; cc < c; ++cc){

                if(ca == cc || cc == cb)
                    continue;

                long long costc = 0;

                for(int other = 0; other < c; ++other)
                    costc += valu[other][cc] * freq[2][other];

                if(best == -1){
                    best = costa + costb + costc;
                } else {
                    best = min(best, costa + costb + costc);
                    //cout << costa << " " << costb << " " << costc << endl;
                }

            }
        }
    }

    cout << best;

    return 0;
}

