      for (int c = 1; c <= C; c++) {
        wrongness += d[0][c]*D[c][p[0]];
        wrongness += d[1][c]*D[c][p[1]];
        wrongness += d[2][c]*D[c][p[2]];
      }
      answer = min(answer,wrongness);
      } while (next_permutation(p.begin(),p.end()));
  }
  cout << answer;
}

