template<typename T>
void warshall_floyd(T& d){
  int N = sz(d[0]);
  for(int i = 0 ; i < N ; i++)
    d[i][i] = 0;
  for(int k = 0 ; k < N ; k++)
    for(int i = 0 ; i < N ; i++)
      for(int j = 0 ; j < N ; j++)
        d[i][j] = min(d[i][j] , d[i][k] + d[k][j]);
}

void solve(){
  ini(N,C);
  vvl d(C,vl(C)); in(d);
  //warshall_floyd(d);

  trc(d);
  vvl c(N,vl(N)); in(c);
  vvl cnt(3,vl(C));
  rep(i,N) rep(j,N){
    cnt[(i+j)%3][c[i][j]-1]++;
  }

  auto f = [&](vl &v,int c)->ll{
    ll ret = 0;
    rep(i,C){
      ret += v[i] * d[i][c];
    }
    return ret;
  };

  //trc(cnt);

  vvl ans(3,vl(C));
  rep(i,3)rep(j,C) ans[i][j] = f(cnt[i],j);

  ll bns = infLL;
  rep(i,C)rep(j,C)rep(k,C){
    if(i!=j&&j!=k&&k!=i) amin(bns,ans[0][i]+ans[1][j]+ans[2][k]);
  }
  out(bns);
}

