int N, C;
vector<vector<int> > D;
vector<vector<int> > c;
map<tuple<int, long long>, int> dp;

int add(int now, int col) {
	int cnt = 0;
	for (int j = 0; j < N; j++) {
		for (int k = 0; k < N; k++) {
			if ((j + k) % 3 != now) continue;
			cnt += D[c[j][k]][col];
		}
	}
	return cnt;
}

int dfs(int now, long long color) {
	if (now == 3) return 0;
	auto status = make_tuple(now, color);
	if (dp.count(status)) return dp[status];
	int res = numeric_limits<int>::max();
	for (int i = 0; i < C; i++) {
		if (color & (1L << i)) continue;
		int cnt = 0;
		cnt += add(now, i);
		res = min(res, cnt + dfs(now + 1, color | (1L << i)));
	}
	return dp[status] = res;
}

