void solve() {
    i64 N; RD(N);
    i64 C; RD(C);

    auto D = ndarray_make<i64>(C,C, 0);
    REP(from, C) REP(to, C) {
        RD(D[from][to]);
    }

    auto M = ndarray_make<i64>(N,N, 0);
    REP(y, N) REP(x, N) {
        i64 c; RD(c); --c;  // 0-based
        M[y][x] = c;
    }

    auto cost = ndarray_make<i64>(3,C, 0);
    REP(to, C) REP(y, N) REP(x, N) {
        i64 r = (x+y) % 3;
        i64 from = M[y][x];
        cost[r][to] += D[from][to];
    }

    i64 ans = INF;
    vector<i64> tos(C);
    ALL(iota, tos, 0);
    do {
        i64 cur = 0;
        REP(r, 3){
            i64 to = tos[r];
            cur += cost[r][to];
        }
        chmin(ans, cur);
    } while(next_partial_permutation(begin(tos), begin(tos)+3, end(tos)));

