int main() {
	int N, C;
	std::cin >> N >> C;

	std::vector<std::vector<int>> D(C, std::vector<int>(C));
	for(int i = 0; i < C; i++) {
		for(int j = 0; j < C; j++) {
			std::cin >> D[i][j];
		}
	}

	std::vector<std::vector<int>> c(N, std::vector<int>(N));
	for(int i = 0; i < N; i++) {
		for(int j = 0; j < N; j++) {
			std::cin >> c[i][j];
		}
	}

	// 余りで3つに分ける（rem[i] はあまりiの者たち）
	std::vector<std::vector<int>> rem(3);
	for(int i = 0; i < N; i++) {
		for(int j = 0; j < N; j++) {
			rem[(i + j) % 3].emplace_back(c[i][j] - 1);
		}
	}

	// cost[i][j] あまりiを色jに変えるコスト
	std::vector<std::vector<int>> cost(3, std::vector<int>(C, 0));
	for(int ci = 0; ci < C; ci++) {
		for(int ri = 0; ri < 3; ri++) {
			for(int ori : rem[ri]) {
				cost[ri][ci] += D[ori][ci];
			}
		}
	}

	int min = std::numeric_limits<int>::max();
	for(int c1 = 0; c1 < C; c1++) {
		for(int c2 = 0; c2 < C; c2++) {
			for(int c3 = 0; c3 < C; c3++) {
				if(c1 != c2 && c2 != c3 && c3 != c1) {
					min = std::min(min, cost[0][c1] + cost[1][c2] + cost[2][c3]);
				}
			}
		}
	}

	std::cout << min << std::endl;

	return 0;
}

