//partial_permutation nPr 順列
//first・・最初の数
//middle・・r(取り出す数)
//last・・n(全体数)
template<class Iter>
bool next_partial_permutation(Iter first, Iter middle, Iter last) {
    reverse(middle, last);
    return next_permutation(first, last);
}

int main() {

    long long N, C;
    cin >> N >> C;

    vector<vector<long long>> D(C, vector<long long>(C));
    for (int i = 0; i < C; i++)for (int j = 0; j < C; j++) cin >> D[i][j];

    vector<vector<long long>> c(N, vector<long long>(N));
    for (int i = 0; i < N; i++) for (int j = 0; j < N; j++) cin >> c[i][j], c[i][j]--;

    vector<vector<long long >> A(3, vector<long long>(C, 0));
    for (int i = 0; i < N; i++) for (int j = 0; j < N; j++) A[(i + j) % 3][c[i][j]]++;

    vector<long long> B(C);
    for (int i = 0; i < C; i++) B[i] = i;

    long long ans = LONG_LONG_MAX;
    do {
        long long sum = 0;
        for (int i = 0; i < 3; i++)for (int j = 0; j < C; j++)sum += D[j][B[i]] * A[i][j];
        ans = min(ans, sum);
    } while (next_partial_permutation(B.begin(), B.begin() + 3, B.end()));

    cout << ans << endl;

    return 0;
}

