  vector<vector<int>> color(3, vector<int>(c, 0));
  for(int i = 0; i < n; i++)
  {
    for(int j = 0; j < n; j++)
    {
      int temp = i + 1 + j + 1;
      temp = temp % 3;
      color[temp][grid[i][j] - 1]++;
    }
  }
  long long int mind = 1000 * n * n;
  auto check = [&](int c0, int c1, int c2)
  {
    long long int diff = 0;
    for(int i = 0; i < 3; i++)
    {
      for(int j = 0; j < c; j++)
      {
        if(i == 0)
        {
          diff += color[i][j] * d[j][c0 - 1];
        }else if(i == 1)
        {
          diff += color[i][j] * d[j][c1 - 1];
        }else{
          diff += color[i][j] * d[j][c2 - 1];
        }
      }
    }
    return diff;
  };
  for(int i = 1; i <= c; i++)
  {
    for(int j = 1; j <= c; j++)
    {
      for(int k = 1; k <=c; k++)
      {
        if(i == j || j == k || i == k) continue;
        long long int temp = check(i, j, k);
        mind = min(mind, temp);
      }
    }
  }
  cout << mind << endl;
  return 0;
}

