    memset(colorcnts, 0, sizeof(colorcnts));
    srep (i, 1, n+1) {
        srep (j, 1, n+1) {
            ll group = (i + j) % 3LL;
            ll color = colors[i][j];
            colorcnts[group][color]++;
        }
    }

    S ll damages[3][33];
    memset(damages, 0, sizeof(damages));
    rep (group, 3LL) {
        srep (color, 1, c+1LL) {
            srep (ncolor, 1, c+1LL) {
                ll incr = dmap[color][ncolor] * colorcnts[group][color];
                damages[group][ncolor] += incr;
            }
        }
    }

    t2 cands[3][3];
    rep (group, 3LL) {
        V<t2> gdamages;
        srep (ncolor, 1LL, c+1LL) {
            gdamages.pb(t2(damages[group][ncolor], ncolor));
        }
        sort(gdamages);
        cands[group][0] = gdamages[0];
        cands[group][1] = gdamages[1];
        cands[group][2] = gdamages[2];
    }

    ll ans = 1e18;

    rep (g0, 3LL) {
        rep (g1, 3LL) {
            rep (g2, 3LL) {
                t2 cand0 = cands[0][g0];
                t2 cand1 = cands[1][g1];
                t2 cand2 = cands[2][g2];
                if (get<1>(cand0) == get<1>(cand1)) continue;
                if (get<1>(cand1) == get<1>(cand2)) continue;
                if (get<1>(cand2) == get<1>(cand0)) continue;
                ll sum = get<0>(cand0) + get<0>(cand1) + get<0>(cand2);
                ans = min(ans, sum);
            }
        }
    }

    cout << ans << endl;
}

