                sum_cost_table[i][j] += cnt_table[i][k] * cost_table[k][j];
            }
        }
    }

    ll ans = LINF;
    for(int i = 0; i < C - 2; i++) {
        for(int j = i + 1; j < C - 1; j++) {
            for(int k = j + 1; k < C; k++) {
                vector<int> color{i, j, k};
                do {
                    ll cost = 0;
                    REP(l, 3) {
                        cost += sum_cost_table[l][color[l]];
                    }
                    ans = min(ans, cost);
                } while(std::next_permutation(color.begin(), color.end()));
            }
        }
    }

    std::cout << ans << std::endl;

    return 0;
}

