	int Rank[MAX_N];//木の深さ

	void init(int n) {
		REP(i, n) {
			par[i] = i;//rootの親は自分に設定しておくことでrootの判別ができる
			Rank[i] = 0;
		}
	}

	//xのrootを求める
	int find(int x) {
		//root
		if (par[x] == x) {
			return x;
		}
		else {
			return par[x] = find(par[x]);//ここで親を貼り直している
		}
	}

	//木の統合
	void unite(int x, int y) {
		//x = find(x), y = find(y);//親ノードの検出
		if (x == y) { return; }//何もしない

							   //併合の際に２つの木の高さが異なれば高さの小さいものが大きい物の根へと辺をはる
		if (Rank[x] < Rank[y]) {
			par[x] = y;
			//Rank[y]のほうが深いのでRankの更新は行わなくて良い
		}
		else {
			par[y] = x;
			//２つの根が同じ深さの場合は１つの根がもうひとつの根につくわけなので深さは1増える
			if (Rank[x] == Rank[y]) { Rank[x]++; }
		}
		/*if (vact[x] > vact[y]) {
			par[y] = x;
		}
		else {
			par[x] = y;
		}*/
	}

	bool same(int x, int y) {
		return find(x) == find(y);
	}
}


class matrix : public vector< vector<int> > {
private:
	int tate_, yoko_;
public:
	matrix(const int tate__, const int yoko__) {
		assert(tate__ > 0); assert(yoko__ > 0);
		resize(tate__);
		for (size_t i = 0; i < size(); i++) { (*this)[i].resize(yoko__); }
		tate_ = tate__; yoko_ = yoko__;
	}
	matrix() {};
	int tate()const { return tate_; }
	int yoko()const { return yoko_; }
	void resizematrix(const int tate__, const int yoko__) {
		assert(tate__ > 0); assert(yoko__ > 0);

		resize(tate__);
		for (size_t i = 0; i < size(); i++) {
			(*this)[i].resize(yoko__);
		}
		tate_ = tate__; yoko_ = yoko__;
	}
	void setone() {
		for (int i = 0; i<tate(); i++)  for (int j = 0; j < yoko(); j++) { (*this)[i][j] = 1; }
	}
	void setzero() {
		for (int i = 0; i<tate(); i++) for (int j = 0; j < yoko(); j++) { (*this)[i][j] = 0; }
	}
	void setchar(char a) {
		for (int i = 0; i<tate(); i++) for (int j = 0; j < yoko(); j++) { (*this)[i][j] = a; }
	}
};
