int draw(int zer, int one, int two){
    int ret = 0;
    rep(i,N)rep(j,N){
        if((i+j)%3 == 0) ret += D[c[i][j]][zer];
        else if((i+j)%3 == 1) ret += D[c[i][j]][one];
        else ret += D[c[i][j]][two];
    }
    return ret;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> N >> C;
    rep(i,C)rep(j,C) cin >> D[i][j];
    rep(i,N)rep(j,N){
        cin >> c[i][j];
        c[i][j]--;
    }
    int ans = 1e9;
    rep(i,C){
        rep(j,C){
            if(i == j) continue;
            rep(k,C){
                if(i == k || j == k) continue;
                chmin(ans, draw(i,j,k));
            }
        }
    }
    cout << ans << endl;
    return 0;
}

