ll modpower(ll x, ll y, ll p) //x^y mod p
{
    ll res = 1;      // Initialize result

    x = x % p;  // Update x if it is more than or 
                // equal to p

    while (y > 0)
    {
        // If y is odd, multiply x with result
        if (y %2!= 0)
            res = (res*x) % p;

        // y must be even now
        y = y/2;
        x = (x*x) % p;  
    }
    return res;
}

