using namespace std;


struct Node{
    ll pos;
    vector<bool> used;
    ll cost;
    bool operator< (const Node &r) const{
        return cost > r.cost;
    }
};

ll solve(ll n, ll c, vector<vector<ll>> d, vector<vector<ll>> f){
    rep(hx, n){
        rep(wx, n) f[hx][wx]--;
    }

    vector<map<ll, ll>> v(3, map<ll, ll>());
    rep(hx, n){
        rep(wx, n){
            ll idx = (hx+wx)%3;
            v[idx][f[hx][wx]]++;
        }
    }

    vector<vector<ll>> list(3, vector<ll>(c, 1e10));
    rep(i, 3){
        auto m = v[i];
        rep(to, c){
            ll sum = 0;
            for(auto from = m.begin(); from != m.end(); from++){
                sum += from->second * d[from->first][to];
            }
            list[i][to] = sum;
        }
    }

    priority_queue<Node> que;
    que.push({0, vector<bool>(c, false), 0});

    while(!que.empty()){
        Node node = que.top(); que.pop();

        if(node.pos == 3) return node.cost;

        rep(i, c){
            if(node.used[i]) continue;
            vector<bool> v = node.used;
            v[i] = true;
            que.push({node.pos+1, v, node.cost+list[node.pos][i]});
        }
    }

    return 1e10;
}

