	vll cset, cused(c);
	REP(i, n){
		REP(j, n){
			cin >> a[i][j];
			a[i][j]--;
			if(!cused[a[i][j]]) cset.push_back(a[i][j]);
			cused[a[i][j]] = 1;
		}
	}
	ll k = cset.size();
	ll res = 1e18, tmp;
	// choose using color
	REP(l0, k){
		REP(l1, k){
			REP(l2, k){
				if(l0 == l1 || l1 == l2 || l2 == l0) continue;
				vll l = {l0, l1, l2};
				//calc penalty
				tmp = 0;
				REP(i, n){
					REP(j, n){
						tmp += d[a[i][j]][cset[l[(i + j) % 3]]];
						if(tmp > res) break;
					}
					if(tmp > res) break;
				}
				res = min(res, tmp);
			}
		}
	}
	cout << res << endl;
    return 0;
}

