#define FORR(i,a,b) for(int i=(int)(b)-1;i>=(int)(a);i--)
#define CHMIN(a,b) (a) = min((a),(b))
#define CHMAX(a,b) (a) = max((a),(b))

int main()
{
    int change[33][33]={};
    int n,c,xpo,ypo,zpo;
    int one[85000]={};
    int two[85000]={};
    int zer[85000]={};
    long int po1=0,po2=0,po0=0;
    long int po11,po22,po00;
    int inc;
    long long int min=2500000000;
    long long int sum=0;
    scanf("%d %d\n",&n,&c);
    REP(ypo,c)
    {
        REP(xpo,c)
        {
            scanf("%d ",&change[ypo][xpo]);
        }
        scanf("\n");
    }
    REP(ypo,n)
    {
        REP(xpo,n)
        {
            scanf("%d ",&inc);
            if((xpo+ypo+2)%3==0)
            {
                zer[po0]=inc-1;
                po0++;
            }
            else if((xpo+ypo+2)%3==1)
            {
                one[po1]=inc-1;
                po1++;
            }
            else if((xpo+ypo+2)%3==2)
            {
                two[po2]=inc-1;
                po2++;
            }
        }
        scanf("\n");
    }
    po00=po0;
    po11=po1;
    po22=po2;
    REP(xpo,c)
    {
        REP(ypo,c)
        {
            REP(zpo,c)
            {
                sum=0;
                if(xpo!=ypo && ypo!=zpo && zpo!=xpo)
                {
                    REP(po0,po00)
                    {
                        sum+=change[zer[po0]][xpo];
                    }
                    REP(po1,po11)
                    {
                        sum+=change[one[po1]][ypo];
                    }
                    REP(po2,po22)
                    {
                        sum+=change[two[po2]][zpo];
                    }
                    if(min>sum)min=sum;
                    //printf("(%d,%d,%d)%ld",xpo,ypo,zpo,sum);
                }
            }
        }
    }
    printf("%lld\n",min);
    return 0;
}

