#define CMAX 30
using namespace std;


int cost[CMAX][CMAX];
int initial[CMAX][CMAX];
vector<vector<int> > allCon;
vector<vector<int> > allPer;


// n!
void foreach_permutation(int n)
{
    vector<int> indexes(n, 0);
    for (int i = 0; i < n; i++) indexes[i] = i;
    do {
        allPer.push_back(indexes);
    } while (std::next_permutation(indexes.begin(), indexes.end()));
}

void recursive_comb(vector<int> &indexes, int s, int rest)
{
    if(rest == 0){
        allCon.push_back(indexes);
    }else{
        if(s < 0){
            return;
        }
        recursive_comb(indexes, s - 1, rest);
        indexes[rest - 1] = s;
        recursive_comb(indexes, s - 1, rest - 1);
    }
}

//nCk
void foreach_comb(int n, int k){
    vector<int> indexes(k, 0);
    recursive_comb(indexes, n-1, k);
}

int main(void)
{
    vector<vector<int> >  gp(3, vector<int>(30, 0));
    int n,c;
    cin >>n >>c;
    for(int i = 0; i < c; i++){
        for(int j = 0; j < c; j++){
            cin >>cost[i][j];
        }
    }
    for(int i = 0; i < n; i++){
        for(int j = 0; j < n; j++){
            int tmp;
            cin >>tmp;
            int r = (i+1+j+1)%3;
            gp[r][tmp-1]++;
        }
    }

    int minCost = INT_MAX;
    foreach_comb(c, 3);
    foreach_permutation(3);

    for(int i = 0; i < allCon.size(); i++){
        for(int j = 0; j < allPer.size(); j++){
            int currentCost = 0;
            for(int k = 0; k < allPer[j].size(); k++){
                int afterColor = allCon[i][allPer[j][k]];
                for(int m = 0; m < gp[k].size(); m++){
                    currentCost += cost[m][afterColor] * gp[k][m];
                }
            }
            minCost = min(minCost, currentCost);
        }
    }

    printf("%d\n", minCost);

    return 0;
}

