int main () {
  int N, C;
  std::cin >> N >> C;

  // Dとcの設定
  int ** D = new int * [C];
  int ** c = new int * [N];
  for (int i = 0; i < C; i++ ) {
    D[i] = new int[C];  
  }
  for (int i = 0; i < N; i++ ) {
    c[i] = new int[N];  
  }
  for (int i = 0; i < C; i++ ) {
    for (int j = 0; j < C; j++ ) {
      std::cin >> D[i][j];  
    }  
  }
  for (int i = 0; i < N; i++ ) {
    for (int j = 0; j < N; j++ ) {
      std::cin >> c[i][j];  
    }  
  }

  // Cの色から3色選び, それについて直した時の違和感の合計を調べて行く. 
  // 計算量ワンチャンヤバい気がする.
  int answer = -1;
  int sub_answer = 0;
  bool forBool = false;
  for (int i = 0; i < C; i++ ) {
    for (int j = 0; j < C; j++ ) {
      for (int k = 0; k < C; k++ ) {
        sub_answer = 0;
        forBool = false;
        if (i != j && j != k && k != i ) {

          // (x+y)%3 == 0にはiの色を振る.
          // (x+y)%3 == 1にはjの色を振る.
          // (x+y)%3 == 2にはkの色を振る.
          for (int l = 0; l < N; l++ ) {
            for (int m = 0; m < N; m++ ) {
              if ( sub_answer >= answer && answer > 0 ) {
                forBool = true;
                break;  
              }
              if ((l + m + 2)% 3  == 0) {
                sub_answer = sub_answer + D[c[l][m]-1][i];
              }
              if ((l + m + 2) % 3  == 1) {
                sub_answer = sub_answer + D[c[l][m]-1][j];  
              }
              if ((l + m + 2) % 3  == 2) {
                sub_answer = sub_answer + D[c[l][m]-1][k];  
              } 
            }  
            if (forBool == true ) {
              break;  
            } 
          }
          if (answer < 0 || sub_answer <= answer ) {
            answer = sub_answer;  
          } 
        } 
      }  
    }  
  }

  std::cout << answer << std::endl;

  // deleteすることを忘れずに
  for (int i = 0; i < C; i++ ) {
    delete[] D[i];
    D[i] = 0;  
  }
  for (int i = 0; i < N; i++ ) {
    delete[] c[i];
    c[i] = 0;  
  }
  delete[] D;
  D = 0;
  delete[] c;
  c = 0;
  return 0;
}

