        }
      }
      cost[i][dstColor] = totalCost;
    }
  }

  int result = 1e9;
  for (int c0 = 0; c0 < NC; c0++) {
    for (int c1 = 0; c1 < NC; c1++) {
      if (c1 == c0) continue;
      for (int c2 = 0; c2 < NC; c2++) {
        if (c2 == c0 or c2 == c1) continue;
        int totalCost = cost[0][c0] + cost[1][c1] + cost[2][c2];
        result = min(result, totalCost);
      }
    }
  }
  cout << result << endl;

  return 0;
}

