	vector<int> c3(N*N);

	for(int i=0;i<C;i++){
		vector<int> v(C);
		for(int j=0;j<C;j++)
			cin >> v.at(j);
		D.at(i)=v;
	}
	//cout << "ok" << endl;
	int size1=0,size2=0,size3=0;
	for(int i=0;i<N;i++){
		for(int j=0;j<N;j++){
			switch((i+j)%3){
				case 0:
				cin >> c1.at(size1);
				size1++;
				break;
				case 1:
				cin >> c2.at(size2);
				size2++;
				break;
				case 2:
				cin >> c3.at(size3);
				size3++;
				break;
			}
		}
	}
	//cout << size1 <<","<<size2<<","<<size3<< endl;


	int min = INT_MAX;	

	for(int i=0;i<C;i++){
		int sum1=0;
		for(auto it = 0;it < size1;++it){
			sum1+=D.at(c1.at(it)-1).at(i);
			if(sum1>min) break;
		}
		if(sum1>min)
			continue;
		for(int j=0;j<C;j++){
			if(i==j)
				continue;
			int sum2=0;
			for(auto it = 0;it < size2;++it){
				sum2+=D.at(c2.at(it)-1).at(j);
				if(sum1+sum2>min) break;
			}
			if(sum1+sum2>min)
				continue;

			for(int k=0;k<C;k++){
				if(i==k||j==k)
					continue;
				int sum3=0;
				for(auto it = 0;it < size3;++it){
					sum3+=D.at(c3.at(it)-1).at(k);
					if(sum1+sum2+sum3>min) break;
				}
				if(sum1+sum2+sum3<min)
					min=sum1+sum2+sum3;
			}
		}
	}
