int d[35][35]={0};
int c[510][510]={0};
int group[3][35]={0};

int dfs(int m, int color[],int sum=0, int answer=100000000, int depth=0) {
    if (depth == 3) {
        return min(sum,answer);
    }
    for (int k=0;k<m;k++) {
        bool next = false;
        for (int i=0;i<depth;i++) {
            if (k==color[i])
                next = true;
        }
        if (next) continue;

        color[depth] = k;

        if (sum+group[depth][k] < answer)
        answer = dfs(m,color,sum+group[depth][k],answer,depth+1);

    }
    return answer;
}

int main() {
    int n, m;
    cin >> n >> m ;
    for (int i=0;i<m;i++)
        for (int j=0;j<m;j++)
            cin >> d[i][j];
    for (int i=0;i<n;i++)
        for (int j=0;j<n;j++) {
            cin >> c[i][j];
            c[i][j] --;
        }

    for (int i=0;i<n;i++)
        for (int j=0;j<n;j++) {
            int g = ((i+1)+(j+1)) % 3;

            for (int k=0;k<m;k++)
                group[g][k] += d[c[i][j]][k];
        }

    int color[3];
    cout << dfs(m,color) << endl;
}

