int calc(vector<vector<int>> &m, vector<int> col, vector<vector<int>> &d, vector<vector<int>> &changecost) {
    int cost = 0;
    for (int i = 0; i < 3; i++) {
        cost += changecost[i][col[i]-1];
    }
    return cost;
}

int recur(vector < vector<int>> &m, vector<vector<int>> &d, int c) {
    vector<vector<int>> changecost(3, vector<int>(c, 0));
    for (int i = 0; i < 3; i++) {
        for (int j = 1; j <= c; j++) {
            for (auto t : m[i]) {
                changecost[i][j - 1] += d[t - 1][j - 1];
            }
        }
    }
    int minx = 2000000000;
    for (int i = 1; i <= c; i++) {
        for (int j = 1; j <= c; j++) {
            for (int k = 1; k <= c; k++) {
                if (i == j || j == k || k == i)
                    continue;
                vector<int> col = { i, j, k };
                minx = min(minx, calc(m, col, d, changecost));
            }
        }
    }
    return minx;

}


