using ll = long long;
using vll = vector<ll>;
using vvll = vector<vector<ll>>;
using P = pair<ll, ll>;

int main(){
	cin.tie(0);
    ios::sync_with_stdio(false);

	ll n, c;
	cin >> n >> c;
	vvll d(c, vll(c)), a(n, vll(n));
	REP(i, c){
		REP(j, c) cin >> d[i][j];
	}

	// cnt : (i + j) % 3 = 0, 1, 2 に対しどの色でいくつ塗られているか.
	vvll cnt(c, vll(3));
	REP(i, n){
		REP(j, n){
			cin >> a[i][j];
			a[i][j]--;
			cnt[a[i][j]][(i + j) % 3]++;
		}
	}
	ll res = 1e18;
	// l : (i + j) % 3 = 0, 1, 2 に対しどの色に塗り替えるか.
	REP(l0, c){
		REP(l1, c){
			REP(l2, c){
				if(l0 == l1 || l1 == l2 || l2 == l0) continue;
				vll l = {l0, l1, l2};
				// tmp : 配色 l に対する目的関数値
				ll tmp = 0;
				// 全色に対し color -> l[mod] による色の変更コストを足す
				// mod に対応する座標の元の色が color でなければ cnt == 0 なのでコストは発生しない
				REP(color, c){
					REP(mod, 3){
						tmp += cnt[color][mod] * d[color][l[mod]];
					}
				}
				res = min(res, tmp);
			}
		}
	}
	cout << res << endl;
    return 0;
}

