    std::vector<Dists> dists { Dists(), Dists(), Dists() }; // mod 3 = 0, 1, 2
    for (int i = 0; i < 3; ++i) {
        const Cells& colorMap = colors[i];
        Dists& distVec = dists[i];
        for (int c = 1; c <= C; ++c) {
            int dist = 0;
            for (auto p : colorMap) {
                dist += getD(p.first, c) * p.second;
            }
            distVec.emplace_back(std::make_pair(c, dist));
        }
        std::partial_sort(distVec.begin(), distVec.begin() + 3, distVec.end(),
                          [](const Dist& lhs, const Dist& rhs){ return lhs.second < rhs.second; });
        distVec.resize(3);
    }
    int minDist = -1;
    for (const Dist& p0 : dists[0]) {
        for (const Dist& p1 : dists[1]) {
            if (p1.first == p0.first) continue;
            for (const Dist& p2 : dists[2]) {
                if (p2.first == p0.first || p2.first == p1.first) continue;
                int total = p0.second + p1.second + p2.second;
                if (minDist == -1 || total < minDist)
                    minDist = total;
            }
        }
    }
    std::cout << minDist << std::endl;
    return 0;
}

