int busquedad(int h){
    if(h==3){
        return 0;
    }
    int resp=INT_MAX;
    for(int i=0;i<y;i++){
        if(visit[i]==true) continue;
        int cont=0;
        if(dp[h][i]!=-1){
            visit[i]=true;
            resp=min(resp,dp[h][i]+busquedad(h+1));
            visit[i]=false;
            continue;
        }
        for(int d=0;d<colors[h].size();d++){
            cont+=graph[colors[h][d]][i];
        }
        visit[i]=true;
        dp[h][i]=cont;
        resp=min(resp,cont+busquedad(h+1));
        visit[i]=false;
    }
    return resp;

}
