void all_perm(int *elem, int n, function<void(int *)> f)
{
    do{
        f(elem);
    } while(next_permutation(elem, elem + n));
}

void comb(int *elem, int n, int k, function<void(int *)> f)
{
    if(k == 0) f(elem);
    else if(n < 0) return;
    else
    {
        comb(elem, n - 1, k, f);
        elem[k - 1] = n;
        comb(elem, n - 1, k - 1, f);
    }

}

void perm(int *elem, int n, int k, function<void(int *)> f)
{
    int t_comb[k];
    comb(t_comb, n - 1, k, [&](int *t_elem) {
        all_perm(elem, n, [&](int *p_elem) {
            int elems[k];
            for(int i = 0; i < k; i++) elems[i] = t_elem[p_elem[i]];
            f(elems);
        });
    });
}

