int calc( int u , int v , int w ){
	int rt = 0 ;
	for( int i = 1 ; i <= C ; i ++ )
		rt += cnt[0][i] * tr[i][u] + cnt[1][i] * tr[i][v] + cnt[2][i] * tr[i][w] ;
	return rt ;
}

