        for(int j = 0; j < n; j++){
            cin >> x;
            M[i][j] = x;
        }
    }

    int count[3][c];
    for(int i = 0; i < 3; i++){
        for(int j = 0; j < c; j++){
            count[i][j] = 0;
        }
    }

    int now;
    for(int i = 0; i < n; i++){
        for(int j = 0; j < n; j++){
            now = (i+1+j+1)%3;
