                    for(int x = 0; x < 3; x++){
                        for(int y = 0; y < c; y++){
                            can += (ll)D[y][colors[x]] * (ll)count[x][y];
                        }
                    }
                    ans = min(can, ans);
                }while(next_permutation(colors, colors+3));
            }
        }
