int num[4][40];
int disc[4][40];
void count(){
  fill(num,0);
  rep(i,N){
    rep(j,N){
      if((i+j)%3==0) num[0][c[i][j]]++;
      else if((i+j)%3==1) num[1][c[i][j]]++;
      else num[2][c[i][j]]++;
    }
  }
}
void makedis(){
  rep(i,3){
    rep(j,C){
      disc[i][j]=0;
      rep(k,C){
	disc[i][j]+=num[i][k]*D[k][j];
      }
    }
  }
}

int solve(){
  count();
  makedis();
  int res=INF;
  int comb=(1<<3)-1;
  while(comb<(1<<C)){
    int z[3],k=0;
    rep(i,C){
      if(comb>>i&1){
	z[k]=i;
	k++;
      }
    }
    rep(i,6){
      int temp=0;
      rep(j,3){
	temp+=disc[j][z[j]];
      }
      res=std::min(res,temp);
      std::next_permutation(z,z+3);
    }
    int x=comb&-comb;
    int y=comb+x;
    comb=((comb&~y)/x>>1)|y;
  }
  return res;
}


