void solve(long long N, long long C, std::vector<std::vector<long long>> D, std::vector<std::vector<long long>> c)
{
    ll ans = INF;

    for (int i = 0; i < N; i++)
    {
        for (int j = 0; j < N; j++)
        {
            t[(i + 1 + j + 1) % 3][c[i][j]-1]++;
        }
    }

    for (int a = 0; a < C; a++)
    {
        for (int b = 0; b < C; b++)
        {
            for (int c = 0; c < C; c++)
            {
                if (a != b && b != c && c != a)
                {
                    ll tmp = 0;

                    for (int i = 0; i < C; i++)
                    {
                        tmp += D[i][a] * t[0][i];
                    }
                    for (int i = 0; i < C; i++)
                    {
                        tmp += D[i][b] * t[1][i];
                    }
                    for (int i = 0; i < C; i++)
                    {
                        tmp += D[i][c] * t[2][i];
                    }
                    ans = min(ans,tmp);
                }
            }
        }
    }
    cout << ans << endl;
}

