const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n, c;
ll d[34][34];
ll colors[505][505];
ll g[3][34];

void div_group(ll c, ll n){
    rep(cd, c){
        rep(j, 3) g[j][cd] = 0; 
        rep(x, n) rep(y, n){
            ll num = (x + y + 2) % 3; ll co = colors[x][y];
            if (co != cd) g[num][cd] += d[co][cd];
        }
    }
}

void solve(ll n, ll c){
    rep(c1, c) rep(c2, c) in1(d[c1][c2]);
    rep(x, n) rep(y, n) {in1(colors[x][y]); colors[x][y]--;}
    div_group(c, n);
    answer = INF;

    rep(c1, c)rep(c2, c)rep(c3, c){
        if (c1 == c2 || c2 == c3 || c3 == c1) continue;
        answer = min(g[0][c1] + g[1][c2] + g[2][c3], answer);
    }

    prl(answer);    
}

int main(void){
    in2(n, c);
    solve(n, c);

    return 0;
}

