						chmin( result, total );
					}
				}
			}
		}
	}

	cout << result << endl;

	return ( 0 );
}

#include <bits/stdc++.h>
using namespace std;

int main() {
  int N, C; cin >> N >> C;
  vector<vector<int>> D(C, vector<int>(C));
  for (int i = 0; i < C; i++) {
    for (int j = 0; j < C; j++) cin >> D.at(i).at(j);
  }
  vector<vector<int>> c(N, vector<int>(N));
  for (int i = 0; i < N; i++) {
    for (int j = 0; j < N; j++) {
      int color;
      cin >> color;
      c.at(i).at(j) = color - 1;
    }
  }
  vector<vector<int>> cnt(3, vector<int>(C));
  for (int i = 0; i < N; i++) {
    for (int j = 0; j < N; j++) {
      cnt.at((i + j) % 3).at(c.at(i).at(j))++;
    }
  }
  long long ans = 1LL << 50;
  for (int x = 0; x < C; x++) {
    for (int y = 0; y < C; y++) {
      for (int z = 0; z < C; z++) {
        if (x == y || y == z || z == x) continue;
        long long tmp = 0;
        for (int i = 0; i < C; i++) {
          tmp += D.at(i).at(x) * cnt.at(0).at(i);
        }
        for (int i = 0; i < C; i++) {
          tmp += D.at(i).at(y) * cnt.at(1).at(i);
        }
        for (int i = 0; i < C; i++) {
          tmp += D.at(i).at(z) * cnt.at(2).at(i);
        }
        ans = min(ans, tmp);
      }
    }
  }
  cout << ans << endl;
}

