int main() {
	int n, C, d[30][30], c;
	int t[3][30];
	int ans = 30 * 30 * 1000 + 1;
	for (int i = 0; i < 3; i++) {
		for (int j = 0; j < 30; j++) {
			t[i][j] = 0;
		}
	}
	cin >> n >> C;
	for (int i = 0; i < C; i++) {
		for (int j = 0; j < C; j++) {
			cin >> d[i][j];
		}
	}
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < n; j++) {
			cin >> c;
			t[(i + j) % 3][c - 1]++;
		}
	}
	for (int i = 0; i < C; i++) {
		for (int j = 0; j < C; j++) {
			for (int k = 0; k < C; k++) {
				if ((i != j && j != k) && k != i) {
					int res = 0;
					for (int m = 0; m < C; m++) {
						res += t[0][m] * d[m][i] + t[1][m] * d[m][j] + t[2][m] * d[m][k];
					}
					ans = min(ans, res);
				}
			}
		}
	}
	cout << ans << endl;
	return 0;
}

