#define MAX_C 40
#define MAX_N 510

ll N, C;
ll D[MAX_C][MAX_C] = {};
ll Cm[MAX_N][MAX_N] = {};

signed main()
{
    cin >> N >> C;
    REP(i, C) {
        REP(j, C) {
            cin >> D[i][j];
        }
    }
    REP(i, N) {
        REP(j, N) {
            cin >> Cm[i][j];
        }
    }

    // 全パターン試す
    ll ans = LLINF;
    for(ll zero = 1; zero <= C; ++zero) {
        for(ll one = 1; one <= C; ++one) {
            if(zero == one) { continue; }
            for(ll two = 1; two <= C; ++two) {
                if(two == zero || two == one) { continue; }
                ll cand = 0;
                auto Check = [&](ll from, ll to) {
                    if(from != to) { cand += D[from-1][to-1]; }
                };
                REP(i, N) {
                    REP(j, N) {
                        if( (i+j+2) % 3 == 0) { Check(Cm[i][j], zero); }
                        if( (i+j+2) % 3 == 1) { Check(Cm[i][j], one); }
                        if( (i+j+2) % 3 == 2) { Check(Cm[i][j], two); }
                    }
                }
                ans = min(ans, cand);
            }
        }
    }

    printf("%lld\n", ans);
    return 0;
}

