ll solve(){
    ll res = LINF;
    ll N,C; cin >> N >> C;
    vector<vector<ll>> D(C+1,vector<ll>(C+1));
    vector<vector<ll>> c(N+1,vector<ll>(N+1));
    for(int i = 1; i <= C;i++)for(int j = 1; j <= C;j++) cin >> D[i][j];
    for(int i = 1; i <= N;i++)for(int j = 1; j <= N;j++) cin >> c[i][j];
    for(int i = 1; i <= C; i++){
        for(int j = 1; j <= C;j++){
            for(int k = 1; k <= C;k++){
      //          D[j][k] = min(D[j][k],D[j][i]+D[i][k]);
            }
        }
    }
    vector<vector<ll>> cnt(3,vector<ll>(C+1));
    for(int i = 1; i<=N;i++){
        for(int j = 1;j<=N;j++){
            cnt[(i+j)%3][c[i][j]]++;
        }
    }
//    cout << cnt << endl;
    for(int c1 = 1; c1 <= C; c1++){
        for(int c2 = 1; c2 <=C; c2++){
            if(c1 == c2) continue;
            for(int c3 = 1; c3 <= C;c3++){
                if(c1 == c3) continue;
                if(c2 == c3) continue;
                ll T = 0;
                for(int j = 1; j <= C;j++){
                    T += cnt[0][j]*D[j][c1];
                }
                for(int j = 1; j <= C;j++){
                    T += cnt[1][j]*D[j][c2];
                }
                for(int j = 1; j <= C;j++){
                    T += cnt[2][j]*D[j][c3];
                }
               // cout << c1 << " " << c2 << " " << c3 << endl;
               // cout << T << endl;
                res = min(res,T);
            }
        }
    }

    return res;
}
