            int index = (i + j) % 3;
            costs[index][c[i][j]]++;
        }
    }

    VVI counts(3, VI(C, 0));
    REP(i, 3) {
        REP(j, C) {
            int cost = 0;
            REP(k, C) {
                cost += D[k][j] * costs[i][k];
            }
            counts[i][j] = cost;
        }
    }

    LL minCost = LONG_LONG_MAX;
    do {

        VI seleCol(3);
        REP(i, 3) {
            seleCol[i] = i;
        }

        do {

            LL cost = 0;
            for(int i=0;i<3;i++){
                cost += counts[i][colors[i]];
            }

            minCost = C_MIN(cost, minCost);


        } while (next_permutation(seleCol.begin(), seleCol.end()));

    } while (next_combination(colors.begin(), colors.begin() + 3, colors.begin() + 3, colors.end()));

    OUT_L(minCost);

    return 0;
}

