inline int dfs(int l,int r)
{
	if(l>r)
		return 0;
    int ans=0,ml=l,mn=0x3f3f3;
    for(int i=l;i<=r;i++)
		mn=min(mn,h[i]);
    for(int i=l;i<=r;i++)
		h[i]-=mn;
    ans+=mn;
    for(int i=l;i<=r;i++)
    {
        if(h[i]==0)
        {
            ans+=dfs(ml,i-1);
            ml=i+1;
        }
        if(i==r)
        {
            if(h[i]>0)
				ans+=dfs(ml,r);
            else
				ans+=dfs(ml,r-1);
        }
    }
    return min(ans,r-l+1);
}
