void solve() {
  VV<int> X(3);
  REP(i,N)REP(j,N) {
    X[(i+j)%3].push_back(--A[i][j]);
  }
  VV<int> cost(3,VI(C));
  REP(c,C)REP(i,3) {
    int sum=0;
    FORR(x,X[i]) sum+=D[x][c];
    cost[i][c]=sum;
  }

  int res=1e9;
  REP(c1,C)REP(c2,C)if(c1!=c2)REP(c3,C)if(c2!=c3&&c3!=c1) {
    int sum=cost[0][c1]+cost[1][c2]+cost[2][c3];
    SMIN(res,sum);
  }
  cout<<res<<endl;
}

