// n!
void foreach_permutation(int n)
{
    vector<int> indexes(n, 0);
    for (int i = 0; i < n; i++) indexes[i] = i;
    do {
        allPer.push_back(indexes);
    } while (std::next_permutation(indexes.begin(), indexes.end()));
}

void recursive_comb(vector<int> &indexes, int s, int rest)
{
    if(rest == 0){
        allCon.push_back(indexes);
    }else{
        if(s < 0){
            return;
        }
        recursive_comb(indexes, s - 1, rest);
        indexes[rest - 1] = s;
        recursive_comb(indexes, s - 1, rest - 1);
    }
}

//nCk
void foreach_comb(int n, int k){
    vector<int> indexes(k, 0);
    recursive_comb(indexes, n-1, k);
}

