    vector<vector<int>> list(3, vector<int>(c, 1e9));
    rep(i, 3){
        rep(to, c){
            int sum = 0;
            rep(from, c){
                sum += v[i][from] * d[from][to];
            }
            list[i][to] = sum;
        }
    }

    priority_queue<Node> que;
    que.push({0, vector<bool>(c, false), 0});

    while(!que.empty()){
        Node node = que.top(); que.pop();

        if(node.pos == 3){
            cout << node.cost << endl;
            break;
        }
        rep(i, c){
            if(node.used[i]) continue;
            vector<bool> v = node.used;
            v[i] = true;
            que.push({node.pos+1, v, node.cost+list[node.pos][i]});
        }
    }

    return 0;
}

