void dfs(vvl change, ll depth, ll tot, vl &used, ll &ans){
  if(depth == 3){
    ans = min(ans, tot);
    return;
  }

  rep(i, change[depth].size()){
    if(used[i] == 1) continue;

    used[i] = 1;
    dfs(change, depth + 1, tot + change[depth][i], used, ans);
    used[i] = 0;
  }
}

