int D[35][35];
int G1[35], G2[35], G3[35];

int main() {
    int N, C, c;
    scanf("%d %d", &N, &C);
    for (int i = 1; i <= C; i++) {
        for (int j = 1; j <= C; j++) scanf("%d", &D[i][j]);
    }
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            scanf("%d", &c);
            if ((i + j) % 3 == 0) G1[c]++;
            else if ((i + j) % 3 == 1) G2[c]++;
            else if ((i + j) % 3 == 2) G3[c]++;
        }
    }
    int ans = 100000000;
    for (int i = 1; i <= C; i++) {
        for (int j = 1; j <= C; j++) {
            if (j == i) continue;
            for (int k = 1; k <= C; k++) {
                if (k == i || k == j) continue;
                int sum = 0;
                for (int l = 1; l <= C; l++) {
                    sum += G1[l] * D[l][i] + G2[l] * D[l][j] + G3[l] * D[l][k];
                }
                ans = min(ans, sum);
            }
        }
    }
    printf("%d\n", ans);
    return 0;
}

