void solve(long long N, long long C, std::vector<std::vector<long long>> D, std::vector<std::vector<long long>> tab){
    vector<map<LL, LL>> cnts(3);
    for(int i=0; i<N; i++){
        for(int j=0; j<N; j++){
            cnts[(i+1+j+1)%3][tab[i][j]]++;
        }
    }

    vector<vector<pair<LL, LL>>> costs(3);
    for(int m=0; m<3; m++){
        for(int c=1; c<=C; c++){
            auto cost = 0ll;
            for(auto kv: cnts[m]){
                cost += kv.second*D[kv.first-1][c-1];
            }
            costs[m].emplace_back(make_pair(cost, c));
        }
        sort(costs[m].begin(), costs[m].end());
    }

    auto ans=LONG_LONG_MAX;

    for(int a=0; a<3; a++){
        for(int b=0; b<3; b++){
            for(int c=0; c<3; c++){
                auto m0 = costs[0][a];
                auto m1 = costs[1][b];
                auto m2 = costs[2][c];
                if(m0.second==m1.second || m1.second==m2.second || m2.second==m0.second)continue;
                ans=min(ans, m0.first+m1.first+m2.first);
            }
        }
    }

    cout << ans << endl;

}

