int main() {
    int N,C;
    cin >> N >> C;
    vector<vector<int>> D(C, vector<int>(C, 0));
    for(int i = 0; i < C; i++)
    {
        for(int j = 0; j < C; j++)
        {
            cin >> D.at(i).at(j);
        }

    }
    vector<vector<int>> coler(N, vector<int>(N, 0));
    vector<vector<int>> cnt(3, vector<int>(C + 1, 0));
    for(int i = 0; i < N; i++)
    {
        for(int j = 0; j < N; j++)
        {
            cin >> coler.at(i).at(j);
            cnt.at(((i + 1) + (j + 1)) % 3).at(coler.at(i).at(j))++;
        }

    }

    int ans = INT_MAX;
    int sum = 0;
    for(int i = 1; i <= C; i++)
    {
        for(int j = 1; j <= C; j++)
        {
            if (i == j) continue;
            for(int k = 1; k <= C; k++)
            {
                if (i == k || j == k) continue;

                sum = 0;

                for(int p = 1; p <= C; p++)
                {
                    if (i == p) continue;

                    sum += cnt.at(0).at(p) * D.at(p - 1).at(i - 1);
                }

                for(int p = 1; p <= C; p++)
                {
                    if (j == p) continue;

                    sum += cnt.at(1).at(p) * D.at(p - 1).at(j - 1);
                }

                for(int p = 1; p <= C; p++)
                {
                    if (k == p) continue;

                    sum += cnt.at(2).at(p) * D.at(p - 1).at(k - 1);
                }

                ans = min(ans, sum);
            }

        }

    }

    cout << ans << endl;
}

