int main() {
	int N, C, D[MAX][MAX], c[MAX2][MAX2];
	cin >> N >> C;
	for (int i = 0;i < C;i ++) for (int j = 0;j < C;j ++) cin >> D[i][j];
	for (int i = 0;i < N;i ++) for (int j = 0;j < N;j ++) cin >> c[i][j];

	if (N == 1) { // 例外条件
		cout << 0;
		return 0;
	}

	int color[3][MAX]; // 色の個数
	for (int i = 0;i < 3;i ++) for (int j = 0;j < C;j ++) color[i][j] = 0;
	for (int i = 0;i < N;i ++) {
		for (int j = 0;j < N;j ++) {
			color[(i + j) % 3][c[i][j] - 1] ++;
		}
	}

	pair<int, int> change[3][MAX]; // 色を決め打った時のコスト
	for (int i = 0;i < 3;i ++) for (int j = 0;j < C;j ++) change[i][j] = make_pair(0, j);
	for (int i = 0;i < 3;i ++) {
		for (int j = 0;j < C;j ++) { // 決め打つ色
			for (int k = 0;k < C;k ++) {
				change[i][j].first += D[k][j] * color[i][k];
			}
		}
		sort(change[i], change[i] + C);
	}

	int ans = INF;
	for (int i = 0;i < 3;i ++) {
		for (int j = 0, k;j < 3;j ++) {
			if (change[0][i].second == change[1][j].second) continue;
			for (k = 0;change[2][k].second == change[0][i].second || change[2][k].second == change[1][j].second;k ++);
			ans = min(ans, change[0][i].first + change[1][j].first + change[2][k].first);
		}
	}
	cout << ans;
	return 0;
}
