                GoodGrid.at(i).at(j) = (GoodGrid.at(i-1).at(j)+1)%3;
            }
            else{
                GoodGrid.at(i).at(j) = (GoodGrid.at(i).at(j-1)+1)%3;
            }
        }
    }

    //余りが0,1,2のそれぞれでどの色に合わせたかによる違和感の総和を求める
    for(int remain = 0;remain<3;remain++){
        for(int c = 0;c<C;c++){
            int wrongnessSum = 0;
            for(int i = 0;i<N;i++){
                for(int j = 0;j<N;j++){
                    if(GoodGrid.at(i).at(j) != remain) continue;
                    wrongnessSum += wrongness.at(ban.at(i).at(j)).at(c);
                }
            }
            if(remain == 0){
                wrongnessSum_0.at(c) = wrongnessSum;
            }
            if(remain == 1){
                wrongnessSum_1.at(c) = wrongnessSum;
            }
            if(remain == 2){
                wrongnessSum_2.at(c) = wrongnessSum;
            }
        }
    }

    //違う色を選んで違和感の最小値を求める
    int ans = inf;
    for(int i = 0;i<C;i++){
        for(int j = 0;j<C;j++){
            for(int k = 0;k<C;k++){
                if(i == j || j == k || k == i) continue;
                ans = min(ans,wrongnessSum_0.at(i)+wrongnessSum_1.at(j)+wrongnessSum_2.at(k));
            }
        }
    }
    cout << ans << endl;
}

