void solve(ostringstream& aout, long long N, long long C, std::vector<std::vector<long long>> D, std::vector<std::vector<long long>> c){

	int ans = LL_HALFMAX;
	map<int, int> zeroc, onec, twoc;


	rep(y, N) {
		rep(x, N) {
			switch ((y + x) % 3)
			{
			case 0:
				zeroc[c[y][x]]++;
				break;
			case 1:
				onec[c[y][x]]++;

				break;
			case 2:
				twoc[c[y][x]]++;
				break;

			default:
				break;
			}
		}
	}

	rep(one, C) {
		rep(two, C) {
			rep(zero, C) {
				int cand = 0;
				if (one == two || two == zero || one == zero) {
					continue;
				}
				for (auto p : zeroc) {
					cand += D[p.first-1][zero] * p.second;
				}
				for (auto p : onec) {
					cand += D[p.first-1][one] * p.second;
				}
				for (auto p : twoc) {
					cand += D[p.first-1][two] * p.second;
				}

				chmin(ans, cand);
			}
		}
	}
	aout << ans << "\n";
}

void solve_TLE(ostringstream& aout, long long N, long long C, std::vector<std::vector<long long>> D, std::vector<std::vector<long long>> c) {
	int ans = LL_HALFMAX;

	rep(one, C) {
		rep(two, C) {
			rep(zero, C) {
				int cand = 0;
				if (one == two || two == zero || one == zero) {
					continue;
				}
				rep(y, N) {
					rep(x, N) {
						switch ((y + x) % 3)
						{
						case 0:
							cand += D[c[y][x] - 1][zero];
							break;
						case 1:
							cand += D[c[y][x] - 1][one];
							break;
						case 2:
							cand += D[c[y][x] - 1][two];
							break;

						default:
							break;
						}
					}
				}
				chmin(ans, cand);
			}
		}
	}
	aout << ans << "\n";
}

