vector<vector<int> > d;
vector<int> g0(31,0),g1(31,0),g2(31,0);

int solver(int a,int b,int c,int C){
    int tmp=0;
    for(int i=1;i<C+1;i++) tmp+=d[i-1][a-1]*g0[i];
    for(int i=1;i<C+1;i++) tmp+=d[i-1][b-1]*g1[i];
    for(int i=1;i<C+1;i++) tmp+=d[i-1][c-1]*g2[i];
    return tmp;
}

int main(){
    int N,C,in,ans;
    cin >> N >> C;
    for(int i=0;i<C;i++){
        vector<int> tmp;
        for(int j=0;j<C;j++) cin >> in,tmp.push_back(in);
        d.push_back(tmp);
    }
    for(int i=1;i<N+1;i++){
        for(int j=1;j<N+1;j++){
            cin >> in;
            if((i+j)%3==0) g0[in]++;
            if((i+j)%3==1) g1[in]++;
            if((i+j)%3==2) g2[in]++;
        }
    }
    ans=numeric_limits<int>::max();
    for(int i=1;i<C+1;i++){
        for(int j=1;j<C+1;j++){
            for(int k=1;k<C+1;k++){
                if(i!=j&&j!=k&&k!=i){
                    int tmp=solver(i,j,k,C);
                    if(ans>tmp) ans=tmp;
                }
            }
        }
    }
    cout << ans << endl;

    return 0;
}

