int main(){
	int n, c;
	cin >> n >> c;
	vector<vector<int>> d = vector<vector<int>>(c, vector<int>(c, 0));
	for (int i = 0; i < c; ++i) {
		for (int j = 0; j < c; ++j) {
			int dij;
			cin >> dij;
			d[i][j] = dij;
		}
	}
	vector<vector<int>> cmap = vector<vector<int>>(n, vector<int>(n, 0));
	for (int i = 0; i < n; ++i) {
		for (int j = 0; j < n; ++j) {
			int cij;
			cin >> cij;
			cij--;
			cmap[i][j] = cij;
		}
	}
	int best = 1000*500*500;
	for (int call = 0; call < c*c*c; call++) {
		int cs[3];
		cs[0] = call % c;
		cs[1] = (call / c) % c;
		cs[2] = (call / c / c) % c;
		if (cs[0] == cs[1] || cs[1] == cs[2] || cs[2] == cs[0]) continue;

		int cost = 0;
		for (int i = 0; i < n; ++i) {
			for (int j = 0; j < n; ++j) {
				int cc = cmap[i][j];
				int ct = cs[(i + j) % 3];
				if (cc == ct) continue;
				cost += d[cc][ct];
			}
			if (cost > best) break;
		}
		if (cost < best) best = cost;
	}
	cout << best << endl;
	return 0;
}

