void solve(long long N, long long C, vector<vector<long long>> D, vector<vector<long long>> c){
    vector< vector<long long> > l(3, vector<long long>(C, 0));
    for (int i = 0; i < C; i++) {
        for (int x = 0; x < N; x++) {
            for (int y = 0; y < N; y++) {
                l[(x+y) % 3][i] += D[c[x][y]-1][i];
            }
        }
    }
    long long ret = 10000000000000000;
    for (int i = 0; i < C; i++) {
        for (int j = 0; j < C; j++) {
            for (int k = 0; k < C; k++) {
                if (i == j || j == k || i == k) {
                    continue;
                }
                ret = min(ret, l[0][i] + l[1][j] + l[2][k]);
            }
        }
    }
    std::cout << ret << std::endl;
}

