int N, C;
int D[555][555];
int c[555][555];
map<int, int> mp0, mp1, mp2; // map<色, 個数>

// mod0の色、mod1の色、mod2の色を決め打った時の合計コスト
int solve(int zero, int one, int two) {
	int ret = 0;
	// mod0の色を変える合計コストを求める
	for (auto x : mp0) {
		int num = x.first;
		int cnt = x.second;
		ret += D[num-1][zero-1] * cnt;
	}

	// mod1の色を変える合計コストを求める
	for (auto x : mp1) {
		int num = x.first;
		int cnt = x.second;
		ret += D[num-1][one-1] * cnt;
	}

	// mod2の色を変える合計コストを求める
	for (auto x : mp2) {
		int num = x.first;
		int cnt = x.second;
		ret += D[num-1][two-1] * cnt;
	}

	return ret;
}

signed main() {
	cin >> N >> C;
	for (int i = 0; i < C; i++) {
		for (int j = 0; j < C; j++) {
			cin >> D[i][j];
		}
	}
	for (int i = 0; i < N; i++) {
		for (int j = 0; j < N; j++) {
			cin >> c[i][j];
			int I = i+1, J = j+1;
			// mod0, mod1, mod2ごとにその色が何個あるかを求める
			if ((I+J)%3 == 0) {
				mp0[c[i][j]]++;
			}
			if ((I+J)%3 == 1) {
				mp1[c[i][j]]++;
			}
			if ((I+J)%3 == 2) {
				mp2[c[i][j]]++;
			}
		}
	}

	int ans = 1e18;
	for (int c0 = 1; c0 <= C; c0++) { // mod0の色
		for (int c1 = 1; c1 <= C; c1++) { // mod1の色
			for (int c2 = 1; c2 <= C; c2++) { // mod2の色
				if (c0 == c1) continue;
				if (c0 == c2) continue;
				if (c1 == c2) continue;

				int t = solve(c0, c1, c2);
				chmin(ans, t);
			}
		}
	}

	cout << ans << endl;

	return 0;
}

