#define INF (1e+9)
#define COLOR_MAX 30
#define GROUPS 3

int calc(int group[][COLOR_MAX+1], int *cs, int ds[][COLOR_MAX+1], int colors) {
    int i, c;
    int disorder = 0;
    for(i = 0; i < GROUPS; i++) {
        for(c = 1; c <= colors; c++) {
            int before = c;
            int after = cs[i];
            disorder += ds[before][after] * group[i][c];
        }
    }
#ifdef DEBUG
    printf("%d, %d, %d -> %d\n", cs[0], cs[1], cs[2], disorder);
#endif
    return disorder;
}

int main(void) {
