    static int mat[NUM_MAX+1][NUM_MAX+1];
    int i, j;
    for(i = 1; i <= colors; i++) {
        fget_array(&ds[i][1], colors);
    }

    for(i = 1; i <= num; i++) {
        fget_array(&mat[i][1], num);
    }

    static int group[3][COLOR_MAX+1];
    for(i = 1; i <= num; i++) {
        for(j = 1; j <= num; j++) {
            int c = mat[i][j];
            group[(i+j)%3][c]++;
        }
    }

    int c0, c1, c2; // c_(mod)
    int ans = INF;
    for(c0 = 1; c0 <= colors; c0++) {
        for(c1 = 1; c1 <= colors; c1++) {
            if(c0 == c1) continue;
            for(c2 = 1; c2 <= colors; c2++) {
                if(c1 == c2) continue;
                if(c0 == c2) continue;
                int cs[3] = {c0, c1, c2};
                int res = calc(group, cs, ds, colors);
                ans = min(ans, res);
            }
        }
    }
    printf("%d\n", ans);
    return 0;
}

