static uint32_t D[30][30];
static uint32_t c[500][500];

static uint32_t calcStrangeScore(const uint32_t N, const uint32_t C, const uint32_t zero, const uint32_t one, const uint32_t two) {
	uint32_t strangeScore = 0;

	for (uint32_t row = 0; row < N; row++) {
		for (uint32_t col = 0; col < N; col++) {
			const uint32_t remainder = (row + 1 + col + 1) % 3;
			if (remainder == 0) {
				if (c[row][col] != zero) {
					strangeScore += D[c[row][col] - 1][zero - 1];
				}
			}
			else if (remainder == 1) {
				if (c[row][col] != one) {
					strangeScore += D[c[row][col] - 1][one - 1];
				}

			}
			else {
				if (c[row][col] != two) {
					strangeScore += D[c[row][col] - 1][two - 1];
				}

			}
		}
	}

	return strangeScore;
}

