		for (uint32_t dCol = 0; dCol < C - 1; dCol++) {
			scanf("%"PRIu32" ", &(D[dRow][dCol]));
		}
		scanf("%"PRIu32"\n", &(D[dRow][C - 1]));
	}

	for (uint32_t cRow = 0; cRow < N; cRow++) {
		for (uint32_t cCol = 0; cCol < N - 1; cCol++) {
			scanf("%"PRIu32" ", &(c[cRow][cCol]));
		}
		scanf(cRow == N - 1 ? "%"PRIu32 : "%"PRIu32"\n", &(c[cRow][N - 1]));
	}

	uint32_t min = UINT32_MAX;

	for (uint32_t zero = 1; zero <= C; zero++) {
		for (uint32_t one = 1; one <= C; one++) {
			if (one != zero) {
				for (uint32_t two = 1; two <= C; two++) {
					if (two != zero && two != one) {
						const uint32_t strangeScore = calcStrangeScore(N, C, zero, one, two);
