#define NUM_MAX 500
// max: 250000 * 1000
#define INF (1e+9)

int calc(int mat[][NUM_MAX+1], int *cs, int ds[][NUM_MAX+1], int size) {
    int i, j;
    int disorder = 0;
    for(i = 1; i <= size; i++) {
        for(j = 1; j <= size; j++) {
            int after = cs[(i+j)%3];
            int before = mat[i][j];
            disorder += ds[before][after];
        }
    }
#ifdef DEBUG
    printf("%d, %d, %d -> %d\n", cs[0], cs[1], cs[2], disorder);
#endif
    return disorder;
}

int main(void) {
    int num, colors;
    get_int2(&num, &colors);
    // 1-indexed
    static int ds[NUM_MAX+1][NUM_MAX+1];
    static int mat[NUM_MAX+1][NUM_MAX+1];
    int i;
    for(i = 1; i <= colors; i++) {
        fget_array(&ds[i][1], colors);
    }

    for(i = 1; i <= num; i++) {
        fget_array(&mat[i][1], num);
    }

    int c0, c1, c2; // c_(mod)
    int ans = INF;
    for(c0 = 1; c0 <= colors; c0++) {
        for(c1 = 1; c1 <= colors; c1++) {
            if(c0 == c1) continue;
            for(c2 = 1; c2 <= colors; c2++) {
                if(c1 == c2) continue;
                if(c0 == c2) continue;
                int c[3] = {c0, c1, c2};
                int res = calc(mat, c, ds, num);
                ans = min(ans, res);
            }
        }
    }
    printf("%d\n", ans);
    return 0;
}

