    val d = Array(c) { Array(c) { sc.nextInt() } }
    val col = Array(n) { Array(n) { sc.nextInt() - 1 } }
    val cost = Array(3) { Array(c) { 0L } }
    for (i in 0 until n) {
        for (j in 0 until n) {
            for (k in 0 until c) {
                cost[(i + j) % 3][k] += d[col[i][j]][k].toLong()
            }
        }
    }
    var min = Long.MAX_VALUE
    for (i in 0 until c) {
        for (j in 0 until c) {
            for (k in 0 until c) {
                if (i == j || j == k || i == k) continue
                min = minOf(min, cost[0][i] + cost[1][j] + cost[2][k])
            }
        }
    }
    println(min)
}

