// Reads multiple ints in a line, separate by a space.
// It works even if the actual number of ints is smaller than n.
// WARNING: This function does not work for -2^31.
// NOTE: This function does not handle error cases.
fun fastReadInts(n: Int): IntArray {
  val xs = IntArray(n)
  val s = readLine()!!
  var currentValue = 0
  var isNegative = false
  var currentIndex = 0
  for (c in s) {
    if (c == ' ') {
      xs[currentIndex] = currentValue * if (isNegative) -1 else 1
      currentValue = 0
      isNegative = false
      currentIndex++
    } else if (c == '-') {
      isNegative = true
    } else {
      currentValue *= 10
      currentValue += c - '0'
    }
  }
  xs[currentIndex] = currentValue * if (isNegative) -1 else 1
  return xs
}

fun main(args: Array<String>) {
  val (n, c) = fastReadInts(2)
  val dMatrix = Array(c, { fastReadInts(c) })
  val cCount = Array(3, { IntArray(c) })
  for (y in 0 until n) {
    val cs = fastReadInts(n).map { it - 1 }
    for (x in 0 until n) {
      cCount[(x + y) % 3][cs[x]]++
    }
  }
  var ans = Int.MAX_VALUE
  for (c1 in 0 until c) {
    for (c2 in 0 until c) {
      if (c2 == c1) continue
      for (c3 in 0 until c) {
        if (c3 == c1 || c3 == c2) continue
        val cost1 = cCount[0].withIndex().map { it.value * dMatrix[it.index][c1] }.sum()
        val cost2 = cCount[1].withIndex().map { it.value * dMatrix[it.index][c2] }.sum()
        val cost3 = cCount[2].withIndex().map { it.value * dMatrix[it.index][c3] }.sum()
        val cost = cost1 + cost2 + cost3
        ans = Math.min(ans, cost)
      }
    }
  }
  println(ans)
}

