            }
        }

        final int[][] modTable = new int[3][c];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                final int tmp = scanner.nextInt() - 1;
                modTable[(i + j) % 3][tmp]++;
            }
        }

        long answer = Long.MAX_VALUE;
