public void solve() {
	int num = ni();
	int c = ni();
	long d[][] = nl(c, c);
	int color[][] = ni(num, num);
	long need[][] = new long[c][3];
	fill(need, 0);
	for(int crt = 0; crt < c; crt ++) {
		for(int i = 0; i < num; i ++) {
			for(int j = 0; j < num; j ++) {
				need[crt][(i + j) % 3] += d[color[i][j] - 1][crt];
			}
		}
	}
	long ans = INF;
	for(int i = 0; i < c; i ++) {
		for(int j = 0; j < c; j ++) {
