class Main {

    static PrintWriter out;
    static InputReader sc;

    static int C;
    static int[][] cost;

    public static void main(String[] args) {
        sc = new InputReader(System.in);
        out = new PrintWriter(System.out);
        solve();
        out.flush();
    }

    static void solve() {
        int N = sc.nextInt();
        C = sc.nextInt();
        int[][] c = new int[N][N];
        int[][] D = new int[C][C];
        for (int i = 0; i < C; i++) {
            for (int j = 0; j < C; j++) {
                D[i][j] = sc.nextInt();
            }
        }
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                c[i][j] = sc.nextInt();
            }
        }
        cost = new int[3][C];
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < C; j++) {
                for (int x = 0; x < N; x++) {
                    for (int y = 0; y < N; y++) {
                        if ((x + y + 2) % 3 == i) {
                            cost[i][j] += D[c[y][x] - 1][j];
                        }
                    }
                }
            }
        }
        out.println(dfs(0, (1 << C) - 1));
    }

    static int dfs(int i, int s) {
        int min = Integer.MAX_VALUE / 3;
        if (i < 2) {
            for (int k = 0; k < C; k++) {
                if (((s >> k) & 1) == 1) {
                    min = Math.min(dfs(i + 1, s & ~(1 << k)) + cost[i][k], min);
                }
            }
        } else {
            for (int k = 0; k < C; k++) {
                if (((s >> k) & 1) == 1) {
                    min = Math.min(cost[i][k], min);
                }
            }
        }
        return min;
    }

