class Main{

    void solve(){
        int N = ni();
        int C = ni();
        int[][] d = new int[C + 1][C + 1];
        for(int i = 1; i <= C; i++){ 
            for(int j = 1; j <= C; j++){ 
                d[i][j] = ni();
            }
        }
        List<Integer> zero = new ArrayList<>();
        List<Integer> one = new ArrayList<>();
        List<Integer> two = new ArrayList<>();
        for(int i = 1; i <= N; i++){ 
            for(int j = 1; j <= N; j++){ 
                int c = ni();
                if((i + j) % 3 == 0){
                    zero.add(c);
                } else if((i + j) % 3 == 1){
                    one.add(c);
                } else if((i + j) % 3 == 2){
                    two.add(c);
                }
            }
        }

        long[][] zerolist = new long[C + 1][2];
        long[][] onelist = new long[C + 1][2];
        long[][] twolist = new long[C + 1][2];   
        zerolist[0][0] = -1;    // 番兵
        onelist[0][0] = -1;
        twolist[0][0] = -1;   
        for(int after = 1; after <= C; after++){ 
            long zerosum = 0;
            long onesum = 0;
            long twosum = 0;
            for(int before : zero){
                zerosum += d[before][after];
            }
            for(int before : one){
                onesum += d[before][after];
            }
            for(int before : two){
                twosum += d[before][after];
            }
            zerolist[after][0] = zerosum;
            zerolist[after][1] = after;
            onelist[after][0] = onesum;
            onelist[after][1] = after;
            twolist[after][0] = twosum;
            twolist[after][1] = after;
        }
        Arrays.sort(zerolist, (x, y) -> Long.compare(x[0], y[0]));
        Arrays.sort(onelist, (x, y) -> Long.compare(x[0], y[0]));
        Arrays.sort(twolist, (x, y) -> Long.compare(x[0], y[0]));

        long ans = LINF;
        for(int z = 1; z <= 3; z++){ 
            for(int o = 1; o <= 3; o++){ 
                for(int t = 1; t <= 3; t++){ 
                    if(zerolist[z][1] == onelist[o][1] || onelist[o][1] == twolist[t][1] || zerolist[z][1] == twolist[t][1]) continue;
                    long sum = zerolist[z][0] + onelist[o][0] + twolist[t][0];
                    ans = min(ans, sum);
                }
            }
        }

        out.println(ans);

        out.flush();
    } 


