				}
				for (int k = 0; k < C; ++k) {
					if (i == k || j == k) {
						continue;
					}
					int[] colPattern = new int[3];
					colPattern[0] = i;
					colPattern[1] = j;
					colPattern[2] = k;
					min = Math.min(min, calc(colPattern, counts));
				}
			}
		}
		System.out.println(min);

	}

