public class Main {

	static PrintWriter out;
	static InputReader ir;
	static boolean debug = false;

	static void solve() {
		int n = ir.nextInt();
		int c = ir.nextInt();
		int[][] d = new int[c][];
		for (int i = 0; i < c; i++)
			d[i] = ir.nextIntArray(c);
		int[][] a = new int[n][];
		for (int i = 0; i < n; i++)
			a[i] = ir.nextIntArray(n);
		for (int i = 0; i < n; i++)
			for (int j = 0; j < n; j++)
				a[i][j]--;
		int[][] ct = new int[3][c];
		for (int i = 0; i < n; i++)
			for (int j = 0; j < n; j++)
				ct[(i + j) % 3][a[i][j]]++;
		long mi = 1000000000000000L;
		for (int i = 0; i < c; i++) {
			for (int j = 0; j < c; j++) {
				if (i == j)
					continue;
				for (int k = 0; k < c; k++) {
					if (j == k || k == i)
						continue;
					long res = 0;
					for (int l = 0; l < c; l++) {
						res += ct[0][l] * d[l][i];
						res += ct[1][l] * d[l][j];
						res += ct[2][l] * d[l][k];
					}
					mi = Math.min(mi, res);
				}
			}
		}
		out.println(mi);
	}

	public static int upper_bound(long[] a, int fromIndex, int toIndex, long val) {
		if (val >= a[toIndex])
			return toIndex + 1;
		if (val < a[fromIndex])
			return fromIndex;
		int lb = fromIndex - 1, ub = toIndex;
		while (ub - lb > 1) {
			int mid = (ub - lb) / 2 + lb;
			if (a[mid] > val) {
				ub = mid;
			} else {
				lb = mid;
			}
		}
		return ub;
	}

