        for (int i = 0; i < C; i++) {
            for (int j = 0; j < C; j++) {
                D[i][j] = ni();
            }
        }
        int[][] c = new int[N][N];
        int[][] count = new int[3][C];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N ; j++) {
                int color = ni()-1;
                c[i][j] = color;
                count[(i+j)%3][color]++;
            }
        }
        long ans = Long.MAX_VALUE;
        for (int i = 0; i < C; i++) {
            for (int j = 0; j < C; j++) {
                for (int k = 0; k < C; k++) {
                    if(i==j || j==k || i==k) continue;
                    long cost = 0;
                    for (int s = 0; s < C; s++) {
                        cost += count[0][s] * D[s][i];
                        cost += count[1][s] * D[s][j];
                        cost += count[2][s] * D[s][k];
                    }
                    ans = Math.min(ans,cost);
