public class Main{
	static Scanner s=new Scanner(System.in);

	void solve(){
		int n=gInt(),color=gInt();
		long[][]cost=new long[color][color];
		int[][]a=new int[n][n];

		int[][]sum=new int[3][color];

		for(int i:rep(color))
			for(int j:rep(color))
				cost[i][j]=gInt();
		for(int i:rep(n)) {
			for(int j:rep(n)) {
				int v=gInt()-1;
				int p=(i+j)%3;
				++sum[p][v];
			}
		}

		long res=Long.MAX_VALUE;
		for(int i:rep(color))
			for(int j:rep(color))
				for(int k:rep(color))
					if(i!=j&&j!=k&&k!=i)
						res=Math.min(res,f(i,j,k,cost,sum));

		System.out.println(res);
	}
	private long f(int c1,int c2,int c3,long[][] cost,int[][] sum){
		int[]v= {c1,c2,c3};
		long r=0;
		for(int i:rep(3)) {
			r+=REP(cost.length)
					.mapToLong(j->cost[j][v[i]]*sum[i][j])
					.sum();
		}
		return r;
	}
	public static void main(String[] A){
		new Main().solve();
	}

	static int gInt(){
		return Integer.parseInt(s.next());
	}
	static long gLong(){
		return Long.parseLong(s.next());
	}
