            }
        }
        int[][] colorCnt = new int[3][C + 1]; // mod, color
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                colorCnt[(i + 1 + j + 1) % 3][c[i][j]]++;
            }
        }
        long minSum = Long.MAX_VALUE;
        for (int c0 = 1; c0 <= C; c0++) {
            for (int c1 = 1; c1 <= C; c1++) {
                for (int c2 = 1; c2 <= C; c2++) {
                    if (c0 == c1 || c0 == c2 || c1 == c2) {
                        continue;
                    }
                    long sum = 0;
                    for (int mod = 0; mod < 3; mod++) {
