    static class GoodGrid {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int n = in.nextInt();
            int c = in.nextInt();
            int[][] d = new int[c + 1][c + 1];
            for (int i = 1; i <= c; i++) {
                for (int j = 1; j <= c; j++) {
                    d[i][j] = in.nextInt();
                }
            }

            int[][] cc = new int[n + 1][n + 1];
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    cc[i][j] = in.nextInt();
                }
            }
            int[][] cost = new int[3][c + 1];

            PriorityQueue<Pair> pq = new PriorityQueue<>(n, (Comparator.comparingLong(o -> o.cost)));
            boolean[] list = new boolean[c + 1];
            for (int to = 1; to <= c; to++) {
                long t0 = 0;
                long t1 = 0;
                long t2 = 0;

                for (int i = 1; i <= n; i++) {
                    for (int j = 1; j <= n; j++) {
                        int cfrom = cc[i][j];
                        int ccost = d[cfrom][to];
                        cost[(i + j) % 3][to] += ccost;
                        if ((i + j) % 3 == 0) {
                            t0 += d[cfrom][to];
                        }
                        if ((i + j) % 3 == 1) {
                            t1 += d[cfrom][to];
                        }
                        if ((i + j) % 3 == 2) {
                            t2 += d[cfrom][to];
                        }
                    }
                }
                pq.add(new Pair(to, t0));
                pq.add(new Pair(to, t1));
                pq.add(new Pair(to, t2));
            }
            int res = Integer.MAX_VALUE;
            for (int i = 1; i <= c; i++) {
                for (int j = 1; j <= c; j++) {
                    if (i == j) {
                        continue;
                    }
                    for (int k = 1; k <= c; k++) {
                        if (k == i || k == j) {
                            continue;
                        }
                        int tmp = cost[0][i];
                        tmp += cost[1][j];
                        tmp += cost[2][k];
                        res = Math.min(res, tmp);
                    }
                }
            }
            out.println(res);
