    public static void search(int n,int c){
        int cc[][] = new int[3][c];
        int s = 2;
        for (int x = 0;x < n;++x){
            s = (x + 2) % 3;
            for (int y = 0;y < n;++y){
                ++cc[s][cArray[x][y] - 1];
                ++s;
                if(s == 3)s = 0;
            }
        }

        long min = Long.MAX_VALUE;
        for (int c1 = 1;c1 <= c;++c1) {
            for (int c2 = 1; c2 <= c; ++c2) {
