                for (int c3 = 1; c3 <= c; ++c3) {
                    if (c1 == c3 || c2 == c3) continue;
                    long k = 0;
                    for (int nn = 0;nn < c;++nn){
                        k += dArray[c3 - 1][nn] * cc[0][nn];
                        k += dArray[c1 - 1][nn] * cc[1][nn];
                        k += dArray[c2 - 1][nn] * cc[2][nn];
                    }
                    if(min > k)min = k;
                }
            }
        }


        System.out.println(min);
    }

