	static int[] mh8 = { -1, -1, -1, 0, 0, 1, 1, 1 };
	static int[] mw8 = { -1, 0, 1, -1, 1, -1, 0, 1 };

	static class TaskX {
		long[][] memo;
		int N, C;
		int[][] d,c;
		public void solve(int testNumber, InputReader in, PrintWriter out) {

			N = in.nextInt(); C = in.nextInt();
			d = new int[C][C];
			c = new int[N][N];

			for (int i = 0; i < C; i++) {
				for (int j = 0; j < C; j++) {
					d[i][j] = in.nextInt();
				}
			}

			for (int i = 0; i < N; i++) {
				for (int j = 0; j < N; j++) {
					c[i][j] = in.nextInt();
				}
			}

			memo = new long[3][C+1];
			for (int i = 0; i < 3; i++) {
				Arrays.fill(memo[i], -1);
			}

			long ans = Long.MAX_VALUE/2;
			for (int i = 1; i <= C; i++) {
				for (int j = 1; j <= C; j++) {
					for (int k = 1; k <= C; k++) {
						if (i == j || j == k || k == i) {
							continue;
						}
						ans = Math.min(ans, dfs(0, i) + dfs(1, j) + dfs(2, k));
					}
				}
			}

			out.println(ans);

		}

		long dfs(int mod, int to) {

			if (memo[mod][to] > 0) {
				return memo[mod][to];
			}

			int ret = 0;
			for (int i = 0; i < N; i++) {
				for (int j = 0; j < N; j++) {
					if ((i+1 + j+1) % 3 == mod) {
						ret += d[c[i][j]-1][to-1];
					}
				}
			}

			return memo[mod][to] = ret;
		}
	}

