class Main{

	static int ans = Integer.MAX_VALUE;
	static int C;
	static int[][] d;
	static ArrayList<Integer> zero;
	static ArrayList<Integer> one;
	static ArrayList<Integer> two;




	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);			//文字の入力
		int n = sc.nextInt();
