		            if((i+j)%3 == 0){
		                d0[k][0] = k;
		                d0[k][1] += gridD[gridC[i][j]][k];
		            }else if((i+j)%3 == 1){
		                d1[k][0] = k;
		                d1[k][1] += gridD[gridC[i][j]][k];
