namespace Contest
{
    class Scanner
    {
        private string[] line = new string[0];
        private int index = 0;

        public string Next()
        {
            if (line.Length <= index)
            {
                line = Console.ReadLine().Split(' ');
                index = 0;
            }

            var res = line[index];
            index++;
            return res;
        }

        public int NextInt()
        {
            return int.Parse(Next());
        }

        public long NextLong()
        {
            return long.Parse(Next());
        }

        public string[] Array()
        {
            line = Console.ReadLine().Split(' ');
            index = line.Length;
            return line;
        }

        public int[] IntArray()
        {
            var array = Array();
            var result = new int[array.Length];
            for (int i = 0; i < array.Length; i++)
            {
                result[i] = int.Parse(array[i]);
            }

            return result;
        }

        public long[] LongArray()
        {
            var array = Array();
            var result = new long[array.Length];
            for (int i = 0; i < array.Length; i++)
            {
                result[i] = long.Parse(array[i]);
            }

            return result;
        }
    }

    class Program
    {
        private int N;
        private int C;
        private int[][] D;
        private int[][] c;
        private int[,] change;
        private void Scan()
        {
            var sc = new Scanner();
            N = sc.NextInt();
            C = sc.NextInt();
            D = new int[C][];
            for (int i = 0; i < C; i++)
            {
                D[i] = sc.IntArray();
            }

            c = new int[N][];
            for (int i = 0; i < N; i++)
            {
                c[i] = sc.IntArray().Select(j => j - 1).ToArray();
            }
        }


        public void Solve()
        {
            Scan();
            int ans = int.MaxValue;
            change = new int[3, C];
            for (int i = 0; i < N; i++)
            {
                for (int j = 0; j < N; j++)
                {
                    int index = (i + j) % 3;
                    for (int k = 0; k < C; k++)
                    {
                        change[index, k] += D[c[i][j]][k];
                    }
                }
            }
            for (int i = 0; i < C; i++)
            {
                for (int j = 0; j < C; j++)
                {
                    if (i == j) continue;
                    for (int k = 0; k < C; k++)
                    {
                        if (i == k || j == k) continue;
                        ans = Math.Min(ans, Calc(i, j, k));
                    }
                }
            }
            Console.WriteLine(ans);
        }

        private int Calc(params int[] col)
        {
            return change[0, col[0]] + change[1, col[1]] + change[2, col[2]];
        }


        static void Main() => new Program().Solve();
    }

}

