public class Hello
{
    private const int INF = 1000000007;
    public static void Main()
    {
        int N = NextInt();
        int C = NextInt();
        List<int[]> D = new List<int[]>();
        List<int[]> c = new List<int[]>();
        for (int i = 0; i < C; i++) D.Add(LineInt());
        for (int i = 0; i < N; i++) c.Add(LineInt());
        //WF
        int[,] WF = new int[C, C];
        for (int i = 0; i < C; i++)
            for (int j = 0; j < C; j++) WF[i, j] = INF;
        for (int i = 0; i < C; i++)
            for (int j = 0; j < C; j++) WF[i, j] = D[i][j];
        //for (int x = 0; x < C; x++)
        //    for (int s = 0; s < C; s++)
        //        for (int t = 0; t < C; t++)
        //            WF[s, t] = Math.Min(WF[s, t], WF[s, x] + WF[x, t]);
        Dictionary<int, int>[] d = new Dictionary<int, int>[3];
        d[0] = new Dictionary<int, int>();
        d[1] = new Dictionary<int, int>();
        d[2] = new Dictionary<int, int>();
        for (int i = 0; i < N; i++)
            for (int j = 0; j < N; j++)
            {
                if (!d[(i + j) % 3].ContainsKey(c[i][j] - 1)) d[(i + j) % 3][c[i][j] - 1] = 0;
                d[(i + j) % 3][c[i][j] - 1]++;
            }
        long ans = INF;
        for (int x = 0; x < C; x++)
            for (int y = 0; y < C; y++)
                for (int z = 0; z < C; z++)
                {
                    if (x == y || y == z || z == x) continue;
                    //%=0 : x   %=1 : y %=2 : z とする
                    //それぞれの色をxyzに変えていく
                    int cost = 0;
                    foreach (var e in d[0])
                        if (e.Key != x) cost += e.Value * WF[e.Key, x];
                    foreach (var e in d[1])
                        if (e.Key != y) cost += e.Value * WF[e.Key, y];
                    foreach (var e in d[2])
                        if (e.Key != z) cost += e.Value * WF[e.Key, z];
                    ans = Math.Min(cost, ans);
                }
        Console.WriteLine(ans);
    }

