	    public static int LowerBound<T>(this List<T> @this, T x) where T : IComparable
	    {
            int lb = -1, ub = @this.Count;
	        while (ub - lb > 1)
	        {
	            int mid = (ub + lb) >> 1;
	            if (@this[mid].CompareTo(x) >= 0) ub = mid;
	            else lb = mid;
	        }
	        return ub;
	    }
	    public static int UpperBound<T>(this List<T> @this, T x) where T : IComparable
	    {
	        int lb = -1, ub = @this.Count;
	        while (ub - lb > 1)
	        {
	            int mid = (ub + lb) >> 1;
	            if (@this[mid].CompareTo(x) > 0) ub = mid;
	            else lb = mid;
	        }
	        return ub;
	    }
