        var ct = Create(3, () => new int[C]);
        for (var i = 0; i < N; i++)
            for (var j = 0; j < N; j++)
                ct[(i + j) % 3][--G[i][j]]++;
        var cn = Create(3, () => new int[C]);
        for (var l = 0; l < 3; l++)
            for (var i = 0; i < C; i++)
                for (var j = 0; j < C; j++)
                    cn[l][i] += ct[l][j] * D[j][i];
        var res = int.MaxValue;
        for (var i = 0; i < C; i++)
            for (var j = 0; j < C; j++)
                for (var k = 0; k < C; k++)
                {
                    if (i == j || j == k || i == k) continue;
                    var c = cn[0][i] + cn[1][j] + cn[2][k];
                    chmin(ref res, c);
                }
        Console.WriteLine(res);
    }
