public class D
{
	public static void Main()
	{
		string[] args;

		args = Console.ReadLine().Split(' ');
		int N = Int32.Parse(args[0]);
		int C = Int32.Parse(args[1]);

		int[,] D = new int[C+1,C+1];
		for(int i = 1; i <= C; i++)
		{
			args = Console.ReadLine().Split(' ');
			for(int j = 1; j <= C; j++)
				D[i,j] = Int32.Parse(args[j-1]);
		}

		int[,] c = new int[N+1,N+1];
		for(int i = 1; i <= N; i++)
		{
			args = Console.ReadLine().Split(' ');
			for(int j = 1; j <= N; j++)
				c[i,j] = Int32.Parse(args[j-1]);
		}

		int[] selected = new int[3];
		int ans = Int32.MaxValue;
		for(int mask = 0; mask < Math.Pow(C,3); mask++)
		{
			int tmp = mask;
			for(int i = 0; i < 3; i++)
			{
				selected[i] = (tmp % C) + 1;
				tmp /= C;
			}
			if((selected[0] == selected[1]) || 
				(selected[1] == selected[2]) ||
				(selected[2] == selected[0]))
				continue;

			int sum = 0;
			for(int i = 1; i <= N; i++)
				for(int j = 1; j <= N; j++)
					sum += D[c[i,j],selected[(i + j) % 3]];

			ans = Math.Min(ans, sum);
		}

		Console.WriteLine(ans);		
	}	
}

