using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

class Program
{
    static void Main(string[] args)
    {
        var sc = new Scanner();
        int n = sc.NextInt();
        int b = sc.NextInt();
        int[,] d = new int[b, b];
        for (int i = 0; i < b; i++)
            for (int j = 0; j < b; j++)
                d[i, j] = sc.NextInt();

        int[,] t = new int[3, 30];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
            {
                t[(i + j) % 3, sc.NextInt() - 1]++;
            }

        int min = 1 << 30;
        for (int i = 0; i < b; i++)
            for (int j = 0; j < b; j++)
            {
                if (i == j) continue;
                for (int k = 0; k < b; k++)
                {
                    if (i == k || j == k) continue;
                    int ans = 0;
                    for (int l = 0; l < b; l++) ans += d[l, i] * t[0, l];
                    for (int l = 0; l < b; l++) ans += d[l, j] * t[1, l];
                    for (int l = 0; l < b; l++) ans += d[l, k] * t[2, l];
                    if (ans < min) min = ans;
                }
            }
        Console.WriteLine(min);
    }
}

class Scanner
{
    int index = -1;
    string[] buf;

    public Scanner()
    {
    }

    public int NextInt()
    {
        CheckNext();
        return int.Parse(buf[index++]);
    }

    public long NextLong()
    {
        CheckNext();
        return long.Parse(buf[index++]);
    }

    public double NextDouble()
    {
        CheckNext();
        return double.Parse(buf[index++]);
    }

    public string NextString()
    {
        CheckNext();
        return buf[index++];
    }

    private void CheckNext()
    {
        if (index >= 0 && index < buf.Length) return;

        buf = Console.ReadLine().Split(' ');
        index = 0;
    }
}

using System;
using System.Linq;//リストの使用
using System.Collections.Generic;
using System.Text;//テキストの高速出力に必要
class Program
{
	static void Main()
	{
		string[] input = Console.ReadLine().Split(' ');//Splitで区切り文字を指定して複数個受け取る。
		long n = long.Parse(input[0]);
		long c = long.Parse(input[1]);
    long answer = long.MaxValue;
    long answerMemo = 0;
    long[,] originalColors = new long[c,3];//それぞれの余りにおける色の数

    int[,] matrixDistance = new int[c,c];//行列
    for(int i = 0; i < c; i++)//それぞれの行
    {
    	int[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),int.Parse);
    	for(int j = 0; j < c; j++) matrixDistance[i,j] = nums[j];//行の全ての成分
    }

    int[,] matrixColor = new int[n,n];//行列  
    for(int i = 0; i < n; i++)//それぞれの行
    {
    	int[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),int.Parse);
    	for(int j = 0; j < n; j++) matrixColor[i,j] = nums[j]-1;//行の全ての成分
    }

    for(int a = 0; a < n; a++)
    {
      for(int b = 0; b < n; b++)
      {
        if((a+b)% 3 == 0)
          originalColors[matrixColor[a,b],0]++;
        if((a+b)% 3 == 1)
          originalColors[matrixColor[a,b],1]++;
        if((a+b)% 3 == 2)
          originalColors[matrixColor[a,b],2]++;
      }
    }

    for(int i = 0; i < c; i++)//全色試す
    {
      for(int j = 0; j < c; j++)
      {
        for(int k = 0; k < c; k++)
        {
          if(i == j || i == k || j == k) continue;//同じ色はダメ
          answerMemo = 0;
          for(int a = 0; a < c; a++)
          {
            answerMemo += matrixDistance[a,i] * originalColors[a,0];
            answerMemo += matrixDistance[a,j] * originalColors[a,1];
            answerMemo += matrixDistance[a,k] * originalColors[a,2];
          }

          answer = Math.Min(answer, answerMemo);
        }
      }
    }


		Console.WriteLine(answer);
	}
}

