    {
        public static void Main(string[] args)
        {
            int[] ints = Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);
            int n = ints[0];
            int c = ints[1];

            int[][] ds = new int[c][];
            for (int i = 0; i < c; i++)
            {
                int[] dline = Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);
                ds[i] = dline;
            }

            int[][] cs = new int[n][];
            for (int i = 0; i < n; i++)
            {
                int[] cline = Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);
                cs[i] = cline;
            }

            int[][] scores = new int[3][];
            for (int i = 0; i < 3; i++)
            {
                scores[i] = score(cs, ds, i, n, c);
            }

            int[] patterns = new int[c * c * c];
            for (int i = 0; i < c; i++)
            {
                for (int j = 0; j < c; j++)
                {
                    for (int k = 0; k < c; k++)
                    {
                        if (i == j || i == k || j == k)
                        {
                            patterns[i + c*j + c*c*k] = Int32.MaxValue;
                            continue;
                        }

                        patterns[i + c * j + c * c * k] = scores[0][i] + scores[1][j] + scores[2][k];
                    }
                }
            }
            Console.WriteLine(patterns.Min());
        }

        public static int[] score(int[][] cs, int[][] ds, int offset, int n, int c)
        {
            int space = n * n;

            int[] scores = new int[c];
            for (int colorIndex = 0; colorIndex < c; colorIndex++)
            {
                for (int i = 0; i < space; i++)
                {
                    int ndiv = i / n;
                    int ndiva = i % n;
                    if ((ndiv + ndiva) % 3 != offset)
                    {
                        continue;
                    }

                    int currentColorIndex = cs[ndiv][ndiva] - 1;
                    int score = ds[currentColorIndex][colorIndex];
                    scores[colorIndex] += score;
                }
            }

            return scores;
        }
    }
}

