    	for(int j = 0; j < c; j++) matrixDistance[i,j] = nums[j];//行の全ての成分
    }

    int[,] matrixColor = new int[n,n];//行列  
    for(int i = 0; i < n; i++)//それぞれの行
    {
    	int[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),int.Parse);
    	for(int j = 0; j < n; j++) matrixColor[i,j] = nums[j];//行の全ての成分
    }

    for(int i = 0; i < c; i++)//全色試す
    {
      for(int j = 0; j < c; j++)
      {
        for(int k = 0; k < c; k++)
        {
          if(i == j || i == k || j == k) continue;//同じ色はダメ
          answerMemo = 0;

          for(int a = 0; a < n; a++)
          {
            for(int b = 0; b < n; b++)
            {
              if((a+b)% 3 == 0)
                answerMemo += matrixDistance[matrixColor[a,b]-1, i];
              if((a+b)% 3 == 1)
                answerMemo += matrixDistance[matrixColor[a,b]-1, j];
              if((a+b)% 3 == 2)
                answerMemo += matrixDistance[matrixColor[a,b]-1, k];
            }
          }

          answer = Math.Min(answer, answerMemo);

        }
      }
    }


		Console.WriteLine(answer);
	}
}

