    public string Result() { var obj = Calc(); if (obj is bool) return (bool)obj ? "Yes" : "No"; if (obj is double) return ((double)obj).ToString("0.####################"); return obj.ToString(); }
    private object Calc()
    {
        var N = cr.Int;
        var C = cr.Int;
        var d = cr.Repeat(C).Select(cr => cr.Split.Int);
        var c = cr.Repeat(N).Select(cr => cr.Split.Int0);

        var m = NewArray(3, C, 0);
        for (int i = 0; i < N; i++)
            for (int j = 0; j < N; j++)
                m[(i + j) % 3][c[i][j]]++;

        long min = long.MaxValue;
        for (int c0 = 0; c0 < C; c0++)
            for (int c1 = 0; c1 < C; c1++)
                for (int c2 = 0; c2 < C; c2++)
                    if (c0 != c1 && c0 != c2 && c1 != c2)
                    {
                        long cnt = 0;
                        for (int cc = 0; cc < C; cc++)
                        {
                            cnt += m[0][cc] * d[cc][c0];
                            cnt += m[1][cc] * d[cc][c1];
                            cnt += m[2][cc] * d[cc][c2];
                        }
                        UpdateMin(ref min, cnt);
                    }
        return min;
    }
