				for (int t = 0; t < C; t++) {
					ulong sum = 0;
					for (int f = 0; f < C; f++) {

						// すべての色を t にした場合の違和感合計
						sum += (ulong)cGrid[i, f] * (ulong)dGrid[f][t];
					}
					dSums[i, t] = sum;
				}
			}

