			ulong minD = ulong.MaxValue;
			var C = dSums.GetLength(1);
			for (int i = 0; i < C; i++) {
				for (int j = 0; j < C; j++) {
					if (i == j) continue;
					for (int k = 0; k < C; k++) {
						if (i == k || j == k) continue;
						var sum = dSums[0, i] + dSums[1, j] + dSums[2, k];
						ReplaceIfSmaller(ref minD, sum);
					}
				}
			}
			return minD;
		}

