using static System.Console;

class Solver {
    Scanner sc = new Scanner();

    public void Solve() {
        int N = sc.nextInt();
        int C = sc.nextInt();
        var D = new int[C, C];
        for (int i = 0; i < C; i++) {
            for (int j = 0; j < C; j++) {
                D[i, j] = sc.nextInt();
            }
        }
        var c = new int[N, N];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                c[i, j] = sc.nextInt();
            }
        }

        var zero = new long[C];
        var one = new long[C];
        var two = new long[C];
        for (int k = 0; k < C; k++) {
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < N; j++) {
                    if ((i + j + 2) % 3 == 0) {
                        zero[k] += D[c[i, j] - 1, k];
                    } else if ((i + j + 2) % 3 == 1) {
                        one [k] += D[c[i, j] - 1, k];
                    } else {
                        two[k] += D[c[i, j] - 1, k];
                    }
                }
            }
        }

        var min = long.MaxValue;
        for (int i = 0; i < C; i++) {
            for (int j = 0; j < C; j++) {
                if (i == j) continue;
                for (int k = 0; k < C; k++) {
                    if (i == k) continue;
                    if (j == k) continue;

                    min = Math.Min(min, zero[i] + one[j] + two[k]);
                }
            }
        }
        WriteLine(min);
    }
}



