		{
			int[] sum = new int[3];
			for(int i = 0; i < N; i++)
				for(int j = 0; j < N; j++)
					sum[(i + j) % 3] += D[c[i,j],k];

			for(int i = 0; i < 3; i++)
				lists[i].Add(new Pair(k, sum[i]));
