            s = Console.ReadLine();
            N = int.Parse(s.Split(' ')[0]);
            C = int.Parse(s.Split(' ')[1]);
            int[,] D = new int[C, C];
            for (int i = 0; i < C;i++){
                s = Console.ReadLine();
                for (int j = 0; j < C;j++){
                    D[i, j] = int.Parse(s.Split(' ')[j]);
                }
            }
            int[,] c = new int[N, N];
            int[,] group = new int[3, C];
            for (int i = 0; i < N; i++)
            {
                s = Console.ReadLine();
                for (int j = 0; j < N; j++)
                {
                    c[i, j] = int.Parse(s.Split(' ')[j])-1;
                    group[(i + j) % 3, c[i, j]]++;
                }
            }

            //グループごとの色のカウント
            /*for (int i = 0; i < N;i++){
                for (int j = 0; j < N;j++){
                    group[(i + j) % 3, c[i, j]]++;
                }
            }*/

            //塗り替えコストのワースト3をだす
            int[,] lowscore = new int[3, 3];
            for (int i = 0; i < 3; i++)
                for (int j = 0; j < 3; j++) lowscore[i, j] = int.MaxValue;
            int[,] color = new int[3, 3];
            for (int j = 0; j < C; j++)//色jに塗り替える
            {
                int[] sum=new int[3];
                for (int i = 0; i < C; i++)//色iから塗り替える
                {
                    sum[0] += D[i, j] * group[0, i];
                    sum[1] += D[i, j] * group[1, i];
                    sum[2] += D[i, j] * group[2, i];
                }
                for (int i = 0; i < 3;i++){
                    if(lowscore[i,0]>=sum[i]){
                        lowscore[i, 2] = lowscore[i, 1];
                        color[i, 2] = color[i, 1];
                        lowscore[i, 1] = lowscore[i, 0];
                        color[i, 1] = color[i, 0];
                        lowscore[i, 0] = sum[i];
                        color[i, 0] = j;
                    }else if(lowscore[i, 1] >= sum[i]){
                        lowscore[i, 2] = lowscore[i, 1];
                        color[i, 2] = color[i, 1];
                        lowscore[i, 1] = sum[i];
                        color[i, 1] = j;
                    }else if(lowscore[i, 2] >= sum[i]){
                        lowscore[i, 2] = sum[i];
                        color[i, 2] = j;
                    }
                }
            }

            //ワースト３から組み合わせで最少を求める
            int min = int.MaxValue;
            for (int i = 0; i < 3;i++){//0はワーストi
                for (int j = 0; j < 3;j++){//1はワーストj
                    for (int k = 0; k < 3;k++){//2はワーストkを選ぶ
                        if(color[0,i]!=color[1,j]&&color[0,i]!=color[2,k]&&color[1,j]!=color[2,k]){
                            int l = lowscore[0, i] + lowscore[1, j] + lowscore[2, k];
                            if (min > l) min = l;
                        }
                    }
                }
            }
            Console.WriteLine(min);
        }
    }
}

