class Program
{
    static void Main(string[] args)
    {
        var N = sc.ReadInt();
        var C = sc.ReadInt();
        var D = new int[C, C];
        for (int i = 0; i < C; i++)
        {
            for (int j = 0; j < C; j++)
            {
                D[i, j] = sc.ReadInt();
            }
        }
        var c = new int[N, N];
        for (int i = 0; i < N; i++)
        {
            for (int j = 0; j < N; j++)
            {
                c[i, j] = sc.ReadInt() - 1;
            }
        }

        // mod3 のマスをjに塗り替えるときの違和感の合計
        var sum = new long[3, C];
        for (int h = 0; h < N; h++)
        {
            for (int w = 0; w < N; w++)
            {
                var mod3 = (h + w) % 3;
                for (int j = 0; j < C; j++)
                {
                    sum[mod3, j] += D[c[h, w], j];
                }
            }
        }

        var ans = long.MaxValue;
        // 使う色の組み合わせ
        for (int i = 0; i < C; i++)
        {
            for (int j = 0; j < C; j++)
            {
                for (int k = 0; k < C; k++)
                {
                    // 同じ色は使えない
                    if (i == j || j == k || k == i) continue;

                    // 色(i, j, k)を使うときの違和感の合計値
                    var tmp = sum[0, i] + sum[1, j] + sum[2, k];
                    ans = Math.Min(ans, tmp);
                }
            }
        }
        Console.WriteLine(ans);
    }
    static Scanner sc = new Scanner();
}
