public class CompetitiveProgramming {
  public void Solve () {
    var o = Ints;
    var N = o[0];
    var C = o[1];
    var D = new int[C][];
    for (int i = 0; i < C; ++i) D[i] = Ints;
    var c = new int[N][];
    for (int i = 0; i < N; ++i) c[i] = Ints;
    int mi = INF;
    var cntcol = new int[3][];
    for (int i = 0; i < 3; ++i) cntcol[i] = new int[C];
    for (int i = 0; i < N; ++i) {
      for (int j = 0; j < N; ++j) {
        ++cntcol[(i + j) % 3][c[i][j] - 1];
      }
    }
    for (int i = 0; i < C; ++i) {
      for (int j = 0; j < C; ++j) {
        for (int k = 0; k < C; ++k) {
          if (i == j || j == k || k == i) continue;
          var c1 = i;
          var c2 = j;
          var c3 = k;
          int sum = 0;
          for (int l = 0; l < C; ++l) {
            sum += D[l][c1] * cntcol[0][l];
            sum += D[l][c2] * cntcol[1][l];
            sum += D[l][c3] * cntcol[2][l];
          }
          mi = Min (mi, sum);
        }
      }
    }
    Put (mi);
  }
}

public static class Math2 {
  public const int INF = 1 << 29;
  public const long INFL = 1L << 60;
  public const long MOD = 1000000007;
  public const int MOD2 = 998244353;

  public static long Power (long a, long b, long MOD = 1000000007) //i^N
  {
    long res = 1;
    while (b > 0) {
      if ((b & 1) != 0) res = res * a % MOD;
      a = a * a % MOD;
      b >>= 1;
    }
    return res;
  }
  public static long Power2 (long a, long b) //i^N
  {
    long res = 1;
    while (b > 0) {
      if ((b & 1) != 0) res = res * a;
      a = a * a;
      b >>= 1;
    }
    return res;
  }
  public static long GCD (long a, long b) {
    while (b > 0) {
      var r = a % b;
      a = b;
      b = r;
    }
    return a;
  }
  public static long LCM (long a, long b) => (b / GCD (a, b)) * a;
  public static long Comb (long n, long r, int MOD = 1000000007) {
    if (r > n - r) r = n - r;
    long Nume = 1;
    long Deno = 1;

    if (r > n - r) r = n - r;
    for (long i = 1; i <= r; ++i) {
      Deno = (Deno * i) % MOD;
      Nume = Nume * (n - i + 1) % MOD;
    }
    return (Nume * inv (Deno)) % MOD;
  }
  public static long Comb2 (long n, long r) {
    long Nume = 1;
    long Deno = 1;

    if (r > n - r) r = n - r;
    for (long i = 1; i <= r; ++i) {
      Deno *= i;
      Nume *= n - i + 1;
    }
    return Nume / Deno;
  }
  public static long inv (long x, int MOD = 1000000007) {
    return Power (x, MOD - 2, MOD);
  }
}
