            var colors = consoleReader.Repeat(N).Select(cr => cr.Split.Int.Select(i => i - 1).ToArray()).ToArray();

            var grouped = new[] { new List<int>(), new List<int>(), new List<int>() };
            for (int i = 0; i < N; i++)
                for (int j = 0; j < N; j++)
                {
                    grouped[(i + j) % 3].Add(colors[i][j]);
                }

            var costs = new int[][] { new int[C], new int[C], new int[C] };
            for (int c = 0; c < C; c++)
                for (int i = 0; i < 3; i++)
                    foreach (var g in grouped[i])
                        costs[i][c] += diffs[g][c];
            var result = costs.Select(g => g.Select((v, i) => new KeyValuePair<int, int>(i, v)).OrderBy(p => p.Value).Take(3).ToArray()).ToArray();
