            foreach (var item0 in result[0])
                foreach (var item1 in result[1])
                    foreach (var item2 in result[2])
                        if (item0.Key != item1.Key && item0.Key != item2.Key && item1.Key != item2.Key)
                        {
                            min = Math.Min(item0.Value + item1.Value + item2.Value, min);
                        }
            return min;
