	public void Solve(){

		int NC3 = NC * NC * NC;
		int NC2 = NC * NC;
		long[] min = new long[NC3];

		Parallel.For(0, NC3, ijk => {
			min[ijk] = Calc(ijk / NC2, (ijk % NC2) / NC, ijk % NC);
		});

		Console.WriteLine(min.Min());

	}

	const long inf = (long) 1e18;
	long Calc(int x, int y, int z){
//Console.WriteLine("{0} {1} {2}",x, y , z);
		if(x == y || y == z || z == x) return inf;
		int[] c = new int[3];
		c[0] = x; c[1] = y; c[2] = z;
		long ret = 0;
		for(int i=0;i<N;i++){
			int cidx = i % 3;
			for(int j=0;j<N;j++){
				ret += D[C[i][j]][c[cidx]];
				cidx++; if(cidx == 3) cidx = 0;
			}
		}
		return ret;
	}


