        static void Main(string[] args)
        {
            Method(args);
            Console.ReadLine();
        }

        static void Method(string[] args)
        {
            int[] nc = ReadInts();
            int n = nc[0];
            int c = nc[1];
            var ds = new int[c, c];
            for (int i = 0; i < c; i++)
            {
                int[] input = ReadInts();
                for(int j = 0; j < c; j++)
                {
                    ds[i, j] = input[j];
                }
            }

            var cs = new int[n, n];
            for (int i = 0; i < n; i++)
            {
                int[] input = ReadInts();
                for (int j = 0; j < n; j++)
                {
                    cs[i, j] = input[j];
                }
            }

            var colors = new int[3,c];//余りと色の個数
            for(int i = 0; i < n; i++)
            {
                for(int j = 0; j < n; j++)
                {
                    colors[(i + j) % 3, cs[i, j] - 1]++;
                }
            }

            var errors = new int[3, c];
            for(int i = 0; i < 3; i++)
            {
                for(int j = 0; j < c; j++)
                {
                    errors[i,j] = 0;
                    for(int k = 0; k < c; k++)
                    {//色kからjに変える
                        errors[i, j] += colors[i, k] * ds[k, j];
                    }
                }
            }

            int minError = int.MaxValue;
            for(int i = 0; i < c; i++)
            {
                for(int j = 0; j < c; j++)
                {
                    if (i == j) continue;

                    for(int k = 0; k < c; k++)
                    {
                        if (i == k || j == k) continue;

                        int errorSum 
                            = errors[0, i] + errors[1, j] + errors[2, k];
                        minError = Math.Min(minError, errorSum);
                    }
                }
            }

            Console.WriteLine(minError);
        }

