        for(int i = a; i < b; i += n)
            act(i);
    }
    public static void REPEQ(int a, Action <int> act) => FOR(0, a + 1, act);
    public static void FOREQ(int a, int b, Action <int> act) => FOR(a, b + 1, act);
    public static void FOREQ(int a, int b, int n, Action <int> act) => FOR(a, b + 1, n, act);
