        for (int i = 0; i < N; i++) {
            Array[i] = Long() + add;
        }
        return Array;
    }
}
class Program {

    static Scanner cin = new Scanner();
    static void Main() {
        int N = cin.Int();
        int C = cin.Int();
        var D = new int[35, 35];
        for (int i = 0; i < C; i++) {
            var tmp = cin.ArrayInt(C);
            for (int j = 0; j < C; j++) {
                D[i, j] = tmp[j];
            }
        }
        var c = new int[5, 35];
        for (int i = 0; i < N; i++) {
            var tmp = cin.ArrayInt(N);
            for (int j = 0; j < N; j++) {
                c[(i + j) % 3, tmp[j] - 1]++; //マスを3で割った余り、色の値を格納
            }
        }

        int ans = int.MaxValue;
        for (int i = 0; i < C; i++) {
            for (int j = 0; j < C; j++) {
                for (int k = 0; k < C; k++) {
                    if(i != j && j != k && k != i) { //色の被りがないようにする
                        int tmp = 0;
                        for (int l = 0; l < C; l++) {
                            tmp += D[l, i] * c[0, l];
                        }
                        for (int l = 0; l < C; l++) {
                            tmp += D[l, j] * c[1, l];
                        }
                        for (int l = 0; l < C; l++) {
                            tmp += D[l, k] * c[2, l];
                        }
                        ans = Math.Min(ans, tmp);
                    }
                }
            }
        }
        Console.WriteLine(ans);
        Console.ReadLine();
    }
}

