internal partial class Solver {
    public void Run() {
        var n = ni();
        var c = ni();
        var d = new int[c, c];
        for (int i = 0; i < c; i++) {
            for (int j = 0; j < c; j++) {
                d[i, j] = ni();
            }
        }
        var g = new int[n, n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                g[i, j] = ni() - 1;
            }
        }
        var a = Enumerable.Range(0, 3).Select(_ => new List<int>()).ToArray();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                a[(i + j) % 3].Add(g[i, j]);
            }
        }

        var v = Enumerable.Range(0, 3).Select(_ => new List<KeyValuePair<int, int>>()).ToArray();
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < c; j++) {
                var cost = a[i].Sum(x => d[x, j]);
                v[i].Add(new KeyValuePair<int, int>(j, cost));
            }
            v[i].Sort((k1, k2) => k1.Value.CompareTo(k2.Value));
        }
        long ans = (
            from kv0 in v[0].Take(3)
            from kv1 in v[1].Take(3)
            from kv2 in v[2].Take(3)
            where kv0.Key != kv1.Key && kv1.Key != kv2.Key && kv0.Key != kv2.Key
            select kv0.Value + kv1.Value + kv2.Value
        ).Min();
        cout.WriteLine(ans);
    }
}

