namespace AtCorder
{
	public class Program
	{
		static void Main(string[] args)
		{
			var nc = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
			int n = nc[0];
			int c = nc[1];

			int[,] d = new int[c, c];
			for (int i = 0; i < c; i++) {
				var ds = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
				for (int j = 0; j < c; j++) {
					d[i, j] = ds[j];
				}
			}

			int[,] colors = new int[n, n];
			for (int i = 0; i < n; i++) {
				var cs = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
				for (int j = 0; j < n; j++) {
					colors[i, j] = cs[j] - 1;
				}
			}

			int[,] sumD = new int[3, c];
			for (int i = 0; i < c; i++) {
				for (int ii = 0; ii < n; ii++) {
					for (int jj = 0; jj < n; jj++) {
						int p = (ii + jj) % 3;
						sumD[p, i] += d[colors[ii, jj], i];
					}
				}
			}

			int ans = int.MaxValue;
			for (int i = 0; i < c; i++) {
				for (int j = 0; j < c; j++) {
					if (i == j) {
						continue;
					}

					for (int k = 0; k < c; k++) {
						if (k == i || k == j) {
							continue;
						}

						int temp = sumD[0, i] + sumD[1, j] + sumD[2, k];
						ans = Math.Min(ans, temp);
					}
				}
			}

			Console.WriteLine(ans);
		}
	}
}

