    class Program
    {
        static StreamReader sr;

        static public long[] Sarray() { return ReadLine().Split().Select(long.Parse).ToArray(); }
        static public List<long> Slist() { return ReadLine().Split().Select(long.Parse).ToList(); }
        static long Mod = (long)998244353;
        static void Main(string[] args)
        {
            //SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
            var NC = Sarray();
            var N = NC[0];
            var C = NC[1];

            var Di = new long[C][];
            for (var i = 0; i < C; ++i)
                Di[i] = Sarray();
            // 色をiからjに変更するときの違和感の最小値
            /*for (var k = 0; k < C; ++k)
                for (var i = 0; i < C; ++i)
                    for (var j = 0; j < C; ++j)
                        Di[i][j] = Min(Di[i][j], Di[i][k] + Di[k][j]);*/

            var Ci = Enumerable.Range(0, 3).Select(_ => new long[C]).ToArray();
            // %3のグリッドについて出てくる色の数
            for (var i = 0; i < N; ++i)
            {
                var cij = Sarray();
                for (var j = 0; j < N; ++j)
                    ++Ci[(i + j) % 3][cij[j] - 1];
            }

            // 色を3つ決めて違和感を計算
            var ans = long.MaxValue;
            for (var i = 0; i < C; ++i)
            {
                for (var j = 0; j < C; ++j)
                {
                    if (i == j) continue;
                    for (var k = 0; k < C; ++k)
                    {
                        if (j == k || i == k) continue;
                        var t = 0L;
                        for (var l = 0; l < C; ++l)
                        {
                            t += Di[l][i] * Ci[0][l];
                            t += Di[l][j] * Ci[1][l];
                            t += Di[l][k] * Ci[2][l];
                        }
                        ans = Min(ans, t);
                    }
                }
            }
            WriteLine(ans);
            //Out.Flush();
        }
