class AC {
    /*------------------------------------------------------------------*/
    private int N, C;
    private int[,] D, c;
    void Solve() {
        io.i(out N, out C);
        io.ini(out D, C, C);
        io.ini(out c, N, N);
        c = c.To0Indexed();
        var cnt = new int[3, 30];
        REP(N, i => REP(N, j => cnt[(i + 1 + j + 1) % 3, c[i, j]]++));
        var ans = int.MaxValue;
        REP(C, i => REP(C, j => {
            if(i != j) {
                REP(C, k => {
                    if(i != k && j != k) {
                        var curCost = 0;
                        REP(C, l => curCost += D[l, i] * cnt[0, l]);
                        REP(C, l => curCost += D[l, j] * cnt[1, l]);
                        REP(C, l => curCost += D[l, k] * cnt[2, l]);
                        ans = Min(ans, curCost);
                    }
                });
            }
        }));
        io.o(ans);
    }
