class P
{
  static void Main()
  {
    int[] NC = Console.ReadLine().Split().Select(int.Parse).ToArray();
    List<int[]> X = new List<int[]>();
    for(int i = 0; i < NC[1]; i++){
      X.Add(Console.ReadLine().Split().Select(int.Parse).ToArray());
    }
    List<int[]> Y = new List<int[]>();
    for(int i = 0; i < NC[0]; i++){
      Y.Add(Console.ReadLine().Split().Select(int.Parse).ToArray());
    }
    List<int[]> Z = new List<int[]>();
    for(int i = 0; i < 3; i++){
      Z.Add(new int[NC[1]]);
    }
    for(int i = 0; i < NC[0]; i++){
      for(int j = 0; j < NC[0]; j++){
        Z[(i+j)%3][Y[i][j]-1] += 1;
      }
    }
    int R = 2000000000;
    for(int i = 0; i < NC[1]; i++){
      int tr = 0;
      for(int l = 0; l < NC[1]; l++){
        tr += Z[0][l]*X[l][i];
      }
      for(int j = 0; j < NC[1]; j++){
        if (i==j){continue;}
        int tr2 = 0;
        for(int l = 0; l < NC[1]; l++){
          tr2 += Z[1][l]*X[l][j];
        }
        for(int k = 0; k < NC[1]; k++){
          if (i==k ^ j==k){continue;}
          int tr3 = 0;
          for(int l = 0; l < NC[1]; l++){
            tr3 += Z[2][l]*X[l][k];
          }
          R = Min(R, tr+tr2+tr3);
//          Console.WriteLine("{0} {1} {2} {3}", i, j, k, tr+tr2+tr3);
        }
      }
    }
    Console.WriteLine(R);
  }
}

