public class Program
{

    public void Proc()
    {
        int[] inpt = Reader.ReadLine().Split(' ').Select(a => int.Parse(a)).ToArray();
        this.Length = inpt[0];
        this.ColorCount = inpt[1];

        this.Ieakan = new int[this.ColorCount, this.ColorCount];
        for (int i = 0; i < this.ColorCount; i++) {
            inpt = Reader.ReadLine().Split(' ').Select(a => int.Parse(a)).ToArray();
            for (int j = 0; j < this.ColorCount; j++) {
                this.Ieakan[i, j] = inpt[j];
            }
        }

        for (int i = 0; i < 3; i++) {
            this.color[i] = new int[ColorCount];
        }
        for (int i = 0; i < this.Length; i++) {
            inpt = Reader.ReadLine().Split(' ').Select(a => int.Parse(a)).ToArray();
            for (int j = 0; j < this.Length; j++) {
                int pos = (i + j) % 3;
                int col = inpt[j] - 1;
                this.color[pos][col]++;
            }
        }

        int ans = int.MaxValue;
        for (int i = 0; i < ColorCount; i++) {
            for (int j = 0; j < ColorCount; j++) {
                for (int k = 0; k < ColorCount; k++) {
                    if(i==j||j==k||k==i) {
                        continue;
                    }
                    int subTotal = ColorChange(0, i);
                    subTotal += ColorChange(1, j);
                    subTotal += ColorChange(2, k);
                    ans = Math.Min(ans, subTotal);
                }
            }
        }
        Console.WriteLine(ans);
    }

    private Dictionary<int, Dictionary<int, int>> dic = new Dictionary<int, Dictionary<int, int>>();
    private int ColorChange(int idx, int toC) {
        if(!dic.ContainsKey(idx)) {
            dic.Add(idx, new Dictionary<int, int>());
        }        
        if(dic[idx].ContainsKey(toC)) {
            return dic[idx][toC];
        }

        int subTotal = 0;
        for (int i = 0; i < this.color[idx].Length; i++) {
            int fromC = i;
            int count = color[idx][fromC];
            subTotal += (this.Ieakan[fromC,toC] * count);
        }
        dic[idx][toC] = subTotal;
        return subTotal;
    }

