class Program
{
    static void Main()
    {



        int[] nc = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToArray();
        int N = nc[0];
        int C = nc[1];

        int[,] D = new int[C, C];
        {
            for (int i = 0; i < C; i++)
            {
                int[] data = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToArray();

                for (int j = 0; j < C; j++)
                {
                    D[i, j] = data[j];
                }

            }
        }

        int[,] c = new int[N, N];
        {
            for (int i = 0; i < N; i++)
            {
                int[] data = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToArray();

                for(int j = 0; j < N; j++)
                {
                    c[i, j] = data[j] - 1;
                }
            }
        }

        //(i+j)%3がkであるマスを色cに変えたときの違和感の増分をX[k,c]とする。
        int[,] X = new int[3, C];
        for (int k = 0; k < 3; k++)
        {
            for (int cc = 0; cc < C; cc++)
            {
                int x = 0;

                for (int i = 0; i < N; i++)
                {
                    for (int j = 0; j < N; j++)
                    {
                        if ((i + j) % 3 == k)
                        {
                            x += D[c[i, j], cc];
                        }
                    }
                }
                X[k, cc] = x;
            }
        }

        int ans = int.MaxValue;

        //色の組み合わせ30*29*28の全部を試す
        for(int i = 0; i < C; i++)
        {
            for(int j = 0; j < C; j++)
            {
                if (j == i) continue;

                for(int k = 0; k < C; k++)
                {
                    if (k == j) continue;
                    if (k == i) continue;

                    ans = Math.Min(ans, X[0, i] + X[1, j] + X[2, k]);
                }
            }
        }

        Console.WriteLine(ans);
    }

    static bool isOkini(long N, long num)
    {
        if (num == 0) return false;

        long a = N % num;
        long b = N / num;

        if (a == b) return true;
        else return false;
    }
}


static class MathUtil
{
    public static IEnumerable<IEnumerable<int>> GetPermutation(int n)
    {
        if (n == 0)
        {
            yield return Single(0);
            yield break;
        }

        for (int i = 0; i <= n; i++)
        {
            foreach (var x in GetPermutation(n - 1))
            {
                yield return Single(i).Concat(x.Select(itm => itm < i ? itm : itm + 1));
            }
        }
    }

    private static IEnumerable<int> Single(int x)
    {
        yield return x;
    }

    public static IEnumerable<int> EnumeratePrimeNumbers()
    {
        List<int> primes = new List<int>() { 2 };
        yield return 2;

        for (int i = 3; i < int.MaxValue; i++)
        {
            bool isPrime = true;
            int Sqrt = (int)Math.Sqrt(i) + 1;

            foreach (var prime in primes)
            {
                if (prime > Sqrt)
                {
                    break;
                }
                if (i % prime == 0)
                {
                    isPrime = false;
                    break;
                }
            }

            if (isPrime)
            {
                primes.Add(i);
                yield return i;
            }
        }
    }
}

