class Program
{
    static void Main(string[] args)
    {
        var N = sc.ReadInt();
        var C = sc.ReadInt();
        var D = new long[C, C];
        for (int i = 0; i < C; i++)
        {
            for (int j = 0; j < C; j++)
            {
                D[i, j] = sc.ReadLong();
            }
        }
        var E = new int[N, N];
        for (int i = 0; i < N; i++)
        {
            for (int j = 0; j < N; j++)
            {
                E[i, j] = sc.ReadInt();
            }
        }

        var cost = new long[3, C];
        for (int h = 0; h < N; h++)
        {
            for (int w = 0; w < N; w++)
            {
                for (int color = 0; color < C; color++)
                {
                    // 今の色をcolorに塗り替えるコスト
                    var now = E[h, w] - 1;
                    var mod = (h + w) % 3;
                    cost[mod, color] += D[now, color];
                }
            }
        }

        var ans = long.MaxValue;
        for (int i = 0; i < C; i++)
        {
            for (int j = 0; j < C; j++)
            {
                if (i == j) continue;
                for (int k = 0; k < C; k++)
                {
                    if (i == k || j == k) continue;
                    var res = cost[0, i] + cost[1, j] + cost[2, k];
                    ans = Math.Min(ans, res);
                }
            }
        }
        Console.WriteLine(ans);
    }
    static Scanner sc = new Scanner();
}
