using System;
using CompLib.Util;

public class Program
{
    public void Solve()
    {
        var sc = new Scanner();
        int n = sc.NextInt();
        int c = sc.NextInt();

        int[][] d = new int[c][];
        for (int i = 0; i < c; i++)
        {
            d[i] = sc.IntArray();
        }

        int[][] cc = new int[n][];
        for (int i = 0; i < n; i++)
        {
            cc[i] = sc.IntArray();
        }

        // %3=i iにしたときの違和感
        int[][] dif = new int[3][];
        for (int i = 0; i < 3; i++)
        {
            dif[i] = new int[c];
        }

        for (int i = 0; i < n; i++)
        {
            for (int j = 0; j < n; j++)
            {
                int m = (i + j) % 3;
                for (int k = 0; k < c; k++)
                {
                    dif[m][k] += d[cc[i][j] - 1][k];
                }
            }
        }

        int ans = int.MaxValue;
        for (int i = 0; i < c; i++)
        {
            for (int j = 0; j < c; j++)
            {
                if(i == j) continue;
                for (int k = 0; k < c; k++)
                {
                    if(i == k || j == k) continue;
                    ans = Math.Min(ans, dif[0][i] + dif[1][j] + dif[2][k]);
                }
            }
        }

        Console.WriteLine(ans);
    }

    public static void Main(string[] args) => new Program().Solve();
}

