    class Program
    {
        static int[][] D;
        static int[][] map;
        static int N;
        static int[,] dist;
        static int C;
        static void Main(string[] args)
        {
            var NC = Console.ReadLine().Split(' ').Select(x => int.Parse(x)).ToArray();
            N = NC[0];
            C = NC[1];

            D = new int[C][];
            for (int i = 0; i < C; i++)
            {
                D[i] = Console.ReadLine().Split(' ').Select(x => int.Parse(x)).ToArray();
            }

            map = new int[N][];
            for (int i = 0; i < N; i++)
            {
                map[i] = Console.ReadLine().Split(' ').Select(x => int.Parse(x)).ToArray();
            }
            dist = new int[3,C+1];
            for (int i = 1; i <= N; i++)
            {
                for (int j = 1; j <= N; j++)
                {
                    if ((i + j) % 3 == 0)
                    {
                        dist[0, map[i - 1][j - 1]]++;
                    }
                    else if ((i + j) % 3 == 1)
                    {
                        dist[1, map[i - 1][j - 1]]++;
                    }
                    else
                    {
                        dist[2, map[i - 1][j - 1]]++;
                    }
                }
            }
            var min = long.MaxValue;

            for (int i = 1; i <= C; i++)
            {
                for (int j = 1; j <= C; j++)
                {
                    for (int k = 1; k <= C; k++)
                    {
                        if(!(i == j || j == k || i== k))
                        {
                            //3割って0余るものをi,1あまるものをj,2余るものをに変換する
                            min = Min(min, Calculation(i, j, k));
                        }
                    }
                }
            }
            Console.WriteLine(min);
        }

        static long Calculation(int a,int b,int c)
        {
            long ans = 0;
            for (int i = 0; i < 3; i++)
            {
                for (int j = 1; j <= C; j++)
                {
                    if(i == 0)
                    {
                        ans += dist[i, j] * D[j - 1][a-1];
                    }else if(i == 1)
                    {
                        ans += dist[i, j] * D[j - 1][b-1];
                    }
                    else
                    {
                        ans += dist[i, j] * D[j - 1][c-1];
                    }

                }
            }

            return ans;
        }


    }
