  for i:=0;i<n;i++ {
    c[i] = make([]int,n)
    for j:=0;j<n;j++ {
      fmt.Scan(&c[i][j])
      c[i][j]--
    }
  }
  m0 := map[int]int{}
  m1 := map[int]int{}
  m2 := map[int]int{}
  for i:=0;i<n;i++ {
    for j:=0;j<n;j++ {
      switch (i+j)%3 {
      case 0:
        m0[c[i][j]]++
      case 1:
        m1[c[i][j]]++
      case 2:
        m2[c[i][j]]++
      }
    }
  }
  d0 := Entries{}
  d1 := Entries{}
  d2 := Entries{}
  for i:=0;i<t;i++ {
    var x int
    for k,v := range m0 {
      x += d[k][i]*v
    }
    d0 = append(d0,Entry{i,x})
  }
  for i:=0;i<t;i++ {
    var x int
    for k,v := range m1 {
      x += d[k][i]*v
    }
    d1 = append(d1,Entry{i,x})
  }
  for i:=0;i<t;i++ {
    var x int
    for k,v := range m2 {
      x += d[k][i]*v
    }
    d2 = append(d2,Entry{i,x})
  }
  var m int = 2000000000
  for i:=0;i<t;i++ {
    for j:=0;j<t;j++ {
      if d1[j].key == d0[i].key { continue }
      for k:=0;k<t;k++ {
        if d2[k].key == d0[i].key || d2[k].key == d1[j].key { continue }
        if m > d0[i].val+d1[j].val+d2[k].val { m = d0[i].val+d1[j].val+d2[k].val }
      }
    }
  }
  fmt.Println(m)
}
type Entry struct {
  key int
  val int
}
type Entries []Entry
func(entries Entries) Len() int {
  return len(entries)
}
func(entries Entries) Swap(i,j int) {
  entries[i],entries[j] = entries[j],entries[i]
}
func(entries Entries) Less(i,j int) bool {
  if entries[i].val == entries[j].val {
    return entries[i].key < entries[j].key
  } else {
    return entries[i].val < entries[j].val
  }
}

