	D := make([][]int, C+1)
	for i := 1; i <= C; i++ {
		D[i] = make([]int, C+1)
		for j := 1; j <= C; j++ {
			D[i][j] = nextInt()
		}
	}
	c := make([][]int, N)
	for i := range c {
		c[i] = nextInts(N)
