			blocks[(i+1+j+1)%3][c[i][j]]++
		}
	}

	sum := func(x [3]int) int {
		res := 0
		for i := range blocks {
			for j := 1; j <= C; j++ {
				res += D[j][x[i]] * blocks[i][j]
			}
		}
