func getNextLine(scanner *bufio.Reader) string {
	var buffer string
	for {
		line, isPrefix, _ := scanner.ReadLine()
		buffer += string(line)
		if isPrefix == false {
			break
		}
	}
	return buffer
}

func getIntList(scanner *bufio.Reader) []int {
	list := strings.Split(getNextLine(scanner), " ")
	l := len(list)
	result := make([]int, l)
	for i := 0; i < l; i++ {
		result[i], _ = strconv.Atoi(list[i])
	}
	return result
}

func main() {
	fp := os.Stdin
	if len(os.Args) > 1 {
		fp, _ = os.Open(os.Args[1])
	}

	scanner := bufio.NewReader(fp)

	var n, c int
	fmt.Sscan(getNextLine(scanner), &n, &c)
	dd := make([][]int, c)
	cc := make([][]int, n)
	counts := make([][]int, 3)
	for i := 0; i < 3; i++ {
		counts[i] = make([]int, c)
	}
	for i := 0; i < c; i++ {
		dd[i] = getIntList(scanner)
	}
	for i := 0; i < n; i++ {
		cc[i] = getIntList(scanner)
		for j := 0; j < n; j++ {
			cc[i][j]--
			counts[(i+j)%3][cc[i][j]]++
		}
	}
	min := -1
	for i := 0; i < c; i++ {
		for ii := 0; ii < c; ii++ {
			if i == ii {
				continue
			}
			for iii := 0; iii < c; iii++ {
				if i == iii || ii == iii {
					continue
				}
				ds := 0
				for ci := 0; ci < c; ci++ {
					ds += dd[ci][i] * counts[0][ci]
					ds += dd[ci][ii] * counts[1][ci]
					ds += dd[ci][iii] * counts[2][ci]
				}
				if min == -1 || min > ds {
					min = ds
				}
			}
		}
	}

	fmt.Println(min)
}

