import * as fs from 'fs';

export class Reader {
    lines: string[];
    currentLine: number;

    constructor() {
        this.lines = fs.readFileSync("/dev/stdin", "utf8").trim().split("\n");
        this.currentLine = 0;
    }

    readLine(): string {
        return this.lines[this.currentLine++];
    }

	readChars(): string[] {
		let S = this.readLine();
		return new Array(S.length).fill(null).map((_, i) => S.charAt(i));
	}

    readInt(): number {
        return Number(this.readLine());
    }

    readInts(): number[] {
        return this.readLine().split(" ").map(Number);
    }
} 

function solve() {
	let reader = new Reader();
	let [N, C] = reader.readInts();
	let colourCount: number[][] = new Array(3).fill(null).map(() => new Array(C).fill(0));
	let D: number[][] = [];

	for(let i=0; i<C; i++) {
		D.push(reader.readInts());
	}

	if (N==1) {
		console.log(0);
		return;
	}

	for(let i=0; i<N; i++) {
		let row = reader.readInts().map((c) => c-1);
		for(let j=0; j<N; j++) {
			colourCount[(i+1+j+1)%3][row[j]] += 1;
		}
	}

	let colourCost: number[][] = new Array(3).fill(null).map(() => new Array(C).fill(0));
	for(let i=0; i<3; i++) {
		for(let targetColour=0; targetColour<C; targetColour++) {
			for(let colour=0; colour<C; colour++) {
				colourCost[i][targetColour] += colourCount[i][colour]*D[colour][targetColour];
			}
		}
	}

	let G: number[][][] = new Array(3).fill(null);
	for(let i=0; i<3; i++) {
		let costAndColours = colourCost[i].map((value, index) => [value, index]).sort((a, b) => a[0]-b[0]).slice(0, 3);
		G[i] = costAndColours;
	}

	let minimumCost = Number.POSITIVE_INFINITY;

	for(let i=0; i<3; i++) {
		for(let j=0; j<3; j++) {
			for(let k=0; k<3; k++) {
				if (G[0][i][1] != G[1][j][1] &&
					G[1][j][1] != G[2][k][1] &&
					G[0][i][1] != G[2][k][1]) {
					minimumCost = Math.min(minimumCost, G[0][i][0]+G[1][j][0]+G[2][k][0]);
				}
			}
		}
	}

	console.log(minimumCost);
}

