auto parse( Range )( Range input )
if( isInputRange!Range && is( ElementType!Range == string ) )
{
	auto nc = input.front.split.to!( long[] );
	auto dss = new long[][]( nc[ 1 ], nc[ 1 ] );
	foreach( ref ds; dss )
	{
		input.popFront;
		ds = input.front.split.to!( long[] );
	}
	auto css = new long[][]( nc[ 0 ], nc[ 0 ] );
	foreach( ref cs; css )
	{
		input.popFront;
		cs = input.front.split.to!( long[] );
		cs[] -= 1;
	}
	return tuple( nc[ 1 ], dss, css );
}

auto solve( long cn, long[][] dss, long[][] css )
{
	// 各色・各マスごとの、塗り替えた後の違和感の合計を集計
	auto kss = new long[][]( 3, cn );
	foreach( y, cs; css )
	{
		foreach( x, c; cs )
		{
			foreach( t; 0L .. cn )
			{
				kss[ ( x + y ) % 3 ][ t ] += dss[ c ][ t ];
			}
		}
	}

	// 違和感の少ない順に色を並べ替え
	auto sss = new Tuple!( long, long )[][]( 3, cn );
	foreach( i, ks; kss )
	{
		auto ss = zip( ks, iota( 0L, cn ) ).array;
		ss.sort();
		sss[ i ] = ss.take( 3 );
	}

	// 違和感の少ない順に3色使ったときの最小値を検索
	auto ans = long.max;
	foreach( s1; sss[ 0 ] )
	{
		foreach( s2; sss[ 1 ] )
		{
			if( s1[ 1 ] == s2[ 1 ] ) continue;
			foreach( s3; sss[ 2 ] )
			{
				if( s1[ 1 ] == s3[ 1 ] || s2[ 1 ] == s3[ 1 ] ) continue;
				ans = min( ans, s1[ 0 ] + s2[ 0 ] + s3[ 0 ] );
			}
		}
	}
	return ans;
}

