proc solve =
  # cnt[i][j]: (x + y) mod 3 == i なるマスを全てある色に変えるときの違和感の和であって j 番目に少ないもの
  # rank[i][j]: cnt[i][j] の更新の時に変えた色
  var cnt = newseq2[int](3, 4)
  var rank = newseq2[int](3, 4)
  for i in 0..2:
    for j in 1..3:
      cnt[i][j] = 0x3f3f3f3f
      rank[i][j] = 0x3f3f3f3f
  for c in 1..C:
