      if sum[k] < cnt[k][3]:
        cnt[k][3] = sum[k]
        rank[k][3] = c
      if cnt[k][2] > cnt[k][3]:
        swap(cnt[k][2], cnt[k][3])
        swap(rank[k][2], rank[k][3])
      if cnt[k][1] > cnt[k][2]:
        swap(cnt[k][1], cnt[k][2])
        swap(rank[k][1], rank[k][2])
  var res = 0x3f3f3f3f3f3f3f3f
  for i in 1..3:
    for j in 1..3:
      for k in 1..3:
        if rank[0][i] != rank[1][j] and rank[1][j] != rank[2][k] and rank[2][k] != rank[0][i]:
