  for i in 0..<n:
    cs[i] = readSeq().map(parseInt).map(it => it - 1)

  debug ds
  debug cs

  var cnt = newSeq2[int](3, c)
  for y in 0..<n:
    for x in 0..<n:
      cnt[(y + x) mod 3][cs[y][x]] += 1

  var ans = INF
  for c0 in 0..<c:
    for c1 in 0..<c:
      for c2 in 0..<c:
        if c0 == c1 or c1 == c2 or c2 == c0:
          continue
        var sum = 0
        sum += eval(ds, cnt[0], c0)
        sum += eval(ds, cnt[1], c1)
        sum += eval(ds, cnt[2], c2)
        ans = min(ans, sum)

  echo ans

main()

