import sys
import itertools 

def solve(N: int, C: int, D: "List[List[int]]", c: "List[List[int]]"):
    c_list = list(itertools.permutations(range(C),3))
    answer = 10**9
    for zero,one,two in c_list:
        a = 0
        for i in range(N):
            for j  in range(N):
                color = c[i][j]
                if (i+j) % 3 == 0:
                    a+= D[color-1][zero]
                elif (i+j) % 3 == 1:
                    a+= D[color-1][one]
                elif (i+j) % 3 == 2:
                    a+= D[color-1][two]
        answer = min(answer,a)

    print(answer)
    return


