def main():
    if len(sys.argv) > 1:
        f = open(sys.argv[1])
    else:
        f = None
    read_func = get_read_func(f);
    input_raw = read_func().strip().split()
    [N, C] = [long(input_raw[0]), long(input_raw[1])]
    grid = []
    D = []

    for i in range(C):
        input_raw = read_func().strip().split()
        row = [long(input_raw[i]) for i in range(len(input_raw))]
        D.append(row)

    for i in range(N):
        input_raw = read_func().strip().split()
        row = [long(input_raw[i]) for i in range(len(input_raw))]
        grid.append(row)

    grid_color_dic = {}
    for i in range(3):
        grid_color_dic[i] = [0 for j in range(C)]

    for i in range(N):
        for j in range(N):
            grid_color_dic[(i + j) % 3][grid[i][j] - 1] += 1

    score = [[0 for i in range(C)] for j in range(3)]
    for g in range(3):
        for now_color in range(len(grid_color_dic[g])):
            for next_color in range(C):
                #if grid_color_dic[g][now_color] > 0:
                score[g][next_color] += D[now_color][next_color] * grid_color_dic[g][now_color]



    order = [[0,1,2],[0,2,1],[1,0,2],[1,2,0],[2,0,1],[2,1,0]]
    s_min = sys.maxint
    for o in order:
        min_score=[sys.maxint for i in range(3)]
        arg_min_score =[0 for i in range(3)]
        for g in o:
            for color in range(C):
                if min_score[g] > score[g][color] and color != arg_min_score[(g + 1) % 3] and color != arg_min_score[(g - 1) % 3]:
                    min_score[g] = score[g][color]
                    arg_min_score[g] = color

        s = 0
        for i in range(len(min_score)):
            s += min_score[i]
        if s < s_min:
            s_min = s

    print s_min

