def read_values():
    return map(int, input().split())


def read_list():
    return list(read_values())


def f(C, D, F, r):
    import collections

    L = []
    for i, f0 in enumerate(F):
        for j, c in enumerate(f0):
            if (i + j) % 3 != r:
                continue
            L.append(c - 1)
    d = collections.Counter(L)
    res = []
    for x in range(C):
        tmp = 0
        for y, v in d.items():
            tmp += D[y][x] * v

        res.append((x, tmp))

    res.sort(key=lambda l: l[1])
    return res[:3]


