INF=10**20
def solve(N: int, C: int, D: "List[List[int]]", c: "List[List[int]]"):

    colormap = [[] for _ in range(3)]
    for i in range(1,N+1):
        for j in range(1,N+1):
            k = i+j
            k %= 3
            colormap[k].append(c[i-1][j-1])

    ans = INF
    for _colors in itertools.permutations(list(range(1,C+1)),3):
        colors = list(_colors)
        res = 0
        for mod,current_colors in enumerate(colormap):
            for current in current_colors:
                color = colors[mod]
                res += D[current-1][color-1]

        ans = min(res,ans)


    print(ans)

    return

def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    N = int(next(tokens))  # type: int
    C = int(next(tokens))  # type: int
    D = [[int(next(tokens)) for _ in range(C)] for _ in range(C)]  # type: "List[List[int]]"
    c = [[int(next(tokens)) for _ in range(N)] for _ in range(N)]  # type: "List[List[int]]"
    solve(N, C, D, c)



