        for j in range(c):
            for k in range(c):
                q=[i,j,k]
                if len(set(q))<3: continue
                chk=0
                for p in range(n**2):
                    h,w=p//n,p%n
                    x=(h+w+2)%3
                    chk+=d[t[h][w]-1][q[x]]
                if ans==-1: ans=chk
                ans=min(ans,chk)

    print(ans)

