import sys

def calc(order, groups, D):
    ret = 0
    for i, G in enumerate(groups):
        target = order[i]
        for elm in G:
            #print(elm, target)
            ret += D[elm - 1][target]
    return ret

def dfs(idx, current, used, groups, D):
    if idx == 3:
        ret = calc(current, groups, D)
        return ret
    ret = float('inf')
    for i, u in enumerate(used):
        if not u:
            used[i] = True
            tmp = dfs(idx + 1, current + [i], used, groups, D)
            ret = min(ret, tmp)
            used[i] = False
    return ret

def solve(N: int, C: int, D: "List[List[int]]", c: "List[List[int]]"):
    groups = [[] for _ in range(3)]
    for i in range(N):
        for j in range(N):
            cc = c[i][j]
            groups[(i + j) % 3].append(cc)
    #print(groups)
    ret = dfs(0, [], [False] * C, groups, D)
    print(ret)
    return


def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    N = int(next(tokens))  # type: int
