def run(N, C, D, c):
    '''
    マス番号に応じて3色に塗る必要がある
    (i+j)%3が0, 1, 2それぞれに対して、ある色に塗るコストを計算する
    0, 1, 2それぞれのC色のコストのパターンができる
    上記コストに対してC色から3色を選択する全パターンのうち最小のコストを求める
    '''
    cost0 = {}
    cost1 = {}
    cost2 = {}
    for k in range(C):
        cost0[k] = 0
        cost1[k] = 0
        cost2[k] = 0
        for i in range(N):
            for j in range(N):
                if (i+j+2) % 3 == 0:
                    color = c[i][j] - 1
                    cost = D[color][k]
                    cost0[k] += cost
                elif (i+j+2) % 3 == 1:
                    color = c[i][j] - 1
                    cost = D[color][k]
                    cost1[k] += cost
                elif (i+j+2) % 3 == 2:
                    color = c[i][j] - 1
                    cost = D[color][k]
                    cost2[k] += cost
    ret = max(cost0.values()) + max(cost1.values()) + max(cost2.values())
    for i in range(C):
        for j in range(C):
            for k in range(C):
                if i == j or j == k or k == i:
                    continue
                else:
                    ret = min(ret, cost0[i]+cost1[j]+cost2[k])
    return ret


