    for j, t in enumerate(T):
        for i in range(CN):
            s = 0
            for c in t:
                s += D[c[2] - 1][i - 1]
            TC[j].append(s)

    ans = sys.maxsize
    for i, j, k in permutations(range(CN), 3):
        ans = min(ans, sum([TC[0][i], TC[1][j], TC[2][k]]))

    return ans


