def input():
    return sys.stdin.readline().strip()


def main():
    N, C = map(int, input().split())
    D = [[0] * (C + 1)]
    for _ in range(C):
        d = [0] + list(map(int, input().split()))
        D.append(d)

    grid = [[0] * (N + 1)]
    for _ in range(N):
        g = [0] + list(map(int, input().split()))
        grid.append(g)

    perm = permutations(range(1, C + 1), 3)
    ans = INF
    for c0, c1, c2 in perm:
        tmp = 0
        for i in range(1, N + 1):
            for j in range(1, N + 1):
                if (i + j) % 3 == 0:
                    tmp += D[grid[i][j]][c0]
                elif (i + j) % 3 == 1:
                    tmp += D[grid[i][j]][c1]
                elif (i + j) % 3 == 2:
                    tmp += D[grid[i][j]][c2]

        if tmp < ans:
            ans = tmp

    print(ans)


