use proconio::input;
use proconio::marker::Usize1;
use std::cmp;
use std::collections::HashMap;

fn main() {
    input! {
        n: usize,
        c: usize,
        costs: [[usize; c]; c],
        grid: [[Usize1; n]; n],
    }

    // group iには何色が何個あるか
    let mut data = vec![HashMap::new(); 3];
    for i in 0..n {
        for j in 0..n {
            let index = ((i + 1) + (j + 1)) % 3;
            let entry = data[index].entry(grid[i][j]).or_insert(0);
            *entry += 1;
        }
    }

    let mut min = std::usize::MAX;
    // group 1 -> color i
    // group 2 -> color j
    // group 3 -> color k
    for i in 0..c {
        for j in 0..c {
            for k in 0..c {
                if i == j || j == k || k == i {
                    continue;
                }
                let mut tmp = 0;
                for (key, value) in &data[0] {
                    tmp += costs[*key][i] * value;
                }
                for (key, value) in &data[1] {
                    tmp += costs[*key][j] * value;
                }
                for (key, value) in &data[2] {
                    tmp += costs[*key][k] * value;
                }
                min = cmp::min(min, tmp);
            }
        }
    }
    println!("{}", min);
}

