#[allow(dead_code)]
fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("Failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("Failed to parse token")
}

#[allow(dead_code)]
fn with_bufwriter<F: FnOnce(BufWriter<StdoutLock>) -> ()>(f: F) {
    let out = stdout();
    let writer = BufWriter::new(out.lock());
    f(writer);
}

fn main() {
    let (n, c) = get!(usize, usize);
    let d = (0..c)
        .map(|_i| (0..c).map(|_j| read::<u32>()).collect::<Vec<_>>())
        .collect::<Vec<_>>();
    let mut t = vec![vec![0; c]; 3];
    for i in 0..n {
        for j in 0..n {
            let x = read::<usize>();
            t[(i + j) % 3][x - 1] += 1;
        }
    }

    let mut res = <u32>::max_value();
    for i in 0..c {
        for j in 0..c {
            if i == j {
                continue;
            }
            for k in 0..c {
                if j == k || k == i {
                    continue;
                }

                let mut tt = 0;
                for l in 0..c {
                    tt += d[l][i] * t[0][l];
                    tt += d[l][j] * t[1][l];
                    tt += d[l][k] * t[2][l];
                }

                if tt < res {
                    res = tt
                }
            }
        }
    }

    with_bufwriter(|mut out| writeln!(out, "{}", res).unwrap());
}

