      eprint!("[{}:{}] ", file!(), line!());
      eprintln!(concat!($(stringify!($x), "={:?}; "),+), $($x),+);
    };
  }

  macro_rules! nested_vec {
    ($e:expr; $n:expr) => {
      vec![$e; $n]
    };
    ($e:expr; $n:expr $(; $m:expr)+) => {
      vec![nested_vec!($e $(; $m)+); $n]
    };
  }

  use math::OrdAssign;

  let (n, c) = scan!(usize, usize);
  let d = scan!(u64; c; c);
  let g = scan!(u64; n; n);

  let mut d_sum = nested_vec![0; 3; c];
  for y in 0..n {
    for x in 0..n {
      for color in 0..c {
        d_sum[(y + 1 + x + 1) % 3][color] += d[(g[y][x] - 1) as usize][color];
      }
    }
  }

  let mut min = u64::max_value();
