                for i in 0..n {
                    for k in 0..n {
                        //                        debug!(c0, c1, c2, i, k);
                        let ii = i + 1;
                        let kk = k + 1;
                        match (ii + kk) % 3 {
                            0 => g0_diff += d[color[i][k] - 1][c0],
                            1 => g1_diff += d[color[i][k] - 1][c1],
                            2 => g2_diff += d[color[i][k] - 1][c2],
                            _ => (),
                        };
                    }
                }
                min_diff = min(min_diff, g0_diff + g1_diff + g2_diff);
            }
        }
    }

    println!("{}", min_diff);
}

