      writeln!(_writer, $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      writeln!(_writer, $fmt, $($arg)*).unwrap()
    };
  }

  let (grid_len, color_len) = scan!(usize, usize);
  let d = scan!(u32; color_len * color_len);
  let grid = scan!(u32; grid_len * grid_len);

  let d_index = |i: usize, j: usize| d[i * color_len + j];
  let grid_index = |i: usize, j: usize| grid[i * grid_len + j];

  // cnt[a][b] := mod 3 で a と合同なマスをすべて b で塗り替えたときの違和感の総和
  let mut cnt = vec![vec![0; color_len]; 3];
  for i in 0..grid_len {
    for j in 0..grid_len {
      for color in 0..color_len {
        cnt[(i + j + 2) % 3][color] += d_index(grid_index(i, j) as usize - 1, color);
      }
    }
  }

  let mut min = u32::max_value();
  for x in 0..color_len {
    for y in 0..color_len {
      for z in 0..color_len {
        if x == y || y == z || z == x {
          continue;
        }
        let sum = cnt[0][x] + cnt[1][y] + cnt[2][z];
        min = ::std::cmp::min(min, sum);
      }
    }
  }

  println!("{}", min);
}

