pub fn main() {
    let w = rw::<usize>();
    let (N, C) = (w[0], w[1]);
    let mut D = vec![vec![0; C]; C];
    let mut c = vec![vec![0; N]; N];

    for X in 0..C {
        D[X] = rw::<i64>();
    }

    for y in 0..N {
        c[y] = rw::<usize>();
    }

    // (r, Y) -> sum D_*,Y
    let mut sumd = HashMap::<(usize, usize), i64>::new();

    for r in 0..3 {
        for Y in 0..C {
            let mut d = 0;

            for y in 0..N {
                for x in 0..N {
                    if ((1 + x) + (1 + y)) % 3 != r {
                        continue;
                    }

                    let X = c[y][x] - 1;
                    d += D[X][Y];
                }
            }

            sumd.insert((r, Y), d);
        }
    }
    debug!(sumd);

    let mut min_d = std::i64::MAX;
    for y1 in 0..C {
        for y2 in 0..C {
            if y1 == y2 {
                continue;
            }
            for y3 in 0..C {
                if y3 == y1 || y3 == y2 {
                    continue;
                }

                let d = sumd[&(0, y1)] + sumd[&(1, y2)] + sumd[&(2, y3)];
                min_d = min(min_d, d);
            }
        }
    }

    println!("{}", min_d);
    return;
}

