use std::fs;
use std::io::{stdin, Read};

macro_rules! parse {
    ($it: ident) => {
        $it.next().unwrap().parse().unwrap()
    };
    ($it: ident,2) => {
        (parse!($it), parse!($it))
    };
    ($it: ident,3) => {
        (parse!($it), parse!($it), parse!($it))
    };
    ($it: ident,4) => {
        (parse!($it), parse!($it), parse!($it), parse!($it))
    };
    ($it: ident, $n: expr) => {
        (&mut $it).take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let (n, nc): (usize, usize) = parse!(it, 2);
    let d: Vec<Vec<usize>> = (0..nc).map(|x| parse!(it, nc)).collect();
    let c: Vec<Vec<usize>> = (0..n).map(|x| parse!(it, n)).collect();
    let mut g = vec![vec![]; 3];
    for i in 0..n {
        for j in 0..n {
            g[(i + j) % 3].push((i, j));
        }
    }
    let mut memo = std::collections::HashMap::new();
    let mut gd = |gi: usize, ci: usize| {
        if let Some(x) = memo.get(&(gi, ci)) {
            return *x;
        }
        let mut ret = 0;
        for &(x, y) in &g[gi] {
            ret += d[c[x][y] - 1][ci];
        }
        memo.insert((gi, ci), ret);
        ret
    };
    let mut ret = std::usize::MAX;
    for c0 in 1..(nc + 1) {
        for c1 in 1..(nc + 1) {
            if c0 == c1 {
                continue;
            }
            for c2 in 1..(nc + 1) {
                if c0 == c2 || c1 == c2 {
                    continue;
                }
                let mut pret = 0;
                let ci = vec![c0, c1, c2];
                for i in 0..3 {
                    pret += gd(i, ci[i] - 1)
                }
                ret = std::cmp::min(ret, pret);
            }
        }
    }
    println!("{:?}", ret); // DEBUG
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    solve(&s);
}

