fn solve(costs:Vec<Vec<i64>>)->i64{
    let c = costs[0].len();
    let mut min_val = 999999999999;

    for c1 in 0..c{
        for c2 in 0..c{
            if c1 == c2{
                continue;
            }

            for c3 in 0..c{
                if c1 == c3 || c2 == c3{
                    continue;
                }

                min_val = cmp::min(
                    min_val,
                    costs[0][c1] + costs[1][c2] + costs[2][c3]
                );

            }
        }
    }

    min_val

}

