#[proconio::fastout]
fn main() {
	input! {
		n: usize,
		cnum: usize,
		d: [[usize; cnum]; cnum],
		c: [[Usize1; n]; n],
	}

	let inf = 99999999999999usize;

	// 各マスを、(i+j)%3 = 0 or 1 or 2 の3つのグループに分割する。 
	// 各グループについて、C通りの色を塗りつぶしたときの違和感の和を前処理しておき, 
	// C^3通りの組み合わせを検証して最小値を出力する

	// 前処理
	let mut cost = vec![vec![0usize; cnum]; 3];
	for color in 0..cnum {
		for i in 0..n {
			for j in 0..n {
				cost[(i+j)%3][color] += d[c[i][j]][color];
			}
		}
	}

	// 解を求める
	let mut ans = inf;
	for c0 in 0..cnum {
		for c1 in 0..cnum {
			if c0 == c1 {
				continue;
			}
			for c2 in 0..cnum {
				if c2 == c0 || c2 == c1 {
					continue;
				}
				let mut tmp = 0usize;
				tmp += cost[0][c0];
				tmp += cost[1][c1];
				tmp += cost[2][c2];
				ans = min(ans, tmp);
			}
		}
	}

	println!("{}", ans);
}

