    for line in stdin.lock().lines().take(c).map(|x| x.unwrap()) {
        let x = line.split(' ').map(|x| x.parse().unwrap())
            .collect::<Vec<u32>>();
        diff.push(x);
    }
    let mut color = Vec::new();
    for line in stdin.lock().lines().take(n).map(|x| x.unwrap()) {
        let x = line.split(' ').map(|x| x.parse().unwrap())
            .collect::<Vec<usize>>();
        color.push(x);
    }

    // Total iwakan when line `(x + y) % 3` is repainted in color `new_c`.
    let mut iwasum = vec![vec![0; c]; 3];
    for y in 0..n {
        for x in 0..n {
            for new_c in 0..c {
                let old_c = color[y][x] - 1;
                iwasum[(x + y) % 3][new_c] += diff[old_c][new_c];
            }
        }
    }
    let mut ans = std::u32::MAX;
    for c0 in 0..c {
        for c1 in (0..c).filter(|&x| x != c0) {
            for c2 in (0..c).filter(|&x| x != c0 && x != c1) {
                ans = std::cmp::min(
                    ans, iwasum[0][c0] + iwasum[1][c1] + iwasum[2][c2]);
            }
        }
    }
