                if c0 == c1 || c1 == c2 || c0 == c2 {
                    continue;
                }
                let ccv = [c0, c1, c2];
                let mut cost = 0;
                for (i, cr) in cov.iter().enumerate() {
                    for (&ce, dr) in cr.iter().zip(d.iter()) {
                        unsafe {
                            cost += ce * dr.get_unchecked(ccv[i]);
                        }
                    }
                }
                ans = min(ans, cost);
            }
        }
    }
    printfln!("{}", ans);
}

