fn run<R: BufRead, W: Write>(i: R, o: &mut W) {
    let mut i = AtRead::from(i);
    let (n, c) = i.read2::<usize, usize>();
    let mut d = Vec::new();
    for _ in 0..c {
        d.push(i.read_vec::<usize>(c));
    }
    let mut x = Vec::new();
    for _ in 0..n {
        let mut xi = i.read_vec::<usize>(n);
        for xii in xi.iter_mut() {
            *xii -= 1;
        }
        x.push(xi);
    }
    writeln!(o, "{}", solve(&d, &x)).unwrap();
}
fn solve(d: &[Vec<usize>], c: &[Vec<usize>]) -> usize {
    let mut d_sums = vec![vec![0; d.len()]; 3];
    for ci in 0..d.len() {
        for x in 0..c.len() {
            for y in 0..c.len() {
                d_sums[(x + y) % 3][ci] += d[c[x][y]][ci];
            }
        }
    }
    let mut result = usize::max_value();
    for i0 in 0..d.len() {
        for i1 in 0..d.len() {
            if i1 == i0 {
                continue;
            }
            for i2 in 0..d.len() {
                if i2 == i0 || i2 == i1 {
                    continue;
                }
                result = min(result, d_sums[0][i0] + d_sums[1][i1] + d_sums[2][i2]);
            }
        }
    }
    result
}

