use std::io;
use std::str::FromStr;
use std::collections::HashMap;
use std::cmp::min;

type Pair = (u64, u64);

fn input_tuple() -> (usize, usize) {
    let mut line: String = String::new();
    io::stdin().read_line(&mut line);
    let vec: Vec<usize> = line.split_whitespace().map(|s| s.parse().unwrap()).collect();
    (vec[0], vec[1])
}

fn input_vec() -> Vec<u64> {
    let mut line: String = String::new();
    io::stdin().read_line(&mut line);
    line.split_whitespace().map(|s| s.parse().unwrap()).collect()
}

fn calc(c: u64, map: &HashMap<u64, u64>, diff: &Vec<Vec<u64>>) -> u64 {
    let mut sum = 0;
    for (k, v) in map {
        if *k - 1 == c {
            continue;
        }
        sum += diff[*k as usize - 1][c as usize] * v;
    }
    sum
}

fn main() {
    let (n, c) = input_tuple();
    let mut diff: Vec<Vec<u64>> = Vec::new();
    let mut colors: Vec<Vec<u64>> = Vec::new();
    let mut elements: Vec<HashMap<u64, u64>> = vec![HashMap::new(); 3];

    for _ in 0..c {
        let d = input_vec();
        diff.push(d);
    }
    for _ in 0..n {
        let c = input_vec();
        colors.push(c);
    }
    for i in 0..n {
        for j in 0..n {
            let n = elements[(i+j) as usize % 3].entry(colors[i][j]).or_insert(0);
            *n += 1;
        }
    }
    let mut ans = std::u64::MAX;
    for i in 0..c {
        for j in 0..c {
            for k in 0..c {
                if i == j || j == k || k == i {
                    continue;
                }
                let tmp = calc(i as u64, &elements[0], &diff)
                    + calc(j as u64, &elements[1], &diff)
                    + calc(k as u64, &elements[2], &diff);
                ans = min(ans, tmp);
                // println!("({}, {}, {}) -> {}", i, j, k, tmp);
            }
        }
    }
    // println!("{:?}", elements);
    println!("{}", ans);
}

