    let mut data = vec![HashMap::new(); 3];
    for i in 0..n {
        for j in 0..n {
            let index = ((i + 1) + (j + 1)) % 3;
            let entry = data[index].entry(grid[i][j]).or_insert(0);
            *entry += 1;
        }
    }

    let mut min = usize::MAX;
    // group 1 -> color i
    // group 2 -> color j
