                for (key, value) in &data[1] {
                    tmp += costs[*key][j] * value;
                }
                for (key, value) in &data[2] {
                    tmp += costs[*key][k] * value;
                }
                min = cmp::min(min, tmp);
            }
        }
    }
    println!("{}", min);
