fn main() {
    input! {
        n: usize,
        c: usize,
        d: [[usize; c]; c],
        col: [[usize1; n]; n],
    }

    let mut cost = vec![vec![0; c]; 3];

    for i in 0..c {
        let mut csum = vec![0; 3];
        for j in 0..n {
            for k in 0..n {
                csum[(j + k) % 3] += d[col[j][k]][i];
            }
        }
        for j in 0..3 {
            cost[j][i] = csum[j];
        }
    }

    let mut ans = 1 << 50;

    for i in 0..c {
        for j in 0..c {
            if i == j {
                continue;
            }
            for k in 0..c {
