fn dfs(seted: (i64,i64,i64), idx: usize, c_n: usize) -> usize{
    let (a,b,c) = seted;
    if idx == c_n {
        if a == -1 || b == -1 || c == -1{
            return std::usize::MAX / 2;
        }else{
            let cumsum = CUMSUM.lock().unwrap();
            let ans = cumsum[0][a as usize] + cumsum[1][b as usize] + cumsum[2][c as usize];
            // eprintln!("{:?}, {}", seted, ans);
            return ans;
        }
    }

    let mut not_inits = Vec::new();
    if a == -1 {
        not_inits.push(0);
    }
    if b == -1 {
        not_inits.push(1);
    }
    if c == -1 {
        not_inits.push(2);
    }

    let fill_min = not_inits.iter().map(|not_init| {
        let mut seted = seted;
        match not_init {
            0 => seted.0 = idx as i64,
             1 => seted.1 = idx as i64,
             2 => seted.2 = idx as i64,
            _ => panic!("fill_min")
        }
        dfs(seted, idx + 1, c_n)
    }).min().unwrap_or(std::usize::MAX / 2);

    return
        min!(
        dfs(seted, idx+1, c_n),
        fill_min
        );
}

