macro_rules! parse_line {
    ($($t: ty),+) => ({
        let mut a_str = String::new();
        io::stdin().read_line(&mut a_str).expect("read error");
        let mut a_iter = a_str.split_whitespace();
        (
            $(
                a_iter.next().unwrap().parse::<$t>().expect("parse error"),
            )+
        )
    })
}

fn parse_line_to_vec<T: FromStr>() -> Vec<T> {
    let mut tmp = String::new();
    io::stdin().read_line(&mut tmp).expect("read error");
    return tmp.split_whitespace().filter_map(|s| T::from_str(s.trim()).ok()).collect();
}

fn main() {
    let (N, C) = parse_line!(usize, usize);
    let mut D = Vec::<Vec<u32>>::new();
    let mut c = Vec::<Vec<u32>>::new();
    for _ in 0..C {
        D.push(parse_line_to_vec());
    }
    for _ in 0..N {
        c.push(parse_line_to_vec());
    }

    let mut color_counts = Vec::new();
    for i in 0..3 {
        color_counts.push(Vec::new());
        color_counts[i].resize(C as usize, 0);
    }
    for i in 0..N {
        for j in 0..N {
            color_counts[((i + j) % 3) as usize][c[i][j] as usize - 1] += 1;
        }
    }

    let mut min_cost = u32::max_value();
    for c0 in 0..C {
        for c1 in 0..C {
            if c0 == c1 {
                continue;
            }
            for c2 in 0..C {
                if c0 == c2 || c1 == c2 {
                    continue;
                }
                let mut cost = 0u32;
                for j in 0..C {
                    cost += color_counts[0][j] * D[j][c0];
                    cost += color_counts[1][j] * D[j][c1];
                    cost += color_counts[2][j] * D[j][c2];
                }
                min_cost = min(min_cost, cost);
            }
        }
    }
    println!("{}", min_cost);
}

