fn dfs(seted: (i64,i64,i64), idx: usize, c_n: usize) -> usize{
    let (a,b,c) = seted;
    if idx == c_n {
        if a == -1 || b == -1 || c == -1{
            return std::usize::MAX / 2;
        }else{
            let cumsum = CUMSUM.lock().unwrap();
            let ans = cumsum[0][a as usize] + cumsum[1][b as usize] + cumsum[2][c as usize];
            // eprintln!("{:?}, {}", seted, ans);
            return ans;
        }
    }

    let mut not_inits = Vec::new();
    if a == -1 {
        not_inits.push(0);
    }
    if b == -1 {
        not_inits.push(1);
    }
    if c == -1 {
        not_inits.push(2);
    }

    let fill_min = not_inits.iter().map(|not_init| {
        let mut seted = seted;
        match not_init {
            0 => seted.0 = idx as i64,
             1 => seted.1 = idx as i64,
             2 => seted.2 = idx as i64,
            _ => panic!("fill_min")
        }
        dfs(seted, idx + 1, c_n)
    }).min().unwrap();

    return
        min!(
        dfs(seted, idx+1, c_n),
        fill_min
        );
}

use std::fs;
use std::io::{stdin, Read};

macro_rules! parse {
    ($it: ident) => {
        $it.next().unwrap().parse().unwrap()
    };
    ($it: ident,2) => {
        (parse!($it), parse!($it))
    };
    ($it: ident,3) => {
        (parse!($it), parse!($it), parse!($it))
    };
    ($it: ident,4) => {
        (parse!($it), parse!($it), parse!($it), parse!($it))
    };
    ($it: ident, $n: expr) => {
        (&mut $it).take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let (n, nc): (usize, usize) = parse!(it, 2);
    let d: Vec<Vec<usize>> = (0..nc).map(|x| parse!(it, nc)).collect();
    let c: Vec<Vec<usize>> = (0..n).map(|x| parse!(it, n)).collect();
    let mut g = vec![vec![]; 3];
    for i in 0..n {
        for j in 0..n {
            g[(i + j) % 3].push((i, j));
        }
    }
    let mut ret = std::usize::MAX;
    for c0 in 1..(nc + 1) {
        for c1 in 1..(nc + 1) {
            if c0 == c1 {
                continue;
            }
            for c2 in 1..(nc + 1) {
                if c0 == c2 || c1 == c2 {
                    continue;
                }
                let mut pret = 0;
                let ci = vec![c0, c1, c2];
                for i in 0..3 {
                    for &(x, y) in &g[i] {
                        pret += d[c[x][y] - 1][ci[i] - 1];
                    }
                }
                ret = std::cmp::min(ret, pret);
            }
        }
    }
    println!("{:?}", ret); // DEBUG
}

