}

fn main() {
    let s: Vec<usize> = read_vec();
    let (N, C) = (s[0], s[1]);
    let mut D = vec![vec![0; C]; C];
    for i in 0..C {
        let s: Vec<i32> = read_vec();
        for j in 0..C {
            D[i][j] = s[j];
        }
    }
    let D = D;
    let mut c = vec![vec![0usize; N]; N];
    for i in 0..N {
        let s: Vec<usize> = read_vec();
        for j in 0..N {
            c[i][j] = s[j] - 1;
        }
    }
    let c = c;
    // println!("{:?}", D);
    // println!("{:?}", c);

    let mut groups = vec![vec![0usize; 0]; 3];
    for i in 0..N {
        for j in 0..N {
            groups[(i + j) % 3].push(c[i][j]);
        }
    }

    let groups = groups;
    let mut group_dict: Vec<std::collections::HashMap<usize, i32>> =
        vec![std::collections::HashMap::new(); 3];
    for i in 0..3 {
        for color in 0..C {
            group_dict[i].insert(color, 0);
        }
        for color in &groups[i] {
            (*group_dict[i].entry(*color).or_insert(0)) += 1;
        }
    }
    // println!("{:?}", group_dict);

    let mut cost_dict: Vec<std::collections::HashMap<usize, i32>> =
        vec![std::collections::HashMap::new(); 3];
    for i in 0..3 {
        for src_color in 0..C {
            for dst_color in 0..C {
                (*cost_dict[i].entry(dst_color).or_insert(0)) +=
                D[src_color][dst_color] * group_dict[i][&src_color];
            }
        }
    }
    // println!("{:?}", cost_dict);

    let mut ans = std::i32::MAX;
    for group_idx in 0..3 {
        for c_idx1 in 0..C {
            let cost1 = cost_dict[0][&c_idx1];
            for c_idx2 in 0..C {
                if c_idx1 == c_idx2 {
                    continue;
                }
                let cost2 = cost_dict[1][&c_idx2];
                for c_idx3 in 0..C {
                    if c_idx1 == c_idx3 || c_idx2 == c_idx3 {
                        continue;
                    }
                    let cost3 = cost_dict[2][&c_idx3];
                    ans = std::cmp::min(ans, cost1 + cost2 + cost3);
                }
            }
        }
    }
    println!("{:?}", ans);
}

#[allow(unused_imports)] use proconio::{input, marker::{Bytes, Chars, Usize1, Isize1}};
#[allow(unused_imports)] use std::cmp::{min, max};
#[allow(unused_imports)] use superslice::Ext as _;

#[proconio::fastout]
fn main() {
	input! {
		n: usize,
		cnum: usize,
		d: [[usize; cnum]; cnum],
		c: [[Usize1; n]; n],
	}

	let inf = 99999999999999usize;

	// 各マスを、(i+j)%3 = 0 or 1 or 2 の3つのグループに分割する。 
	// 各グループについて、C通りの色を塗りつぶしたときの違和感の和を前処理しておき, 
	// C^3通りの組み合わせを検証して最小値を出力する

	// 前処理
	let mut cost = vec![vec![0usize; 3]; cnum];
	for color in 0..cnum {
		for i in 0..n {
			for j in 0..n {
				cost[(i+j)%3][color] += d[c[i][j]][color];
			}
		}
	}

	// 解を求める
	let mut ans = inf;
	for c0 in 0..cnum {
		for c1 in 0..cnum {
			if c0 == c1 {
				continue;
			}
			for c2 in 0..cnum {
				if c2 == c0 || c2 == c1 {
					continue;
				}
				let mut tmp = 0usize;
				tmp += cost[0][c0];
				tmp += cost[1][c1];
				tmp += cost[2][c2];
				ans = min(ans, tmp);
			}
		}
	}

	println!("{}", ans);
}

