fn solve(src: &str) -> String {
    let mut sc = Scanner::from_str(src);

    let n: usize = sc.read();
    let cmx: usize = sc.read();

    let d: Vec<Vec<usize>> = (0..cmx)
        .map(|_| (0..cmx).map(|_| sc.read()).collect())
        .collect();
    let c: Vec<Vec<usize>> = (0..n)
        .map(|_| (0..n).map(|_| sc.read()).collect())
        .collect();
    let mut cnt = vec![vec![0; cmx]; 3];
    for i in 0..n {
        for j in 0..n {
            cnt[(i + j) % 3][c[i][j] - 1] += 1;
        }
    }
    let cnt = cnt;

    let mut ans = 1000 * 500 * 500;
    for i in 0..cmx {
        for j in 0..cmx {
            if i == j {
                continue;
            }
            for k in 0..cmx {
                if i == k || j == k {
                    continue;
                }
                let mut res = 0;
                for c in 0..cmx {
                    res += cnt[0][c] * d[c][i];
                }
                for c in 0..cmx {
                    res += cnt[1][c] * d[c][j];
                }
                for c in 0..cmx {
                    res += cnt[2][c] * d[c][k];
                }
                ans = std::cmp::min(ans, res);
            }
        }
    }

    format!("{}\n", ans)
}
fn main() {
    let mut buf = String::new();
    use std::io::{Read, Write};
    std::io::stdin().read_to_string(&mut buf).unwrap();
    std::io::stdout().write_all(solve(&buf).as_bytes()).unwrap();
}
struct Scanner<'a>(std::str::SplitWhitespace<'a>);
impl<'a> Scanner<'a> {
    fn from_str(src: &str) -> Scanner {
        Scanner(src.split_whitespace())
    }
    fn get(&mut self) -> &str {
        self.0.next().unwrap()
    }
    fn read<T: std::str::FromStr>(&mut self) -> T {
        self.get().parse().ok().unwrap()
    }
}
